    def _get_preview_badge_offsets_for_plate(self, plate_id: str):
        if not plate_id:
            return {}
        return self._preview_badge_offsets.setdefault(str(plate_id), {})

    def _get_preview_badge_offset(self, plate_id: str, badge_key: str):
        offsets = self._get_preview_badge_offsets_for_plate(plate_id)
        entry = offsets.get(str(badge_key), {})
        return float(entry.get("dx", 0.0)), float(entry.get("dy", 0.0))

    def _set_preview_badge_offset(self, plate_id: str, badge_key: str, dx: float, dy: float):
        offsets = self._get_preview_badge_offsets_for_plate(plate_id)
        offsets[str(badge_key)] = {"dx": float(dx), "dy": float(dy)}

    def _clamp_preview_badge_offset(self, badge_key: str, dx: float, dy: float):
        runtime = self._preview_badge_runtime.get(str(badge_key), {})
        base_left = float(runtime.get("base_left", 0.0))
        base_top = float(runtime.get("base_top", 0.0))
        badge_width = float(runtime.get("badge_width", 0.0))
        left_limit = float(runtime.get("left_limit", base_left))
        right_limit = float(runtime.get("right_limit", base_left + badge_width))
        top_limit = float(runtime.get("top_limit", 46.0))

        min_dx = left_limit - base_left
        max_dx = (right_limit - badge_width) - base_left
        if max_dx < min_dx:
            max_dx = min_dx

        dx = max(min_dx, min(max_dx, float(dx)))
        dy = max(float(top_limit) - base_top, float(dy))
        return float(dx), float(dy)

    def _clamp_preview_image_position(
        self,
        x_off: float,
        y_off: float,
        *,
        image_w: float,
        image_h: float,
        canvas_w: float,
        canvas_h: float,
        top_reserved: float,
        preferred_x: float | None = None,
        preferred_y: float | None = None,
    ):
        min_visible = 48.0
        canvas_w = max(min_visible, float(canvas_w))
        canvas_h = max(min_visible, float(canvas_h))
        image_w = max(1.0, float(image_w))
        image_h = max(1.0, float(image_h))
        top_reserved = max(0.0, float(top_reserved))
        available_h = max(min_visible, canvas_h - top_reserved)

        if image_w <= canvas_w and preferred_x is not None:
            min_x = float(preferred_x)
            max_x = float(preferred_x)
        else:
            min_x = float(min_visible) - image_w
            max_x = canvas_w - float(min_visible)
            if max_x < min_x:
                center_x = float(preferred_x) if preferred_x is not None else (canvas_w - image_w) / 2.0
                min_x = center_x
                max_x = center_x

        if image_h <= available_h and preferred_y is not None:
            min_y = float(preferred_y)
            max_y = float(preferred_y)
        else:
            min_y = top_reserved
            max_y = canvas_h - float(min_visible)
            if max_y < min_y:
                fallback_y = float(preferred_y) if preferred_y is not None else min_y
                min_y = fallback_y
                max_y = fallback_y

        x_off = max(min_x, min(max_x, float(x_off)))
        y_off = max(min_y, min(max_y, float(y_off)))
        return float(x_off), float(y_off)

    def _get_preview_canvas_size(self):
        canvas = getattr(self, "preview_canvas", None)
        if canvas is None:
            return 0.0, 0.0
        try:
            return float(max(0, int(canvas.winfo_width() or 0))), float(max(0, int(canvas.winfo_height() or 0)))
        except Exception:
            return 0.0, 0.0

    def _get_preview_mode_overlay_size(self):
        overlay = getattr(self, "preview_mode_overlay", None)
        if overlay is None:
            return 0.0, 0.0
        try:
            overlay.update_idletasks()
        except Exception:
            pass

        try:
            width = float(max(0, int(overlay.winfo_reqwidth() or overlay.winfo_width() or 0)))
            height = float(max(0, int(overlay.winfo_reqheight() or overlay.winfo_height() or 0)))
            return width, height
        except Exception:
            return 0.0, 0.0

    def _clamp_preview_mode_overlay_position(self, x: float, y: float):
        canvas_w, canvas_h = self._get_preview_canvas_size()
        overlay_w, overlay_h = self._get_preview_mode_overlay_size()
        margin = 12.0

        if canvas_w <= 0 or canvas_h <= 0:
            return float(x), float(y)

        max_x = max(margin, canvas_w - overlay_w - margin)
        max_y = max(margin, canvas_h - overlay_h - margin)
        x = max(margin, min(max_x, float(x)))
        y = max(margin, min(max_y, float(y)))
        return float(x), float(y)

    @staticmethod
    def _preview_rects_intersect(rect_a, rect_b, padding: float = 0.0) -> bool:
        if not rect_a or not rect_b:
            return False
        ax1, ay1, ax2, ay2 = [float(v) for v in rect_a]
        bx1, by1, bx2, by2 = [float(v) for v in rect_b]
        pad = max(0.0, float(padding or 0.0))
        return not (
            (ax2 + pad) <= bx1
            or (bx2 + pad) <= ax1
            or (ay2 + pad) <= by1
            or (by2 + pad) <= ay1
        )

    @staticmethod
    def _preview_rect_intersection_area(rect_a, rect_b, padding: float = 0.0) -> float:
        if not CharacterAnnotationTab._preview_rects_intersect(rect_a, rect_b, padding=padding):
            return 0.0
        ax1, ay1, ax2, ay2 = [float(v) for v in rect_a]
        bx1, by1, bx2, by2 = [float(v) for v in rect_b]
        left = max(ax1, bx1)
        top = max(ay1, by1)
        right = min(ax2, bx2)
        bottom = min(ay2, by2)
        return max(0.0, right - left) * max(0.0, bottom - top)

    def _get_preview_mode_overlay_collision_rects(self):
        canvas_w, canvas_h = self._get_preview_canvas_size()
        if canvas_w <= 0.0 or canvas_h <= 0.0:
            return []

        reserved_rects = []
        if bool(getattr(self, "_preview_render_state", None)):
            top_bar_height = max(38.0, float(getattr(self, "_preview_overlay_top_bar_height", 38.0) or 38.0))
            reserved_rects.append((0.0, 0.0, float(canvas_w), top_bar_height))

        if bool(getattr(self, "_preview_fullscreen_active", False)):
            legend_canvas = getattr(self, "preview_controls_canvas", None)
            legend_height = 0.0
            if legend_canvas is not None:
                try:
                    legend_canvas.update_idletasks()
                except Exception:
                    pass
                try:
                    legend_height = float(max(0, int(legend_canvas.winfo_height() or 0)))
                except Exception:
                    legend_height = 0.0
            if legend_height > 0.0:
                reserved_rects.append((0.0, max(0.0, float(canvas_h) - legend_height - 14.0), float(canvas_w), float(canvas_h)))

        return reserved_rects

    def _resolve_preview_mode_overlay_collision_position(self, x: float, y: float):
        clamped_x, clamped_y = self._clamp_preview_mode_overlay_position(x, y)
        overlay_w, overlay_h = self._get_preview_mode_overlay_size()
        canvas_w, canvas_h = self._get_preview_canvas_size()
        reserved_rects = self._get_preview_mode_overlay_collision_rects()
        margin = 12.0

        if overlay_w <= 0.0 or overlay_h <= 0.0 or canvas_w <= 0.0 or canvas_h <= 0.0 or not reserved_rects:
            return float(clamped_x), float(clamped_y)

        top_block_bottom = 0.0
        bottom_block_top = float(canvas_h)
        for rect in reserved_rects:
            _left, top, _right, bottom = [float(v) for v in rect]
            if top <= (margin + 2.0):
                top_block_bottom = max(top_block_bottom, bottom)
            if bottom >= (float(canvas_h) - margin - 2.0):
                bottom_block_top = min(bottom_block_top, top)

        candidate_positions = [
            (clamped_x, clamped_y),
            (float(canvas_w) - overlay_w - margin, max(margin, top_block_bottom + 8.0)),
            (margin, max(margin, top_block_bottom + 8.0)),
            (float(canvas_w) - overlay_w - margin, min(max(margin, bottom_block_top - overlay_h - 8.0), float(canvas_h) - overlay_h - margin)),
            (margin, min(max(margin, bottom_block_top - overlay_h - 8.0), float(canvas_h) - overlay_h - margin)),
        ]

        unique_candidates = []
        seen = set()
        for candidate_x, candidate_y in candidate_positions:
            safe_x, safe_y = self._clamp_preview_mode_overlay_position(candidate_x, candidate_y)
            key = (round(float(safe_x), 1), round(float(safe_y), 1))
            if key in seen:
                continue
            seen.add(key)
            unique_candidates.append((float(safe_x), float(safe_y)))

        best_candidate = (float(clamped_x), float(clamped_y))
        best_overlap = None
        for candidate_x, candidate_y in unique_candidates:
            candidate_rect = (
                float(candidate_x),
                float(candidate_y),
                float(candidate_x) + float(overlay_w),
                float(candidate_y) + float(overlay_h),
            )
            overlap_area = sum(
                self._preview_rect_intersection_area(candidate_rect, reserved_rect, padding=2.0)
                for reserved_rect in reserved_rects
            )
            if overlap_area <= 0.0:
                return float(candidate_x), float(candidate_y)
            if best_overlap is None or overlap_area < best_overlap:
                best_overlap = float(overlap_area)
                best_candidate = (float(candidate_x), float(candidate_y))

        return best_candidate

    def _get_preview_mode_overlay_default_position(self, *, fullscreen: bool = False):
        if bool(fullscreen):
            top_bar_height = max(38.0, float(getattr(self, "_preview_overlay_top_bar_height", 38.0) or 38.0))
            return {"x": 12.0, "y": float(top_bar_height + 8.0)}

        canvas_w, _canvas_h = self._get_preview_canvas_size()
        overlay_w, _overlay_h = self._get_preview_mode_overlay_size()
        desired_x = max(12.0, canvas_w - overlay_w - 12.0)
        return {"x": float(desired_x), "y": 12.0}

    def _ensure_preview_mode_overlay_position(self):
        overlay = getattr(self, "preview_mode_overlay", None)
        canvas = getattr(self, "preview_canvas", None)
        if overlay is None or canvas is None:
            return

        current = getattr(self, "_preview_mode_overlay_position", None)
        if not isinstance(current, dict):
            current = self._get_preview_mode_overlay_default_position(
                fullscreen=bool(getattr(self, "_preview_fullscreen_active", False))
            )

        if bool(getattr(self, "_preview_fullscreen_active", False)):
            clamped_x, clamped_y = self._clamp_preview_mode_overlay_position(
                current.get("x", 12.0),
                current.get("y", 12.0),
            )
        else:
            clamped_x, clamped_y = self._resolve_preview_mode_overlay_collision_position(
                current.get("x", 12.0),
                current.get("y", 12.0),
            )
        self._preview_mode_overlay_position = {"x": float(clamped_x), "y": float(clamped_y)}

        try:
            overlay.place(in_=canvas, x=clamped_x, y=clamped_y, anchor="nw")
            overlay.lift()
        except Exception:
            pass

    def _focus_preview_canvas(self):
        canvas = getattr(self, "preview_canvas", None)
        if canvas is None:
            return
        try:
            canvas.focus_set()
        except Exception:
            pass

    def _resolve_preview_canvas_cursor(self) -> str:
        if not bool(getattr(self, "_preview_render_state", None)):
            return "arrow"
        if getattr(self, "_preview_badge_drag_state", None) is not None:
            return "hand2"
        char_drag_state = getattr(self, "_preview_char_drag_state", None)
        if isinstance(char_drag_state, dict):
            mode = str(char_drag_state.get("mode", "move") or "move").lower()
            return "crosshair" if mode == "resize" else "fleur"
        if getattr(self, "_preview_pan_drag_state", None) is not None:
            return "fleur"
        if self._preview_char_add_requested():
            return "crosshair"
        return "arrow"

    def _apply_preview_canvas_cursor(self, cursor: str | None = None):
        canvas = getattr(self, "preview_canvas", None)
        if canvas is None:
            return
        desired = str(cursor or self._resolve_preview_canvas_cursor() or "arrow")
        try:
            current = str(canvas.cget("cursor") or "")
        except Exception:
            current = ""
        if current == desired:
            return
        try:
            canvas.configure(cursor=desired)
        except Exception:
            pass

    def _on_preview_canvas_enter(self, event=None):
        self._focus_preview_canvas()
        self._apply_preview_canvas_cursor()
        return None

    def _preview_canvas_to_image_point(self, canvas_x: float, canvas_y: float):
        state = getattr(self, "_preview_render_state", None) or {}
        scale = max(0.001, float(state.get("scale", 0.0) or 0.0))
        image_left = float(state.get("image_left", 0.0))
        image_top = float(state.get("image_top", 0.0))
        orig_w = max(1.0, float(state.get("orig_w", 1.0)))
        orig_h = max(1.0, float(state.get("orig_h", 1.0)))

        img_x = (float(canvas_x) - image_left) / scale
        img_y = (float(canvas_y) - image_top) / scale
        img_x = max(0.0, min(orig_w, img_x))
        img_y = max(0.0, min(orig_h, img_y))
        return float(img_x), float(img_y)

    def _preview_image_to_canvas_point(self, img_x: float, img_y: float):
        state = getattr(self, "_preview_render_state", None) or {}
        scale = max(0.001, float(state.get("scale", 0.0) or 0.0))
        image_left = float(state.get("image_left", 0.0))
        image_top = float(state.get("image_top", 0.0))
        return (
            (float(img_x) * scale) + image_left,
            (float(img_y) * scale) + image_top,
        )

    def _preview_point_inside_image(self, canvas_x: float, canvas_y: float) -> bool:
        state = getattr(self, "_preview_render_state", None) or {}
        return bool(
            float(state.get("image_left", 0.0)) <= float(canvas_x) <= float(state.get("image_right", -1.0))
            and float(state.get("image_top", 0.0)) <= float(canvas_y) <= float(state.get("image_bottom", -1.0))
        )

    def _get_preview_metadata_path(self) -> Path | None:
        preview_dir_raw = str(getattr(self, "preview_dir_var", None).get() if hasattr(self, "preview_dir_var") else "").strip()
        if not preview_dir_raw:
            return None
        return Path(preview_dir_raw) / "metadata.json"

    def _get_preview_active_data(self, create: bool = False):
        pid = str(getattr(self, "_preview_active_pid", "") or "")
        if not pid:
            return None
        if create:
            return self.preview_metadata.setdefault(pid, {})
        return self.preview_metadata.get(pid)

    def _get_preview_active_character_records(self, create: bool = False):
        data = self._get_preview_active_data(create=create)
        if not isinstance(data, dict):
            return []
        chars = data.get("characters")
        if isinstance(chars, list):
            return chars
        if create:
            data["characters"] = []
            return data["characters"]
        return []

    def _get_preview_source_filename(self, data: dict | None = None) -> str:
        source_data = data if isinstance(data, dict) else self._get_preview_active_data(create=False)
        if not isinstance(source_data, dict):
            return ""

        source_image = str(source_data.get("source_image", "") or "").strip()
        if source_image:
            return Path(source_image).name

        for field_name in ("filename", "source_name"):
            candidate = str(source_data.get(field_name, "") or "").strip()
            if candidate:
                return Path(candidate).name
        return ""

    @staticmethod
    def _normalize_preview_source_path_key(raw_value: str) -> str:
        text = str(raw_value or "").strip()
        if not text:
            return ""
        try:
            path_obj = Path(text)
            if path_obj.exists():
                try:
                    return path_obj.resolve().as_posix().lower()
                except Exception:
                    return path_obj.absolute().as_posix().lower()
            if path_obj.is_absolute():
                try:
                    return path_obj.absolute().as_posix().lower()
                except Exception:
                    pass
        except Exception:
            pass
        return text.replace("\\", "/").lower()

    def _resolve_preview_source_image_path(self, data: dict | None = None) -> Path | None:
        source_data = data if isinstance(data, dict) else self._get_preview_active_data(create=False)
        if not isinstance(source_data, dict):
            return None

        candidate_paths = []
        images_dir_raw = str(self.images_dir_var.get() or "").strip() if hasattr(self, "images_dir_var") else ""
        raw_dir_raw = ""
        try:
            raw_dir_raw = str(CAMPAIGN.get_dir("raw") or "").strip()
        except Exception:
            raw_dir_raw = ""

        for field_name in ("source_image", "filename", "source_name"):
            raw_value = str(source_data.get(field_name, "") or "").strip()
            if not raw_value:
                continue
            raw_path = Path(raw_value)
            candidate_paths.append(raw_path)
            if not raw_path.is_absolute():
                if images_dir_raw:
                    candidate_paths.append(Path(images_dir_raw) / raw_path.name)
                if raw_dir_raw:
                    candidate_paths.append(Path(raw_dir_raw) / raw_path.name)

        seen = set()
        first_candidate = None
        for candidate in candidate_paths:
            normalized = self._normalize_preview_source_path_key(str(candidate))
            if not normalized or normalized in seen:
                continue
            seen.add(normalized)
            if first_candidate is None:
                first_candidate = candidate
            try:
                if candidate.exists() and candidate.is_file():
                    try:
                        return candidate.resolve()
                    except Exception:
                        return candidate.absolute()
            except Exception:
                continue

        if first_candidate is None:
            return None
        try:
            return first_candidate.absolute()
        except Exception:
            return first_candidate

    def _build_preview_plate_reextract_match_key(self, data: dict | None = None) -> str:
        source_data = data if isinstance(data, dict) else {}
        if not isinstance(source_data, dict):
            return ""

        source_key = self._normalize_preview_source_path_key(
            str(source_data.get("source_image", "") or source_data.get("source_name", "") or source_data.get("filename", "") or "").strip()
        )
        if not source_key:
            return ""

        bbox = list(source_data.get("source_bbox") or [])
        if len(bbox) >= 4:
            try:
                bbox_key = ":".join(str(int(round(float(value)))) for value in bbox[:4])
            except Exception:
                bbox_key = ":".join(str(value) for value in bbox[:4])
        else:
            bbox_key = ""

        return f"{source_key}|{bbox_key}"

    def _capture_preview_reextract_seed_metadata(self) -> dict:
        seed_source = {}
        preview_dir = None
        if isinstance(getattr(self, "preview_metadata", None), dict) and self.preview_metadata:
            seed_source = copy.deepcopy(self.preview_metadata)
            try:
                preview_dir_raw = str(self.preview_dir_var.get() or "").strip()
                preview_dir = Path(preview_dir_raw) if preview_dir_raw else None
            except Exception:
                preview_dir = None
        else:
            preview_dir_raw = str(self.preview_dir_var.get() or "").strip()
            if preview_dir_raw:
                meta_path = Path(preview_dir_raw) / "metadata.json"
                seed_source = self._load_json_file_safely(meta_path)
                preview_dir = Path(preview_dir_raw)

        if not isinstance(seed_source, dict):
            return {}

        seed_lookup: dict[str, dict] = {}
        for _pid, raw_data in seed_source.items():
            if not isinstance(raw_data, dict):
                continue
            match_key = self._build_preview_plate_reextract_match_key(raw_data)
            if not match_key or match_key in seed_lookup:
                continue
            seed_payload = copy.deepcopy(raw_data)
            try:
                seed_size = self._get_preview_plate_image_size(preview_dir, str(_pid or "").strip())
            except Exception:
                seed_size = None
            if seed_size:
                seed_payload["_seed_image_size"] = [int(seed_size[0]), int(seed_size[1])]
            seed_lookup[match_key] = seed_payload
        return seed_lookup

    @staticmethod
    def _preview_plate_has_renderable_boxes(data: dict | None) -> bool:
        if not isinstance(data, dict):
            return False
        for key_name in ("characters", "yolo_detections", "yolo_nms_detections", "yolo_raw_detections"):
            values = data.get(key_name)
            if isinstance(values, list) and len(values) > 0:
                return True
        return False

    def _collect_historical_preview_reextract_seed_metadata(self, current_preview_dir: Path | None = None) -> dict:
        run_root = None
        if current_preview_dir is not None:
            try:
                run_root = Path(current_preview_dir).parent
            except Exception:
                run_root = None
        if run_root is None:
            try:
                run_root = self._get_step3_chars_root_dir(ensure_exists=False)
            except Exception:
                run_root = None
        if run_root is None or not Path(run_root).exists():
            return {}

        current_meta = None
        if current_preview_dir is not None:
            try:
                current_meta = Path(current_preview_dir) / "metadata.json"
            except Exception:
                current_meta = None

        try:
            meta_files = sorted(
                (
                    path for path in Path(run_root).rglob("metadata.json")
                    if current_meta is None or path != current_meta
                ),
                key=lambda path: path.stat().st_mtime,
                reverse=True,
            )
        except Exception:
            return {}

        seed_lookup: dict[str, dict] = {}
        for meta_path in meta_files:
            metadata = self._load_json_file_safely(meta_path)
            if not isinstance(metadata, dict) or not metadata:
                continue
            for _pid, raw_data in metadata.items():
                if not isinstance(raw_data, dict) or not self._preview_plate_has_renderable_boxes(raw_data):
                    continue
                match_key = self._build_preview_plate_reextract_match_key(raw_data)
                if not match_key or match_key in seed_lookup:
                    continue
                seed_payload = copy.deepcopy(raw_data)
                try:
                    seed_size = self._get_preview_plate_image_size(meta_path.parent, str(_pid or "").strip())
                except Exception:
                    seed_size = None
                if seed_size:
                    seed_payload["_seed_image_size"] = [int(seed_size[0]), int(seed_size[1])]
                seed_lookup[match_key] = seed_payload
            if seed_lookup:
                # najnowszy sensowny run zwykle wystarcza; jeśli już coś znaleźliśmy,
                # nie schodzimy dalej, żeby nie mieszać bardzo starych poprawek.
                break
        return seed_lookup

    def _scale_preview_char_records_to_new_size(self, records, from_size, to_size):
        if not isinstance(records, list):
            return copy.deepcopy(records)
        try:
            from_w, from_h = (float(from_size[0]), float(from_size[1]))
            to_w, to_h = (float(to_size[0]), float(to_size[1]))
        except Exception:
            return copy.deepcopy(records)

        if from_w <= 0 or from_h <= 0 or to_w <= 0 or to_h <= 0:
            return copy.deepcopy(records)

        scale_x = to_w / from_w
        scale_y = to_h / from_h
        scaled_records = []
        for rec in list(records or []):
            cloned = copy.deepcopy(rec)
            bbox = self._char_record_bbox(cloned)
            if not bbox:
                scaled_records.append(cloned)
                continue
            x1, y1, x2, y2 = bbox
            scaled_bbox = [
                max(0.0, min(to_w, float(x1) * scale_x)),
                max(0.0, min(to_h, float(y1) * scale_y)),
                max(0.0, min(to_w, float(x2) * scale_x)),
                max(0.0, min(to_h, float(y2) * scale_y)),
            ]
            if scaled_bbox[2] < scaled_bbox[0]:
                scaled_bbox[0], scaled_bbox[2] = scaled_bbox[2], scaled_bbox[0]
            if scaled_bbox[3] < scaled_bbox[1]:
                scaled_bbox[1], scaled_bbox[3] = scaled_bbox[3], scaled_bbox[1]
            if isinstance(cloned, dict):
                cloned["bbox"] = [float(v) for v in scaled_bbox]
            else:
                try:
                    cloned.bbox = tuple(float(v) for v in scaled_bbox)
                except Exception:
                    pass
            scaled_records.append(cloned)
        return scaled_records

    def _adapt_reextract_seed_payload_to_current_preview(self, previous: dict, preview_dir: Path, pid: str) -> dict:
        adapted = copy.deepcopy(previous)
        from_size = adapted.get("_seed_image_size")
        to_size = self._get_preview_plate_image_size(preview_dir, pid)
        if from_size and to_size and list(from_size) != [int(to_size[0]), int(to_size[1])]:
            for key_name in ("characters", "yolo_detections", "yolo_nms_detections", "yolo_raw_detections"):
                if key_name in adapted:
                    adapted[key_name] = self._scale_preview_char_records_to_new_size(
                        adapted.get(key_name),
                        from_size,
                        to_size,
                    )
        adapted.pop("_seed_image_size", None)
        return adapted

    def _merge_reextract_seed_metadata_into_preview(self, preview_dir: Path | None, seed_lookup: dict | None = None) -> dict:
        if preview_dir is None:
            return {"matched": 0, "total": 0}

        meta_path = Path(preview_dir) / "metadata.json"
        if not meta_path.exists():
            return {"matched": 0, "total": 0}

        previous_lookup = dict(seed_lookup or getattr(self, "_campaign_step3_reextract_seed_metadata", {}) or {})
        if not previous_lookup or not any(self._preview_plate_has_renderable_boxes(item) for item in previous_lookup.values()):
            previous_lookup = self._collect_historical_preview_reextract_seed_metadata(preview_dir)
        if not previous_lookup:
            return {"matched": 0, "total": 0}

        metadata = self._load_json_file_safely(meta_path)
        if not isinstance(metadata, dict) or not metadata:
            return {"matched": 0, "total": 0}

        preserve_keys = (
            "characters",
            "status",
            "fusion_strategy",
            "fusion_details",
            "source_info",
            "gold_state",
            "yolo_detections",
            "yolo_nms_detections",
            "yolo_raw_detections",
        )

        matched = 0
        for pid, raw_data in list(metadata.items()):
            if not isinstance(raw_data, dict):
                continue
            match_key = self._build_preview_plate_reextract_match_key(raw_data)
            if not match_key:
                continue
            previous = previous_lookup.get(match_key)
            if not isinstance(previous, dict):
                continue
            previous = self._adapt_reextract_seed_payload_to_current_preview(
                previous,
                Path(preview_dir),
                str(pid or "").strip(),
            )
            for key_name in preserve_keys:
                if key_name in previous:
                    raw_data[key_name] = copy.deepcopy(previous.get(key_name))
            self._ensure_plate_source_metadata(raw_data, plate_id=str(pid or ""), meta_path=meta_path)
            matched += 1

        metadata = self._recalculate_preview_statuses_in_metadata(metadata)
        self._atomic_write_json(meta_path, metadata)
        return {"matched": int(matched), "total": int(len(metadata))}

    @staticmethod
    def _replace_preview_source_filename(raw_value: str, new_filename: str) -> str:
        raw_text = str(raw_value or "").strip()
        safe_name = str(new_filename or "").strip()
        if not raw_text:
            return safe_name
        for separator in ("\\", "/"):
            if separator in raw_text:
                prefix = raw_text.rsplit(separator, 1)[0]
                return f"{prefix}{separator}{safe_name}" if prefix else safe_name
        return safe_name

    def _sanitize_preview_char_symbol(self, value) -> str:
        text = str(value or "").strip().upper()
        if not text:
            return ""
        if len(text) == 1 and text in CHAR_CLASS_ALPHABET:
            return text
        return ""

    def _normalize_preview_char_bbox(self, bbox, *, min_size: float = 4.0):
        if not isinstance(bbox, (list, tuple)) or len(bbox) < 4:
            return None
        try:
            x1, y1, x2, y2 = (float(v) for v in bbox[:4])
        except Exception:
            return None
        if x2 < x1:
            x1, x2 = x2, x1
        if y2 < y1:
            y1, y2 = y2, y1

        state = getattr(self, "_preview_render_state", None) or {}
        max_w = max(1.0, float(state.get("orig_w", 1.0)))
        max_h = max(1.0, float(state.get("orig_h", 1.0)))
        x1 = max(0.0, min(max_w, x1))
        y1 = max(0.0, min(max_h, y1))
        x2 = max(0.0, min(max_w, x2))
        y2 = max(0.0, min(max_h, y2))

        if x2 - x1 < float(min_size):
            if x1 + float(min_size) <= max_w:
                x2 = x1 + float(min_size)
            else:
                x1 = max(0.0, x2 - float(min_size))
        if y2 - y1 < float(min_size):
            if y1 + float(min_size) <= max_h:
                y2 = y1 + float(min_size)
            else:
                y1 = max(0.0, y2 - float(min_size))

        return [float(x1), float(y1), float(x2), float(y2)]

    def _mark_preview_char_record_manual(self, rec: dict):
        if not isinstance(rec, dict):
            return
        rec["method"] = "manual"
        rec["source_tag"] = "manual"
        rec["source_kind"] = "local_manual"
        try:
            rec["confidence"] = float(rec.get("confidence", 1.0) or 1.0)
        except Exception:
            rec["confidence"] = 1.0

    def _derive_preview_status_from_characters(self, chars) -> str:
        if not isinstance(chars, list) or not chars:
            return "needs_fix"
        valid_count = 0
        for rec in chars:
            symbol = ""
            if isinstance(rec, dict):
                symbol = rec.get("character", "")
            else:
                symbol = getattr(rec, "character", "")
            symbol = self._sanitize_preview_char_symbol(symbol)
            if symbol:
                valid_count += 1
        return "perfect" if valid_count == len(chars) and valid_count > 0 else "needs_fix"

    def _preview_has_reference_text_source(self, data: dict | None = None) -> bool:
        source_data = data if isinstance(data, dict) else self._get_preview_active_data(create=False)
        return any(bool(value) for value in self._get_preview_reference_text_values(source_data))

    def _get_preview_reference_text_values(self, data: dict | None = None) -> list[str]:
        source_data = data if isinstance(data, dict) else self._get_preview_active_data(create=False)
        if not isinstance(source_data, dict):
            return []
        values = []
        for field_name in ("source_image", "source_name", "filename"):
            prepared = str(source_data.get(field_name, "") or "").strip()
            if prepared:
                values.append(prepared)
        return values

    def _get_preview_expected_texts(self, data: dict | None = None) -> list[str]:
        source_data = data if isinstance(data, dict) else self._get_preview_active_data(create=False)
        normalized = []
        seen = set()
        for candidate in self._get_preview_reference_text_values(source_data):
            if not candidate:
                continue
            for item in self._get_true_texts_from_filename(candidate):
                prepared = str(item or "").strip().upper()
                if not prepared or prepared in seen:
                    continue
                seen.add(prepared)
                normalized.append(prepared)
        return normalized

    def _derive_preview_status_from_data(self, data: dict | None, chars) -> str:
        base_status = self._derive_preview_status_from_characters(chars)
        if base_status != "perfect":
            return base_status

        expected_texts = self._get_preview_expected_texts(data)
        if not expected_texts:
            if self._preview_has_reference_text_source(data):
                return "needs_fix"
            return base_status

        candidate_text = self._characters_to_text(chars).strip().upper()
        if candidate_text and candidate_text in expected_texts:
            return "perfect"
        return "needs_fix"

    def _get_preview_live_status(self, data: dict | None = None, chars=None, plate_id: str | None = None) -> str:
        source_data = data if isinstance(data, dict) else self._get_preview_active_data(create=False)
        if not isinstance(source_data, dict):
            return str((data or {}).get("status", "unknown") or "unknown").strip().lower() if isinstance(data, dict) else "unknown"

        probe = dict(source_data)
        resolved_plate_id = str(plate_id or getattr(self, "_preview_active_pid", "") or probe.get("plate_id", "") or "").strip()
        if resolved_plate_id:
            probe["plate_id"] = resolved_plate_id

        source_chars = chars
        if source_chars is None:
            source_chars = probe.get("characters", [])
        return str(self._derive_preview_status_from_data(probe, source_chars) or "unknown").strip().lower()

    def _get_preview_status_presentation(self, data: dict | None = None, chars=None, plate_id: str | None = None) -> dict:
        source_data = data if isinstance(data, dict) else self._get_preview_active_data(create=False)
        source_chars = chars if isinstance(chars, list) else (
            source_data.get("characters", []) if isinstance(source_data, dict) else []
        )
        status = self._get_preview_live_status(data=source_data, chars=source_chars, plate_id=plate_id)
        expected_texts = self._get_preview_expected_texts(source_data if isinstance(source_data, dict) else None)

        total_boxes = len(source_chars) if isinstance(source_chars, list) else 0
        filled_boxes = 0
        if isinstance(source_chars, list):
            for rec in source_chars:
                symbol = ""
                if isinstance(rec, dict):
                    symbol = rec.get("character", "")
                else:
                    symbol = getattr(rec, "character", "")
                if self._sanitize_preview_char_symbol(symbol):
                    filled_boxes += 1

        candidate_text = self._characters_to_text(source_chars).strip().upper()
        severity = "muted"
        canvas_text = "Nieocenione"
        info_text = "status: nieoceniona"

        if status == "perfect":
            severity = "success"
            canvas_text = "Perfect"
            info_text = "status: OK"
        elif total_boxes <= 0:
            severity = "warning"
            canvas_text = "Brak boxow"
            info_text = "status: brak boxow"
        elif filled_boxes < total_boxes:
            severity = "warning"
            canvas_text = f"Niepelne {filled_boxes}/{total_boxes}"
            info_text = f"status: niepelne {filled_boxes}/{total_boxes}"
        elif expected_texts:
            expected_lengths = [len(str(text or "").strip().upper()) for text in expected_texts if str(text or "").strip()]
            target_len = min(expected_lengths, key=lambda value: abs(int(value) - int(total_boxes))) if expected_lengths else None
            if target_len is not None and int(total_boxes) != int(target_len):
                severity = "warning"
                canvas_text = f"Boxy {total_boxes}/{int(target_len)}"
                info_text = f"status: boxy {total_boxes}/{int(target_len)}"
            elif candidate_text:
                severity = "error"
                canvas_text = "Do korekty"
                info_text = "status: wymaga korekty"
            else:
                severity = "warning"
                canvas_text = "Brak znaków"
                info_text = "status: brak znaków"
        elif candidate_text:
            severity = "warning"
            canvas_text = "Bez wzorca"
            info_text = "status: brak wzorca"

        return {
            "status": status,
            "severity": severity,
            "canvas_text": canvas_text,
            "info_text": info_text,
            "candidate_text": candidate_text,
            "expected_texts": list(expected_texts or []),
            "filled_boxes": int(filled_boxes),
            "total_boxes": int(total_boxes),
        }

    def _recalculate_preview_statuses_in_metadata(self, metadata: dict | None):
        if not isinstance(metadata, dict):
            return metadata

        for plate_id, raw_data in list(metadata.items()):
            if not isinstance(raw_data, dict):
                continue
            self._ensure_plate_source_metadata(raw_data, plate_id=str(plate_id or ""))
            chars = raw_data.get("characters", None)
            if not isinstance(chars, list):
                continue
            if not chars:
                raw_data["status"] = "needs_fix"
                continue

            status_probe = dict(raw_data)
            status_probe["plate_id"] = str(plate_id)
            raw_data["status"] = self._derive_preview_status_from_data(status_probe, chars)

        return metadata

    def _persist_preview_metadata(self, *, success_message: str | None = None, refresh_list: bool = True):
        meta_path = self._get_preview_metadata_path()
        if meta_path is None:
            raise RuntimeError("Brak aktywnej paczki preview do zapisania.")

        self._atomic_write_json(meta_path, self.preview_metadata)
        self._loaded_meta_path = meta_path
        try:
            self._loaded_meta_mtime = meta_path.stat().st_mtime
        except Exception:
            self._loaded_meta_mtime = None

        if refresh_list:
            self._refresh_listbox_rows_from_metadata()
        self._sync_step3_access_from_preview_state(self.preview_metadata)
        if success_message:
            self._set_preview_box_info(success_message, "success")

    def _clone_preview_plate_data(self, plate_id: str | None = None):
        pid = str(plate_id or getattr(self, "_preview_active_pid", "") or "").strip()
        if not pid:
            return None
        data = self.preview_metadata.get(pid)
        return copy.deepcopy(data if isinstance(data, dict) else {})

    def _get_preview_history_stack(self, kind: str, plate_id: str | None = None, create: bool = False):
        pid = str(plate_id or getattr(self, "_preview_active_pid", "") or "").strip()
        if not pid:
            return None
        store_attr = "_preview_history_undo" if str(kind).lower() == "undo" else "_preview_history_redo"
        store = getattr(self, store_attr, None)
        if not isinstance(store, dict):
            store = {}
            setattr(self, store_attr, store)
        if create:
            return store.setdefault(pid, [])
        return store.get(pid)

    def _push_preview_history_snapshot(self, plate_id: str | None = None):
        if bool(getattr(self, "_preview_history_replaying", False)):
            return
        pid = str(plate_id or getattr(self, "_preview_active_pid", "") or "").strip()
        if not pid:
            return
        snapshot = self._clone_preview_plate_data(pid)
        if snapshot is None:
            return

        undo_stack = self._get_preview_history_stack("undo", pid, create=True)
        if isinstance(undo_stack, list) and undo_stack and undo_stack[-1] == snapshot:
            return

        undo_stack.append(snapshot)
        limit = max(10, int(getattr(self, "_preview_history_limit", 80) or 80))
        if len(undo_stack) > limit:
            del undo_stack[:-limit]

        redo_stack = self._get_preview_history_stack("redo", pid, create=True)
        if isinstance(redo_stack, list):
            redo_stack.clear()

    def _refresh_preview_listbox_row(self, plate_id: str | None = None):
        pid = str(plate_id or getattr(self, "_preview_active_pid", "") or "").strip()
        listbox = getattr(self, "plates_listbox", None)
        if not pid or listbox is None:
            return
        pid_map = getattr(self, "_listbox_pid_by_index", [])
        try:
            row_index = pid_map.index(pid)
        except Exception:
            return

        data = self.preview_metadata.get(pid, {})
        status = str(data.get("status", "unknown")).strip().lower()
        label = self._format_plate_listbox_label(pid, data)

        try:
            selected_rows = {int(idx) for idx in listbox.curselection()}
        except Exception:
            selected_rows = set()
        try:
            active_row = int(listbox.index(tk.ACTIVE))
        except Exception:
            active_row = None
        row_selected = row_index in selected_rows

        try:
            listbox.delete(row_index)
            listbox.insert(row_index, label)
            self._apply_plate_listbox_row_style(row_index, status)
            if row_selected:
                listbox.selection_set(row_index)
            if active_row == row_index:
                listbox.activate(row_index)
            if row_selected or active_row == row_index:
                listbox.see(row_index)
        except Exception as exc:
            logger.debug(f"Nie udało się odświeżyć pojedynczego wiersza listy tablic [{pid}]: {exc}")

    def _refresh_preview_live_metadata_ui(self, *, status_message: str | None = None, status_tone: str = "muted", render_preview: bool = True):
        pid = str(getattr(self, "_preview_active_pid", "") or "").strip()
        data = self._get_preview_active_data(create=False)
        if pid and isinstance(data, dict):
            self._refresh_preview_listbox_row(pid)
            self._update_preview_info_label()

            box_chars, box_source = self._get_preview_box_records(data)
            yolo_variants = self._get_preview_box_variants(data)
            self._update_preview_box_info_label(
                plate_id=pid,
                mode_key=box_source,
                shown_count=len(box_chars),
                yolo_raw_count=len(yolo_variants.get("YOLO_RAW", [])),
                yolo_nms_count=len(yolo_variants.get("YOLO_NMS", [])),
                yolo_filtered_count=len(yolo_variants.get("YOLO_FILTERED", [])),
            )
            self._sync_step3_access_from_preview_state(self.preview_metadata)

        self._refresh_preview_editor_toolbar()
        if status_message:
            self._update_preview_edit_status(status_message, tone=status_tone)
        else:
            self._update_preview_edit_status()
        if render_preview:
            self._on_preview_select(None)
        self._focus_preview_canvas()

    def _restore_preview_plate_history_snapshot(self, snapshot, *, action_label: str):
        pid = str(getattr(self, "_preview_active_pid", "") or "").strip()
        if not pid:
            return False

        self._preview_history_replaying = True
        try:
            self.preview_metadata[pid] = copy.deepcopy(snapshot if isinstance(snapshot, dict) else {})
            self._preview_char_selected_index = None
            self._preview_char_drag_state = None
            self._preview_char_add_state = None
            self._preview_char_hover_index = None
            self._preview_char_hover_label_index = None
            self._preview_char_label_active_index = None
            self._refresh_preview_live_metadata_ui(
                status_message=action_label,
                status_tone="info",
                render_preview=True,
            )
            self.frame.update_idletasks()
            self._persist_preview_metadata(success_message=None, refresh_list=False)
            return True
        finally:
            self._preview_history_replaying = False

    def _undo_preview_edit(self, event=None):
        pid = str(getattr(self, "_preview_active_pid", "") or "").strip()
        undo_stack = self._get_preview_history_stack("undo", pid, create=False)
        if not pid or not isinstance(undo_stack, list) or not undo_stack:
            self._update_preview_edit_status("Brak zmian do cofniecia.", tone="warning")
            return "break"

        current_snapshot = self._clone_preview_plate_data(pid)
        redo_stack = self._get_preview_history_stack("redo", pid, create=True)
        if current_snapshot is not None:
            redo_stack.append(current_snapshot)

        target_snapshot = undo_stack.pop()
        self._restore_preview_plate_history_snapshot(target_snapshot, action_label="Cofnieto ostatnia zmiane boxow znaków.")
        return "break"

    def _redo_preview_edit(self, event=None):
        pid = str(getattr(self, "_preview_active_pid", "") or "").strip()
        redo_stack = self._get_preview_history_stack("redo", pid, create=False)
        if not pid or not isinstance(redo_stack, list) or not redo_stack:
            self._update_preview_edit_status("Brak zmian do ponowienia.", tone="warning")
            return "break"

        current_snapshot = self._clone_preview_plate_data(pid)
        undo_stack = self._get_preview_history_stack("undo", pid, create=True)
        if current_snapshot is not None:
            undo_stack.append(current_snapshot)

        target_snapshot = redo_stack.pop()
        self._restore_preview_plate_history_snapshot(target_snapshot, action_label="Przywrócono ostatnia cofnięta zmiane boxow znaków.")
        return "break"

    @staticmethod
    def _event_has_control_modifier(event=None) -> bool:
        if event is None:
            return False
        try:
            return bool(int(getattr(event, "state", 0) or 0) & 0x4)
        except Exception:
            return False

    @staticmethod
    def _event_has_shift_modifier(event=None) -> bool:
        if event is None:
            return False
        try:
            return bool(int(getattr(event, "state", 0) or 0) & 0x1)
        except Exception:
            return False

    @staticmethod
    def _event_has_alt_modifier(event=None) -> bool:
        if event is None:
            return False
        try:
            state = int(getattr(event, "state", 0) or 0)
        except Exception:
            return False
        return bool(state & 0x8 or state & 0x20000)

    @staticmethod
    def _pane_has_child(pane, child) -> bool:
        if pane is None or child is None:
            return False
        try:
            return str(child) in {str(item) for item in pane.panes()}
        except Exception:
            return False

    def _get_current_preview_list_index(self):
        listbox = getattr(self, "plates_listbox", None)
        if listbox is None:
            return None
        try:
            sel = listbox.curselection()
            if sel:
                idx = int(sel[0])
                if 0 <= idx < len(getattr(self, "_listbox_pid_by_index", [])):
                    return idx
        except Exception:
            pass
        try:
            idx = int(listbox.index(tk.ACTIVE))
            if 0 <= idx < len(getattr(self, "_listbox_pid_by_index", [])):
                return idx
        except Exception:
            pass
        return None

    @staticmethod
    def _clear_listbox_selection_fast(listbox) -> None:
        if listbox is None:
            return
        try:
            selected_indices = list(listbox.curselection() or ())
        except Exception:
            selected_indices = []
        for selected_index in selected_indices:
            try:
                listbox.selection_clear(selected_index)
            except Exception:
                pass

    def _on_preview_list_mouse_primary(self, event):
        try:
            self.plates_listbox.focus_set()
        except Exception:
            pass
        try:
            modifier_state = int(getattr(event, "state", 0) or 0)
        except Exception:
            modifier_state = 0

        try:
            target_index = int(self.plates_listbox.nearest(getattr(event, "y", 0)))
        except Exception:
            return None

        try:
            size = int(self.plates_listbox.size() or 0)
        except Exception:
            size = 0
        if size <= 0 or target_index < 0 or target_index >= size:
            return "break"

        shift_pressed = bool(modifier_state & 0x0001)
        control_pressed = bool(modifier_state & 0x0004)
        preserve_index = self._get_current_preview_list_index()
        if preserve_index is not None and not (0 <= int(preserve_index) < size):
            preserve_index = None
        preserve_preview = False

        try:
            if shift_pressed:
                try:
                    anchor_index = int(self.plates_listbox.index(tk.ANCHOR))
                except Exception:
                    anchor_index = -1
                if anchor_index < 0 or anchor_index >= size:
                    try:
                        anchor_index = int(self.plates_listbox.index(tk.ACTIVE))
                    except Exception:
                        anchor_index = target_index
                anchor_index = max(0, min(anchor_index, size - 1))
                start_index = min(anchor_index, target_index)
                end_index = max(anchor_index, target_index)
                if not control_pressed:
                    self._clear_listbox_selection_fast(self.plates_listbox)
                self.plates_listbox.selection_set(start_index, end_index)
                if preserve_index is not None:
                    self.plates_listbox.activate(preserve_index)
                else:
                    self.plates_listbox.activate(anchor_index)
                self.plates_listbox.see(target_index)
                preserve_preview = True
            elif control_pressed:
                if self.plates_listbox.selection_includes(target_index):
                    self.plates_listbox.selection_clear(target_index)
                else:
                    self.plates_listbox.selection_set(target_index)
                self.plates_listbox.selection_anchor(target_index)
                if preserve_index is not None:
                    self.plates_listbox.activate(preserve_index)
                else:
                    self.plates_listbox.activate(target_index)
                self.plates_listbox.see(target_index)
                preserve_preview = True
            else:
                self._suppress_preview_reload_on_list_select = False
                self._clear_listbox_selection_fast(self.plates_listbox)
                self.plates_listbox.selection_set(target_index)
                self.plates_listbox.selection_anchor(target_index)
                self.plates_listbox.activate(target_index)
                self.plates_listbox.see(target_index)
        except Exception:
            return "break"

        if preserve_preview:
            self._suppress_preview_reload_on_list_select = True
            self._refresh_preview_editor_toolbar()
            return "break"

        self._on_preview_select(None)
        return "break"

    def _handle_preview_list_arrow_nav(self, offset: int):
        try:
            self.plates_listbox.focus_set()
        except Exception:
            pass
        self._select_preview_relative(int(offset))
        return "break"

    def _select_preview_relative(self, offset: int):
        listbox = getattr(self, "plates_listbox", None)
        pid_map = getattr(self, "_listbox_pid_by_index", [])
        if listbox is None or not pid_map:
            return False

        current_idx = self._get_current_preview_list_index()
        if current_idx is None:
            current_idx = 0
        target_idx = max(0, min(len(pid_map) - 1, int(current_idx) + int(offset)))
        if target_idx == current_idx and current_idx is not None:
            return False

        try:
            self._clear_listbox_selection_fast(listbox)
            listbox.selection_set(target_idx)
            listbox.activate(target_idx)
            listbox.see(target_idx)
        except Exception:
            return False

        self._preview_char_label_active_index = None
        self._preview_char_hover_label_index = None
        self._preview_char_hover_index = None
        self._on_preview_select(None)
        return True

    @staticmethod
    def _append_preview_status_sentence(base: str, sentence: str) -> str:
        base_text = str(base or "").strip()
        addition = str(sentence or "").strip()
        if not addition:
            return base_text
        if not base_text:
            return addition
        if addition.lower() in base_text.lower():
            return base_text
        if base_text.endswith((".", "!", "?", ":")):
            return f"{base_text} {addition}"
        return f"{base_text}. {addition}"

    def _cancel_preview_char_label_interaction(self, *, reset_mode: bool = True, clear_hover: bool = True) -> bool:
        had_state = bool(getattr(self, "_preview_char_label_mode", False))
        had_state = had_state or getattr(self, "_preview_char_label_active_index", None) is not None
        had_state = had_state or getattr(self, "_preview_char_hover_label_index", None) is not None

        if reset_mode:
            self._preview_char_label_mode = False
        self._preview_char_label_active_index = None
        if clear_hover:
            self._preview_char_hover_label_index = None

        try:
            self._preview_typing_overlay_text = ""
        except Exception:
            pass

        if had_state:
            self._apply_preview_canvas_cursor()
            try:
                self._refresh_preview_editor_toolbar()
            except Exception:
                pass
            try:
                self._sync_preview_edit_status_visibility()
                self._refresh_preview_typing_overlay_visibility()
            except Exception:
                pass

        return had_state

    def _get_preview_typing_state(self) -> tuple[bool, bool]:
        label_mode_active = bool(getattr(self, "_preview_char_label_mode", False))
        label_input_active = getattr(self, "_preview_char_label_active_index", None) is not None
        return label_mode_active, label_input_active

    def _format_preview_typing_status(self, message: str | None = None, *, persistent: bool = False) -> str:
        base_text = str(message or "").strip()
        if persistent:
            if not base_text:
                base_text = "TRYB WPISYWANIA ZNAKÓW AKTYWNY. Kliknij box LPM albo użyj strzałek lewo/prawo, potem wpisz 0-9 lub A-Z."
            elif "tryb wpisywania znaków aktywny" not in base_text.lower():
                base_text = f"TRYB WPISYWANIA ZNAKÓW AKTYWNY. {base_text}"
            return self._append_preview_status_sentence(base_text, "Esc konczy tryb wpisywania.")

        if not base_text:
            base_text = "AKTYWNE POLE ZNAKU. Wpisz 0-9 lub A-Z, aby nadpisać etykietę."
        elif "aktywne pole znaku" not in base_text.lower() and "pole znaku jest aktywne" not in base_text.lower():
            base_text = f"AKTYWNE POLE ZNAKU. {base_text}"
        return self._append_preview_status_sentence(base_text, "Esc zamyka wpisywanie.")

    def _sync_preview_edit_status_visibility(self):
        label = getattr(self, "preview_edit_status_lbl", None)
        if label is None:
            return

        overlay_text = self._get_preview_typing_overlay_text()
        if overlay_text:
            try:
                label.grid_remove()
            except Exception:
                pass
            return

        if not bool(getattr(self, "_preview_fullscreen_active", False)):
            try:
                label.grid()
            except Exception:
                pass
            return

        try:
            label.grid_remove()
        except Exception:
            pass

    def _get_preview_typing_overlay_text(self) -> str:
        cached = str(getattr(self, "_preview_typing_overlay_text", "") or "").strip()
        if cached:
            return cached

        label_mode_active, label_input_active = self._get_preview_typing_state()
        if label_mode_active:
            return self._format_preview_typing_status(persistent=True)
        if label_input_active:
            return self._format_preview_typing_status(persistent=False)
        return ""

    def _preview_status_overlay_available(self) -> bool:
        if getattr(self, "preview_canvas", None) is None:
            return False
        return bool(str(getattr(self, "_preview_active_pid", "") or "").strip())

    def _get_preview_typing_overlay_collision_rects(self):
        canvas_w, canvas_h = self._get_preview_canvas_size()
        if canvas_w <= 0.0 or canvas_h <= 0.0:
            return []

        reserved_rects = []
        top_bar_height = max(38.0, float(getattr(self, "_preview_overlay_top_bar_height", 38.0) or 38.0))
        reserved_rects.append((0.0, 0.0, float(canvas_w), top_bar_height))

        mode_overlay = getattr(self, "preview_mode_overlay", None)
        mode_position = getattr(self, "_preview_mode_overlay_position", None)
        if mode_overlay is not None and isinstance(mode_position, dict):
            try:
                mode_overlay.update_idletasks()
            except Exception:
                pass
            try:
                mode_w = float(max(0, int(mode_overlay.winfo_width() or mode_overlay.winfo_reqwidth() or 0)))
                mode_h = float(max(0, int(mode_overlay.winfo_height() or mode_overlay.winfo_reqheight() or 0)))
                mode_x = float(mode_position.get("x", 0.0) or 0.0)
                mode_y = float(mode_position.get("y", 0.0) or 0.0)
            except Exception:
                mode_w = 0.0
                mode_h = 0.0
                mode_x = 0.0
                mode_y = 0.0
            if mode_w > 0.0 and mode_h > 0.0:
                reserved_rects.append((mode_x, mode_y, mode_x + mode_w, mode_y + mode_h))

        render_state = dict(getattr(self, "_preview_render_state", {}) or {})
        try:
            image_left = float(render_state.get("image_left", 0.0) or 0.0)
            image_top = float(render_state.get("image_top", 0.0) or 0.0)
            image_right = float(render_state.get("image_right", 0.0) or 0.0)
            image_bottom = float(render_state.get("image_bottom", 0.0) or 0.0)
        except Exception:
            image_left = image_top = image_right = image_bottom = 0.0

        if image_right > image_left and image_bottom > image_top:
            protected_top = max(top_bar_height, image_top - 6.0)
            protected_bottom = min(float(canvas_h), image_bottom + 56.0)
            reserved_rects.append((image_left - 6.0, protected_top, image_right + 6.0, protected_bottom))

        return reserved_rects

    def _resolve_preview_typing_overlay_anchor(self, overlay_w: float, overlay_h: float) -> tuple[float, float] | None:
        canvas_w, canvas_h = self._get_preview_canvas_size()
        margin = 12.0
        bottom_offset = self._get_preview_typing_overlay_bottom_offset()
        max_y = max(margin, float(canvas_h) - float(overlay_h) - float(bottom_offset))

        base_x, base_y = self._get_preview_typing_overlay_anchor(overlay_h)
        base_x = max(margin, min(max(margin, float(canvas_w) - float(overlay_w) - margin), float(base_x)))
        base_y = max(margin, min(max_y, float(base_y)))

        reserved_rects = self._get_preview_typing_overlay_collision_rects()
        if not reserved_rects or overlay_w <= 0.0 or overlay_h <= 0.0 or canvas_w <= 0.0 or canvas_h <= 0.0:
            return float(base_x), float(base_y)

        render_state = dict(getattr(self, "_preview_render_state", {}) or {})
        try:
            image_left = float(render_state.get("image_left", 0.0) or 0.0)
            image_top = float(render_state.get("image_top", 0.0) or 0.0)
            image_right = float(render_state.get("image_right", 0.0) or 0.0)
            image_bottom = float(render_state.get("image_bottom", 0.0) or 0.0)
        except Exception:
            image_left = image_top = image_right = image_bottom = 0.0

        candidate_positions = [
            (base_x, base_y),
            (float(canvas_w) - float(overlay_w) - margin, base_y),
            (image_right + margin, max(base_y, image_top)),
            (image_left - float(overlay_w) - margin, max(base_y, image_top)),
            (margin, image_bottom + margin),
            (float(canvas_w) - float(overlay_w) - margin, image_bottom + margin),
            (image_right + margin, image_bottom + margin),
            (image_left - float(overlay_w) - margin, image_bottom + margin),
        ]

        unique_candidates = []
        seen = set()
        max_x = max(margin, float(canvas_w) - float(overlay_w) - margin)
        for candidate_x, candidate_y in candidate_positions:
            safe_x = max(margin, min(max_x, float(candidate_x)))
            safe_y = max(margin, min(max_y, float(candidate_y)))
            key = (round(safe_x, 1), round(safe_y, 1))
            if key in seen:
                continue
            seen.add(key)
            unique_candidates.append((safe_x, safe_y))

        for candidate_x, candidate_y in unique_candidates:
            candidate_rect = (
                float(candidate_x),
                float(candidate_y),
                float(candidate_x) + float(overlay_w),
                float(candidate_y) + float(overlay_h),
            )
            overlap_area = sum(
                self._preview_rect_intersection_area(candidate_rect, reserved_rect, padding=4.0)
                for reserved_rect in reserved_rects
            )
            if overlap_area <= 0.0:
                return float(candidate_x), float(candidate_y)

        return None

    def _get_preview_typing_overlay_bottom_offset(self) -> float:
        legend_canvas = getattr(self, "preview_controls_canvas", None)
        if not bool(getattr(self, "_preview_fullscreen_active", False)) or legend_canvas is None:
            return 12.0

        try:
            legend_canvas.update_idletasks()
        except Exception:
            pass

        try:
            legend_height = float(max(0, int(legend_canvas.winfo_height() or 0)))
        except Exception:
            legend_height = 0.0
        return 18.0 + legend_height if legend_height > 0.0 else 12.0

    def _get_preview_typing_overlay_anchor(self, overlay_h: float) -> tuple[float, float]:
        canvas_w, canvas_h = self._get_preview_canvas_size()
        margin = 12.0
        x = margin
        y = margin

        top_bar_height = max(38.0, float(getattr(self, "_preview_overlay_top_bar_height", 38.0) or 38.0))
        y = max(y, float(top_bar_height + 10.0))

        mode_overlay = getattr(self, "preview_mode_overlay", None)
        mode_position = getattr(self, "_preview_mode_overlay_position", None)
        mode_y = margin
        mode_h = 0.0
        if mode_overlay is not None:
            try:
                mode_overlay.update_idletasks()
            except Exception:
                pass
            try:
                mode_h = float(max(0, int(mode_overlay.winfo_height() or mode_overlay.winfo_reqheight() or 0)))
            except Exception:
                mode_h = 0.0
        if isinstance(mode_position, dict):
            try:
                mode_y = float(mode_position.get("y", margin))
            except Exception:
                mode_y = margin
        y = max(y, mode_y + mode_h + 10.0)

        bottom_offset = self._get_preview_typing_overlay_bottom_offset()
        max_y = max(margin, float(canvas_h) - float(overlay_h) - float(bottom_offset))
        y = min(y, max_y)
        return float(x), float(y)

    def _refresh_preview_typing_overlay_visibility(self):
        overlay = getattr(self, "preview_typing_overlay", None)
        label = getattr(self, "preview_typing_overlay_lbl", None)
        canvas = getattr(self, "preview_canvas", None)
        if overlay is None or label is None or canvas is None:
            return

        overlay_text = self._get_preview_typing_overlay_text()
        if not overlay_text:
            try:
                overlay.place_forget()
            except Exception:
                pass
            return

        canvas_w, canvas_h = self._get_preview_canvas_size()
        if canvas_w <= 0.0 or canvas_h <= 0.0:
            return

        wraplength = max(160, min(230, int(canvas_w * 0.22)))
        try:
            label.configure(text=overlay_text, wraplength=wraplength)
        except Exception:
            pass

        try:
            overlay.update_idletasks()
        except Exception:
            pass

        try:
            overlay_w = float(max(0, int(overlay.winfo_reqwidth() or overlay.winfo_width() or 0)))
            overlay_h = float(max(0, int(overlay.winfo_reqheight() or overlay.winfo_height() or 0)))
        except Exception:
            overlay_w = 0.0
            overlay_h = 0.0

        anchor = self._resolve_preview_typing_overlay_anchor(overlay_w, overlay_h)
        if anchor is None:
            try:
                overlay.place_forget()
            except Exception:
                pass
            return
        x, y = anchor

        try:
            overlay.place(in_=canvas, x=x, y=y, anchor="nw")
            overlay.lift()
        except Exception:
            pass

    def _update_preview_edit_status(self, extra_message: str | None = None, tone: str = "muted", emphasis: bool | None = None):
        label_mode_active, label_input_active = self._get_preview_typing_state()
        message = str(extra_message or "").strip()
        overlay_only_message = ""
        overlay_available = self._preview_status_overlay_available()

        if not message:
            if self._preview_char_add_requested():
                message = "Przytrzymaj D i przeciagnij LPM po tablicy, aby narysowac nowy box."
                tone = "info"
                overlay_only_message = message if overlay_available else ""
            elif label_mode_active:
                overlay_only_message = self._format_preview_typing_status(persistent=True)
                message = "Tryb wpisywania znaków aktywny."
                tone = "info"
            elif label_input_active:
                overlay_only_message = self._format_preview_typing_status(persistent=False)
                message = "Aktywne pole znaku."
                tone = "info"
            elif bool(getattr(self, "_preview_char_edit_mode", False)):
                message = "Tryb edycji: S zaznacza lub odznacza hoverowany box, LPM+drag przesuwa zaznaczony box, uchwyty rogów zmieniają rozmiar, Alt+W włącza wpisywanie znaków, a strzałki lewo/prawo przełączają boxy."
                tone = "muted"
                overlay_only_message = message if overlay_available else ""
            else:
                message = "Q/E zmienia tablice, D+LPM rysuje nowy box, S zaznacza lub odznacza hoverowany box, Alt+W wlacza wpisywanie znaków, Enter przelacza pełny ekran."
                tone = "muted"
                overlay_only_message = message if overlay_available else ""
        elif label_mode_active:
            overlay_only_message = self._format_preview_typing_status(message, persistent=True)
            message = "Tryb wpisywania znaków aktywny."
        elif label_input_active:
            overlay_only_message = self._format_preview_typing_status(message, persistent=False)
            message = "Aktywne pole znaku."
        elif overlay_available:
            overlay_only_message = message

        if emphasis is None:
            emphasis = False

        label = getattr(self, "preview_edit_status_lbl", None)
        if hasattr(self, "preview_edit_status_var"):
            try:
                self.preview_edit_status_var.set(message)
            except Exception:
                pass
        if label is not None:
            self._set_inline_status_label_state(label, text=message, tone=tone, emphasis=bool(emphasis))
        try:
            self._preview_typing_overlay_text = str(overlay_only_message or "")
        except Exception:
            pass
        self._sync_preview_edit_status_visibility()
        self._refresh_preview_typing_overlay_visibility()

    def _get_preview_char_label_canvas_rect(self, rec) -> tuple[float, float, float, float] | None:
        bbox = self._char_record_bbox(rec)
        if not bbox:
            return None
        cx1, cy1 = self._preview_image_to_canvas_point(bbox[0], bbox[1])
        cx2, _cy2 = self._preview_image_to_canvas_point(bbox[2], bbox[3])
        label_w = min(max(18.0, (cx2 - cx1) * 0.34), 28.0)
        label_h = 18.0
        inset = 2.0
        return (
            float(cx1 + inset),
            float(cy1 + inset),
            float(cx1 + inset + label_w),
            float(cy1 + inset + label_h),
        )

    def _find_preview_char_label_hit(self, canvas_x: float, canvas_y: float):
        if (
            not bool(getattr(self, "_preview_char_label_mode", False))
            and getattr(self, "_preview_char_label_active_index", None) is None
        ):
            return None
        chars = self._get_preview_active_character_records(create=False)
        for idx, rec in enumerate(chars):
            rect = self._get_preview_char_label_canvas_rect(rec)
            if rect is None:
                continue
            rx1, ry1, rx2, ry2 = rect
            pad = 2.0
            if (rx1 - pad) <= float(canvas_x) <= (rx2 + pad) and (ry1 - pad) <= float(canvas_y) <= (ry2 + pad):
                return idx
        return None

    def _resolve_preview_char_label_target_index(self, *, prefer_hover: bool = True) -> int | None:
        chars = self._get_preview_active_character_records(create=False)
        if not isinstance(chars, list) or not chars:
            return None

        total = len(chars)

        def _safe_index(value) -> int | None:
            try:
                idx = int(value)
            except Exception:
                return None
            return idx if 0 <= idx < total else None

        hover_idx = _safe_index(getattr(self, "_preview_char_hover_label_index", None))
        if hover_idx is None and bool(getattr(self, "_preview_char_label_mode", False)):
            hover_idx = _safe_index(getattr(self, "_preview_char_hover_index", None))
        active_idx = _safe_index(getattr(self, "_preview_char_label_active_index", None))
        selected_idx = _safe_index(getattr(self, "_preview_char_selected_index", None))

        ordered_candidates = (
            (hover_idx, active_idx, selected_idx)
            if bool(prefer_hover)
            else (active_idx, hover_idx, selected_idx)
        )
        for idx in ordered_candidates:
            if idx is not None:
                return idx
        return 0

    def _get_leftmost_preview_char_index(self, chars=None) -> int | None:
        local_chars = chars if isinstance(chars, list) else self._get_preview_active_character_records(create=False)
        if not isinstance(local_chars, list) or not local_chars:
            return None

        ordered_chars = self._sort_character_records_by_x(list(local_chars))
        target_rec = ordered_chars[0] if ordered_chars else None
        if target_rec is None:
            return None
        return self._find_preview_char_record_index(local_chars, target_rec)

    def _resolve_preview_char_label_entry_index(self) -> int | None:
        chars = self._get_preview_active_character_records(create=False)
        if not isinstance(chars, list) or not chars:
            return None

        total = len(chars)

        def _safe_index(value) -> int | None:
            try:
                idx = int(value)
            except Exception:
                return None
            return idx if 0 <= idx < total else None

        explicit_hover_idx = _safe_index(getattr(self, "_preview_char_hover_label_index", None))
        if explicit_hover_idx is None:
            explicit_hover_idx = _safe_index(getattr(self, "_preview_char_hover_index", None))
        if explicit_hover_idx is not None:
            return explicit_hover_idx

        explicit_active_idx = _safe_index(getattr(self, "_preview_char_label_active_index", None))
        if explicit_active_idx is not None:
            return explicit_active_idx

        return self._get_leftmost_preview_char_index(chars)

    def _activate_preview_char_label_input(self, char_idx: int | None, *, keep_selection: bool = True, status_message: str | None = None):
        if char_idx is None:
            self._preview_char_label_active_index = None
        else:
            self._preview_char_label_active_index = int(char_idx)
            if keep_selection:
                self._preview_char_selected_index = int(char_idx)
            self._preview_char_hover_label_index = int(char_idx)
        if status_message:
            self._update_preview_edit_status(status_message, tone="info")
        else:
            self._update_preview_edit_status()
        self._focus_preview_canvas()
        self._on_preview_select(None)

    def _assign_character_to_active_preview_label(self, symbol: str):
        idx = getattr(self, "_preview_char_label_active_index", None)
        chars = self._get_preview_active_character_records(create=False)
        if idx is None or not (0 <= int(idx) < len(chars)):
            return False

        symbol = self._sanitize_preview_char_symbol(symbol)
        if not symbol:
            return False

        rec = chars[int(idx)]
        if self._sanitize_preview_char_symbol(rec.get("character", "")) == symbol:
            self._preview_char_selected_index = int(idx)
            self._preview_char_label_active_index = int(idx)
            self._preview_char_hover_label_index = int(idx)
            self._update_preview_edit_status(
                "Znak już ma taka wartosc. Uzyj strzalek lewo/prawo albo kliknij inny box LPM.",
                tone="muted",
            )
            self._on_preview_select(None)
            return True
        self._push_preview_history_snapshot()
        rec["character"] = symbol
        self._mark_preview_char_record_manual(rec)
        self._preview_char_selected_index = int(idx)
        self._preview_char_label_active_index = int(idx)
        self._preview_char_hover_label_index = int(idx)
        self._persist_active_preview_characters(
            selected_record=rec,
            success_message=f"Zapisano znak {symbol} w metadata.json.",
        )
        if bool(getattr(self, "_preview_char_label_mode", False)):
            self._update_preview_edit_status(
                f"Zapisano znak {symbol}. Uzyj strzalek lewo/prawo albo kliknij kolejny box LPM.",
                tone="success",
            )
        return True

    def _reset_current_preview_view(self):
        plate_id = str(getattr(self, "_preview_active_pid", "") or "")
        if plate_id:
            self._preview_badge_offsets.pop(plate_id, None)
        self._reset_preview_view_state()
        if getattr(self, "preview_canvas", None) is not None:
            self._on_preview_select(None)

    def _init_preview_vertical_split(self):
        pane = getattr(self, "preview_vertical_split", None)
        if pane is None or self._preview_vertical_split_ready:
            return

        try:
            total_w = int(pane.winfo_width() or 0)
            if total_w < 240:
                self.frame.after(120, self._init_preview_vertical_split)
                return
            total_w = max(760, total_w)
            min_left = 240
            max_left = 340
            target_x = max(min_left, min(int(total_w * 0.28), max_left))
            pane.sash_place(0, target_x, 1)
            self._preview_vertical_split_ready = True
        except Exception:
            pass

    def _apply_preview_badge_selection_style(self):
        canvas = getattr(self, "preview_canvas", None)
        if canvas is None:
            return

        for badge_key, runtime in getattr(self, "_preview_badge_runtime", {}).items():
            is_selected = str(badge_key) == str(getattr(self, "_preview_selected_badge_key", None))
            box_color = str(runtime.get("box_color", "#cccccc"))
            line_color = str(runtime.get("line_color", "#cccccc"))
            box_width = 4 if is_selected else int(runtime.get("box_width", 2))
            line_width = 3 if is_selected else int(runtime.get("line_width", 1))

            try:
                canvas.itemconfigure(runtime.get("box_id"), outline=box_color, width=box_width)
            except Exception:
                pass

            try:
                canvas.itemconfigure(runtime.get("line_id"), fill=line_color, width=line_width)
            except Exception:
                pass

    def _set_preview_selected_badge(self, badge_key: str = None):
        self._preview_selected_badge_key = str(badge_key) if badge_key else None
        self._apply_preview_badge_selection_style()

    def _move_preview_badge_to_offset(self, badge_key: str, dx: float, dy: float):
        runtime = self._preview_badge_runtime.get(str(badge_key))
        canvas = getattr(self, "preview_canvas", None)
        if runtime is None or canvas is None:
            return

        dx, dy = self._clamp_preview_badge_offset(badge_key, dx, dy)

        prev_dx = float(runtime.get("offset_dx", 0.0))
        prev_dy = float(runtime.get("offset_dy", 0.0))
        delta_x = float(dx) - prev_dx
        delta_y = float(dy) - prev_dy

        if abs(delta_x) > 0.001 or abs(delta_y) > 0.001:
            try:
                canvas.move(runtime["tag"], delta_x, delta_y)
            except Exception:
                pass

        runtime["offset_dx"] = float(dx)
        runtime["offset_dy"] = float(dy)

        try:
            canvas.coords(
                runtime["line_id"],
                float(runtime["base_center_x"]) + float(dx),
                float(runtime["base_bottom_y"]) + float(dy),
                float(runtime["box_center_x"]),
                float(runtime["box_top_y"]),
            )
        except Exception:
            pass

    def _on_preview_canvas_configure(self, event=None):
        self._ensure_preview_mode_overlay_position()
        self._refresh_preview_typing_overlay_visibility()
        self._on_preview_select(None)

    def _on_preview_mode_eye_press(self, event=None):
        if event is None:
            return "break"
        self._preview_mode_eye_drag_state = {
            "start_x": float(event.x_root),
            "start_y": float(event.y_root),
            "origin_x": float((getattr(self, "_preview_mode_overlay_position", {}) or {}).get("x", 12.0)),
            "origin_y": float((getattr(self, "_preview_mode_overlay_position", {}) or {}).get("y", 12.0)),
            "dragged": False,
        }
        return "break"

    def _on_preview_mode_eye_drag(self, event=None):
        drag_state = getattr(self, "_preview_mode_eye_drag_state", None)
        if not isinstance(drag_state, dict) or event is None:
            return "break"

        delta_x = float(event.x_root) - float(drag_state.get("start_x", 0.0))
        delta_y = float(event.y_root) - float(drag_state.get("start_y", 0.0))
        if abs(delta_x) >= 3.0 or abs(delta_y) >= 3.0:
            drag_state["dragged"] = True

        new_x, new_y = self._clamp_preview_mode_overlay_position(
            float(drag_state.get("origin_x", 12.0)) + delta_x,
            float(drag_state.get("origin_y", 12.0)) + delta_y,
        )
        self._preview_mode_overlay_position = {"x": float(new_x), "y": float(new_y)}
        self._ensure_preview_mode_overlay_position()
        return "break"

    def _on_preview_mode_eye_release(self, event=None):
        drag_state = getattr(self, "_preview_mode_eye_drag_state", None)
        self._preview_mode_eye_drag_state = None
        if isinstance(drag_state, dict) and bool(drag_state.get("dragged")):
            self._focus_preview_canvas()
            return "break"
        return self._toggle_preview_mode_overlay()

    def _get_preview_selected_char_record(self):
        chars = self._get_preview_active_character_records(create=False)
        idx = getattr(self, "_preview_char_selected_index", None)
        if idx is None:
            return None, None
        try:
            idx = int(idx)
        except Exception:
            self._preview_char_selected_index = None
            return None, None
        if not (0 <= idx < len(chars)):
            self._preview_char_selected_index = None
            return None, None
        return idx, chars[idx]

    def _preview_char_add_requested(self) -> bool:
        return bool(
            getattr(self, "_preview_char_add_state", None) is not None
            or getattr(self, "_preview_char_add_mode", False)
            or getattr(self, "_preview_char_add_modifier_down", False)
        )

    @staticmethod
    def _find_preview_char_record_index(chars, target_record) -> int | None:
        if not isinstance(chars, list) or target_record is None:
            return None
        for idx, rec in enumerate(chars):
            if rec is target_record:
                return idx
        return None

    def _select_preview_character_box(self, char_idx: int | None, *, activate_label: bool = False, status_message: str | None = None):
        chars = self._get_preview_active_character_records(create=False)
        if not isinstance(chars, list) or not chars:
            self._preview_char_selected_index = None
            self._preview_char_label_active_index = None
            self._preview_char_hover_label_index = None
            self._refresh_preview_editor_toolbar()
            self._update_preview_edit_status("Brak boxow znaków do zaznaczenia.", tone="warning")
            self._on_preview_select(None)
            return "break"

        try:
            safe_idx = max(0, min(int(char_idx), len(chars) - 1))
        except Exception:
            self._update_preview_edit_status("Nie udało się zaznaczyc boxu znaku.", tone="warning")
            return "break"

        self._ensure_preview_final_box_mode()
        label_mode_active = bool(getattr(self, "_preview_char_label_mode", False))
        self._preview_char_edit_mode = False if label_mode_active else True
        self._preview_char_add_mode = False
        self._preview_char_add_modifier_down = False
        self._preview_char_add_state = None
        self._preview_char_selected_index = safe_idx
        self._preview_char_hover_index = safe_idx
        label_target_active = bool(activate_label or label_mode_active)
        self._preview_char_hover_label_index = safe_idx if label_target_active else None
        self._preview_char_label_active_index = safe_idx if label_target_active else None
        self._refresh_preview_editor_toolbar()
        self._update_preview_edit_status(
            status_message or (
                "Tryb wpisywania znaków jest aktywny. Kliknij kolejny box LPM albo użyj strzałek lewo/prawo, a potem wpisz znak."
                if label_mode_active else
                "Box znaku jest aktywny. LPM+drag przesuwa, uchwyty zmieniaja rozmiar, PPM usuwa aktywny box, a Alt+W wlacza wpisywanie znaków."
            ),
            tone="info",
        )
        self._focus_preview_canvas()
        self._on_preview_select(None)
        return "break"

    def _select_hovered_preview_char_box(self, event=None):
        hover_idx = getattr(self, "_preview_char_hover_index", None)
        if hover_idx is None:
            selected_idx, _selected_rec = self._get_preview_selected_char_record()
            if selected_idx is not None:
                self._preview_char_selected_index = None
                self._preview_char_label_active_index = None
                self._preview_char_hover_label_index = None
                self._refresh_preview_editor_toolbar()
                self._update_preview_edit_status("Odznaczono aktywny box znaku.", tone="muted")
                self._on_preview_select(None)
                return "break"
            self._update_preview_edit_status("Najedz kursorem na box i nacisnij S, aby go zaznaczyc.", tone="warning")
            return "break"
        selected_idx, _selected_rec = self._get_preview_selected_char_record()
        if selected_idx is not None and int(selected_idx) == int(hover_idx):
            self._preview_char_selected_index = None
            self._preview_char_label_active_index = None
            self._preview_char_hover_label_index = None
            self._refresh_preview_editor_toolbar()
            self._update_preview_edit_status("Odznaczono hoverowany box znaku.", tone="muted")
            self._on_preview_select(None)
            return "break"
        return self._select_preview_character_box(
            int(hover_idx),
            activate_label=False,
            status_message="Zaznaczono hoverowany box. PPM usuwa aktywny box, a S ponownie go odznacza.",
        )

    def _cycle_preview_character_selection(self, step: int, *, activate_label: bool = False):
        chars = self._get_preview_active_character_records(create=False)
        if not isinstance(chars, list) or not chars:
            self._update_preview_edit_status("Brak boxow znaków do przelaczenia.", tone="warning")
            return "break"

        ordered_chars = self._sort_character_records_by_x(list(chars))
        selected_idx, selected_rec = self._get_preview_selected_char_record()
        ordered_pos = None
        if selected_rec is not None:
            for idx, rec in enumerate(ordered_chars):
                if rec is selected_rec:
                    ordered_pos = idx
                    break

        if ordered_pos is None:
            target_pos = 0 if int(step) >= 0 else (len(ordered_chars) - 1)
        else:
            target_pos = (int(ordered_pos) + int(step)) % len(ordered_chars)

        target_rec = ordered_chars[int(target_pos)]
        target_idx = self._find_preview_char_record_index(chars, target_rec)
        if target_idx is None:
            if selected_idx is not None:
                target_idx = max(0, min(int(selected_idx), len(chars) - 1))
            else:
                target_idx = 0

        return self._select_preview_character_box(
            int(target_idx),
            activate_label=(activate_label or bool(getattr(self, "_preview_char_label_mode", False))),
            status_message=(
                f"Wybrano box {int(target_pos) + 1}/{len(ordered_chars)} wedlug rosnacego X. "
                + (
                    "Wpisz znak z klawiatury, aby nadpisac etykiete."
                    if bool(getattr(self, "_preview_char_label_mode", False))
                    else "Strzałki lewo/prawo przelaczaja kolejne boxy."
                )
            ),
        )

    def _get_preview_char_handle_radius(self) -> float:
        state = getattr(self, "_preview_render_state", None) or {}
        scale = float(state.get("scale", 1.0) or 1.0)
        return max(5.0, min(9.0, 4.0 + (scale * 0.12)))

    def _find_preview_character_box_hit(self, canvas_x: float, canvas_y: float):
        chars = self._get_preview_active_character_records(create=False)
        for idx in range(len(chars) - 1, -1, -1):
            bbox = self._char_record_bbox(chars[idx])
            if not bbox:
                continue
            cx1, cy1 = self._preview_image_to_canvas_point(bbox[0], bbox[1])
            cx2, cy2 = self._preview_image_to_canvas_point(bbox[2], bbox[3])
            pad = 3.0
            if (cx1 - pad) <= float(canvas_x) <= (cx2 + pad) and (cy1 - pad) <= float(canvas_y) <= (cy2 + pad):
                return idx
        return None

    def _find_preview_character_handle_hit(self, canvas_x: float, canvas_y: float):
        idx, rec = self._get_preview_selected_char_record()
        if rec is None:
            return None

        bbox = self._char_record_bbox(rec)
        if not bbox:
            return None

        cx1, cy1 = self._preview_image_to_canvas_point(bbox[0], bbox[1])
        cx2, cy2 = self._preview_image_to_canvas_point(bbox[2], bbox[3])
        radius = self._get_preview_char_handle_radius()
        handles = {
            "nw": (cx1, cy1),
            "ne": (cx2, cy1),
            "sw": (cx1, cy2),
            "se": (cx2, cy2),
        }
        for handle_name, (hx, hy) in handles.items():
            if abs(float(canvas_x) - float(hx)) <= radius and abs(float(canvas_y) - float(hy)) <= radius:
                return idx, handle_name
        return None

    def _refresh_preview_editor_toolbar(self):
        hidden_controls = getattr(self, "preview_hidden_controls", None)
        if hidden_controls is not None:
            try:
                if not str(hidden_controls.winfo_manager()):
                    return
            except Exception:
                pass

        active_data = self._get_preview_active_data(create=False)
        has_plate = isinstance(active_data, dict)
        selected_idx, _selected_rec = self._get_preview_selected_char_record()
        has_selection = selected_idx is not None

        button_specs = (
            ("preview_edit_toggle_btn", has_plate, "Edytuj boxy", "Edytowanie boxow"),
            ("preview_add_box_btn", has_plate, "Nowy box", "Rysowanie boxu"),
            ("preview_edit_char_btn", has_selection, "Zmien znak", "Zmien znak"),
            ("preview_delete_char_btn", has_selection, "Usuń box", "Usuń box"),
        )

        for attr_name, enabled, idle_text, active_text in button_specs:
            widget = getattr(self, attr_name, None)
            if widget is None:
                continue
            is_active = bool(
                (attr_name == "preview_edit_toggle_btn" and getattr(self, "_preview_char_edit_mode", False))
                or (attr_name == "preview_add_box_btn" and getattr(self, "_preview_char_add_mode", False))
            )
            try:
                widget.configure(
                    state=(tk.NORMAL if enabled else tk.DISABLED),
                    text=(active_text if is_active else idle_text),
                )
            except Exception:
                pass

        try:
            self._update_preview_toolbar_state()
        except Exception:
            pass
        try:
            self._refresh_preview_clear_sources_menu()
        except Exception:
            pass

    def _ensure_preview_final_box_mode(self):
        if self._get_preview_box_mode_key() == "FINAL":
            return
        try:
            self.preview_box_mode_var.set(PREVIEW_BOX_MODE_LABELS["FINAL"])
        except Exception:
            pass
        self._on_preview_box_mode_change()

    def _set_preview_char_editor_modes(self, *, edit: bool | None = None, add: bool | None = None, message: str | None = None):
        if edit is not None:
            self._preview_char_edit_mode = bool(edit)
            if not self._preview_char_edit_mode:
                self._preview_char_drag_state = None
            else:
                self._preview_char_label_mode = False
                self._preview_char_label_active_index = None
                self._preview_char_hover_label_index = None
        if add is not None:
            self._preview_char_add_mode = bool(add)
            if not self._preview_char_add_mode:
                self._preview_char_add_state = None
            else:
                self._preview_char_label_mode = False
                self._preview_char_label_active_index = None
                self._preview_char_hover_label_index = None
        if bool(getattr(self, "_preview_char_add_mode", False)):
            self._preview_char_label_active_index = None
        self._refresh_preview_editor_toolbar()
        if message:
            self._set_preview_box_info(message, "info")
            self._update_preview_edit_status(message, tone="info")
        else:
            self._update_preview_edit_status()
        self._focus_preview_canvas()
        self._on_preview_select(None)

    def _toggle_preview_char_edit_mode(self, event=None):
        if self._get_preview_active_data(create=False) is None:
            self._set_preview_box_info("Najpierw wybierz tablice z listy.", "warning")
            return "break"
        self._ensure_preview_final_box_mode()
        self._set_preview_char_editor_modes(
            edit=(not bool(getattr(self, "_preview_char_edit_mode", False))),
            add=False,
            message="Tryb korekty boxow znaków działa na wyniku koncowym.",
        )
        return "break"

    def _toggle_preview_char_add_mode(self, event=None):
        if self._get_preview_active_data(create=False) is None:
            self._set_preview_box_info("Najpierw wybierz tablice z listy.", "warning")
            return "break"
        self._ensure_preview_final_box_mode()
        self._set_preview_char_editor_modes(
            edit=False,
            add=(not bool(getattr(self, "_preview_char_add_mode", False))),
            message="Narysuj nowy box na znaku w podgladzie tablicy.",
        )
        return "break"

    def _toggle_preview_char_label_mode(self, event=None):
        if self._get_preview_active_data(create=False) is None:
            self._set_preview_box_info("Najpierw wybierz tablice z listy.", "warning")
            return "break"

        self._ensure_preview_final_box_mode()
        next_state = not bool(getattr(self, "_preview_char_label_mode", False))
        self._preview_char_label_mode = next_state
        self._preview_char_edit_mode = False
        self._preview_char_add_mode = False
        self._preview_char_add_modifier_down = False
        self._preview_char_add_state = None
        self._preview_char_drag_state = None

        if next_state:
            target_idx = self._resolve_preview_char_label_entry_index()
            if target_idx is not None:
                self._preview_char_selected_index = int(target_idx)
                self._preview_char_hover_label_index = int(target_idx)
                self._preview_char_label_active_index = int(target_idx)
            self._update_preview_edit_status(
                "Tryb wpisywania znaków aktywny. Kliknij box LPM albo użyj strzałek lewo/prawo, a potem wpisz znak z klawiatury.",
                tone="info",
            )
        else:
            self._preview_char_hover_label_index = None
            self._preview_char_label_active_index = None
            self._update_preview_edit_status("Wylaczono tryb wpisywania znaków.", tone="muted")

        self._refresh_preview_editor_toolbar()
        self._focus_preview_canvas()
        self._apply_preview_canvas_cursor()
        self._on_preview_select(None)
        return "break"

    def _prompt_preview_char_symbol(self, initial_value: str = ""):
        current_value = self._sanitize_preview_char_symbol(initial_value)
        while True:
            value = self._prompt_dark_text_input(
                title="Znak tablicy",
                prompt="Podaj pojedynczy znak [0-9, A-Z]:",
                initial_value=current_value,
                width=420,
            )
            if value is None:
                return None
            normalized = self._sanitize_preview_char_symbol(value)
            if normalized:
                return normalized
            messagebox.showerror("Nieprawidlowy znak", "Wpisz pojedynczy znak z zakresu 0-9 lub A-Z.")

    def _prompt_dark_text_input(
        self,
        *,
        title: str,
        prompt: str,
        initial_value: str = "",
        width: int = 520,
    ) -> str | None:
        result = {"value": None}
        palette = getattr(self.app, "palette", {}) or {}

        dialog = tk.Toplevel(self.frame)
        try:
            dialog.withdraw()
        except Exception:
            pass

        dialog_styler = getattr(self.app, "style_dialog_window", None)
        if callable(dialog_styler):
            try:
                dialog_styler(
                    dialog,
                    title=str(title or "").strip(),
                    geometry=f"{int(max(420, width))}x220",
                    parent=self.frame,
                )
            except Exception:
                try:
                    dialog.title(str(title or "").strip())
                    dialog.resizable(False, False)
                except Exception:
                    pass
        else:
            try:
                dialog.title(str(title or "").strip())
                dialog.resizable(False, False)
            except Exception:
                pass

        panel_bg = palette.get("panel", "#252526")
        field_bg = palette.get("field", palette.get("panel_alt", "#2d2d30"))
        border = palette.get("panel_border", palette.get("border", "#3c3c3c"))
        fg = palette.get("fg", "#f3f3f3")
        muted = palette.get("muted", "#c7c7c7")

        try:
            dialog.configure(bg=panel_bg, highlightbackground=panel_bg, highlightcolor=panel_bg)
        except Exception:
            pass

        body_surface_builder = getattr(self.app, "_build_themed_dialog_surface", None)
        if callable(body_surface_builder):
            try:
                body_surface = body_surface_builder(dialog, tone="info")
            except Exception:
                body_surface = tk.Frame(dialog, bg=panel_bg, bd=0, highlightthickness=0)
                body_surface.pack(fill=tk.BOTH, expand=True)
        else:
            body_surface = tk.Frame(dialog, bg=panel_bg, bd=0, highlightthickness=0)
            body_surface.pack(fill=tk.BOTH, expand=True)

        body = tk.Frame(body_surface, bg=panel_bg, bd=0, highlightthickness=0)
        body.pack(fill=tk.BOTH, expand=True, padx=16, pady=16)

        tk.Label(
            body,
            text=str(prompt or "").strip(),
            bg=panel_bg,
            fg=muted,
            font=("Segoe UI", 9),
            anchor="w",
            justify=tk.LEFT,
            wraplength=max(360, int(width) - 100),
        ).pack(anchor=tk.W, fill=tk.X)

        entry = tk.Entry(
            body,
            bd=0,
            highlightthickness=1,
            relief=tk.FLAT,
            bg=field_bg,
            fg=fg,
            insertbackground=fg,
            highlightbackground=border,
            highlightcolor=border,
        )
        entry.pack(fill=tk.X, pady=(12, 0), ipady=6)
        try:
            entry.insert(0, str(initial_value or ""))
            entry.selection_range(0, tk.END)
        except Exception:
            pass

        buttons = tk.Frame(body, bg=panel_bg, bd=0, highlightthickness=0)
        buttons.pack(fill=tk.X, pady=(16, 0))

        def _close(value):
            result["value"] = value
            try:
                dialog.destroy()
            except Exception:
                pass

        ttk.Button(buttons, text="Anuluj", command=lambda: _close(None)).pack(side=tk.RIGHT)
        ttk.Button(buttons, text="OK", command=lambda: _close(entry.get())).pack(side=tk.RIGHT, padx=(0, 8))

        try:
            dialog.bind("<Return>", lambda _e: _close(entry.get()))
            dialog.bind("<Escape>", lambda _e: _close(None))
        except Exception:
            pass

        try:
            dialog.update_idletasks()
            dialog.deiconify()
            dialog.lift()
            entry.focus_force()
        except Exception:
            pass

        dialog.wait_window()
        return result.get("value")

    def _persist_active_preview_characters(self, *, selected_record=None, success_message: str):
        data = self._get_preview_active_data(create=True)
        previous_chars = list(data.get("characters", [])) if isinstance(data.get("characters"), list) else []
        previous_status = str(data.get("status", "unknown") or "unknown").strip().lower()
        chars = self._get_preview_active_character_records(create=True)
        normalized_chars = []
        for rec in list(chars):
            if not isinstance(rec, dict):
                continue
            bbox = self._normalize_preview_char_bbox(rec.get("bbox"))
            if bbox is None:
                continue
            rec["bbox"] = bbox
            normalized_chars.append(rec)

        sorted_chars = self._sort_character_records_by_x(normalized_chars)
        data["characters"] = sorted_chars
        status_now = self._derive_preview_status_from_data(data, sorted_chars)
        if (
            status_now == "perfect"
            and previous_status == "perfect"
            and len(sorted_chars) != len(previous_chars)
            and not self._get_preview_expected_texts(data)
        ):
            status_now = "needs_fix"
        data["status"] = status_now
        data["fusion_strategy"] = "manual_correction"
        data["fusion_details"] = {"source": "preview_editor"}
        self._ensure_plate_source_metadata(
            data,
            plate_id=str(getattr(self, "_preview_active_pid", "") or data.get("plate_id", "") or ""),
            default_bucket="local_manual",
            default_origin="preview_editor",
            modified_by="human",
        )

        if selected_record is not None:
            self._preview_char_selected_index = None
            for idx, rec in enumerate(sorted_chars):
                if rec is selected_record:
                    self._preview_char_selected_index = idx
                    break
        elif self._preview_char_selected_index is not None:
            self._preview_char_selected_index = min(int(self._preview_char_selected_index), len(sorted_chars) - 1) if sorted_chars else None

        status_suffix = "Status tablicy: OK." if status_now == "perfect" else "Status tablicy: wymaga korekty."
        live_message = f"{success_message} {status_suffix}".strip()
        live_tone = "success" if status_now == "perfect" else "info"
        self._refresh_preview_live_metadata_ui(
            status_message=live_message,
            status_tone=live_tone,
            render_preview=True,
        )
        try:
            self.frame.update_idletasks()
        except Exception:
            pass
        self._persist_preview_metadata(success_message=None, refresh_list=False)

    def _edit_selected_preview_char_symbol(self, event=None):
        idx, rec = self._get_preview_selected_char_record()
        if rec is None:
            self._set_preview_box_info("Najpierw zaznacz box znaku do korekty.", "warning")
            return "break"
        self._activate_preview_char_label_input(
            idx,
            status_message="Pole znaku jest aktywne tymczasowo. Wpisz 0-9 lub A-Z, aby nadpisać etykietę, albo Esc aby wyjść.",
        )
        return "break"

    def _edit_preview_source_filename(self, event=None):
        try:
            from ..campaign_manager import CAMPAIGN

            in_campaign = bool(CAMPAIGN.get_active_project_name())
        except Exception:
            in_campaign = False

        guidance_lines = [
            "Zmianę nazwy pliku źródłowego wykonuj w Z2, a nie w Z3/PZ2.",
            "",
            "Dlaczego:",
            "• Z2 pracuje jeszcze na obrazie źródłowym i całym workflow tablic.",
            "• Z3 powinno służyć już do pracy na wyciętych tablicach i znakach.",
            "",
            "W Z2 zmienisz nazwę bezpieczniej, zanim dane zostaną użyte w kolejnych etapach.",
        ]
        if in_campaign:
            guidance_lines.extend(
                [
                    "",
                    "Przejdź do wizarda i wróć do Z2, aby wykonać zmianę nazwy na właściwym etapie.",
                ]
            )

        messagebox.showinfo(
            "Zmiana nazwy w Z2",
            "\n".join(guidance_lines),
            parent=self.frame.winfo_toplevel() if self.frame is not None else None,
        )
        self._update_preview_edit_status(
            "Zmianę nazwy pliku źródłowego przenieśliśmy do Z2. W Z3/PZ2 ta operacja jest już tylko informacyjna.",
            tone="info",
        )
        self._focus_preview_canvas()
        return "break"

    def _delete_selected_preview_char_box(self, event=None):
        idx, rec = self._get_preview_selected_char_record()
        chars = self._get_preview_active_character_records(create=False)
        if rec is None or not isinstance(chars, list):
            self._set_preview_box_info("Najpierw zaznacz box klawiszem S, aby go usunąć.", "warning")
            self._update_preview_edit_status("Najpierw zaznacz box klawiszem S, a potem użyj PPM albo przycisku Usuń box.", tone="warning")
            return "break"

        self._push_preview_history_snapshot()
        try:
            chars.pop(idx)
        except Exception:
            return "break"

        self._preview_char_selected_index = min(idx, len(chars) - 1) if chars else None
        self._preview_char_label_active_index = None
        self._preview_char_hover_label_index = None
        self._persist_active_preview_characters(
            selected_record=(chars[self._preview_char_selected_index] if self._preview_char_selected_index is not None and chars else None),
            success_message="Usunieto box znaku i zapisano zmiane do metadata.json.",
        )
        return "break"

    def _on_preview_canvas_motion(self, event=None):
        if event is None:
            return
        if (
            self._preview_badge_drag_state is not None
            or self._preview_pan_drag_state is not None
            or self._preview_char_drag_state is not None
            or self._preview_char_add_state is not None
        ):
            return

        action_key = self._extract_preview_action_from_current_item()
        if action_key in {"reset_view", "edit_source_filename"}:
            had_hover = bool(
                getattr(self, "_preview_char_hover_index", None) is not None
                or getattr(self, "_preview_char_hover_label_index", None) is not None
            )
            self._preview_char_hover_index = None
            if not bool(getattr(self, "_preview_char_label_mode", False)):
                self._preview_char_hover_label_index = None
            self._apply_preview_canvas_cursor("hand2")
            if had_hover:
                self._on_preview_select(None)
            return

        self._apply_preview_canvas_cursor()
        label_mode_active = bool(getattr(self, "_preview_char_label_mode", False))
        next_hover_box = self._find_preview_character_box_hit(event.x, event.y)
        next_hover_label = self._find_preview_char_label_hit(event.x, event.y)
        if label_mode_active:
            next_hover_label = next_hover_box if next_hover_box is not None else next_hover_label
        elif bool(getattr(self, "_preview_char_edit_mode", False)) and getattr(self, "_preview_char_label_active_index", None) is None:
            next_hover_label = None
        if (
            next_hover_box == getattr(self, "_preview_char_hover_index", None)
            and next_hover_label == getattr(self, "_preview_char_hover_label_index", None)
        ):
            return

        self._preview_char_hover_index = next_hover_box
        self._preview_char_hover_label_index = next_hover_label
        self._on_preview_select(None)

    def _on_preview_canvas_leave(self, event=None):
        if (
            getattr(self, "_preview_char_hover_index", None) is None
            and getattr(self, "_preview_char_hover_label_index", None) is None
        ):
            self._apply_preview_canvas_cursor()
            return
        self._preview_char_hover_index = None
        self._preview_char_hover_label_index = None
        self._apply_preview_canvas_cursor()
        self._on_preview_select(None)

    def _on_preview_prev_shortcut(self, event=None):
        if (
            getattr(self, "_preview_char_label_active_index", None) is not None
            and not bool(getattr(self, "_preview_char_label_mode", False))
        ):
            return None
        if self._select_preview_relative(-1):
            self._update_preview_edit_status()
            return "break"
        return None

    def _on_preview_next_shortcut(self, event=None):
        if (
            getattr(self, "_preview_char_label_active_index", None) is not None
            and not bool(getattr(self, "_preview_char_label_mode", False))
        ):
            return None
        if self._select_preview_relative(1):
            self._update_preview_edit_status()
            return "break"
        return None

    def _on_preview_fit_shortcut(self, event=None):
        if not bool(getattr(self, "_preview_render_state", None)):
            return None
        self._reset_current_preview_view()
        self._update_preview_edit_status("Dopasowano widok tablicy.", tone="muted")
        return "break"

    def _on_preview_enter_fullscreen_shortcut(self, event=None):
        self._toggle_preview_fullscreen()
        return "break"

    def _on_preview_escape_shortcut(self, event=None):
        if bool(getattr(self, "_preview_char_label_mode", False)):
            self._preview_char_label_mode = False
            self._preview_char_hover_label_index = None
            self._preview_char_label_active_index = None
            self._refresh_preview_editor_toolbar()
            self._apply_preview_canvas_cursor()
            self._update_preview_edit_status("Wylaczono tryb wpisywania znaków klawiszem Esc.", tone="muted")
            self._on_preview_select(None)
            return "break"
        if getattr(self, "_preview_char_label_active_index", None) is not None:
            self._preview_char_label_active_index = None
            self._preview_char_hover_label_index = None
            self._refresh_preview_editor_toolbar()
            self._apply_preview_canvas_cursor()
            self._update_preview_edit_status("Zamknieto aktywne pole znaku klawiszem Esc.", tone="muted")
            self._on_preview_select(None)
            return "break"
        return None

    def _on_preview_canvas_keypress(self, event=None):
        if event is None:
            return None

        keysym = str(getattr(event, "keysym", "") or "").lower()
        label_mode_active = bool(getattr(self, "_preview_char_label_mode", False))
        if self._event_has_control_modifier(event):
            if keysym == "z":
                return self._undo_preview_edit(event)
            if keysym == "y":
                return self._redo_preview_edit(event)
        if keysym == "w" and self._event_has_alt_modifier(event):
            return self._toggle_preview_char_label_mode(event)

        active_label_idx = getattr(self, "_preview_char_label_active_index", None)
        if keysym in {"left", "right"} and (label_mode_active or active_label_idx is not None):
            step = -1 if keysym == "left" else 1
            return self._cycle_preview_character_selection(step, activate_label=True)
        typed_symbol = self._sanitize_preview_char_symbol(getattr(event, "char", ""))
        if active_label_idx is not None and typed_symbol:
            if self._assign_character_to_active_preview_label(typed_symbol):
                return "break"

        if keysym in {"return", "kp_enter"}:
            return self._on_preview_enter_fullscreen_shortcut(event)
        if keysym == "escape":
            return self._on_preview_escape_shortcut(event)
        if keysym == "q":
            return self._on_preview_prev_shortcut(event)
        if keysym == "e":
            return self._on_preview_next_shortcut(event)
        if keysym == "f":
            return self._on_preview_fit_shortcut(event)
        if keysym == "space":
            step = -1 if self._event_has_shift_modifier(event) else 1
            return self._cycle_preview_character_selection(
                step,
                activate_label=bool(getattr(self, "_preview_char_label_mode", False)),
            )
        if keysym == "d":
            if active_label_idx is None:
                self._ensure_preview_final_box_mode()
                self._preview_char_add_modifier_down = True
                self._apply_preview_canvas_cursor()
                self._update_preview_edit_status("Przytrzymaj D i przeciagnij LPM, aby narysowac nowy box znaku.", tone="info")
                return "break"
            return None
        if keysym == "n":
            if active_label_idx is None:
                return self._toggle_preview_char_add_mode(event)
            return None
        if keysym == "s":
            if not bool(getattr(self, "_preview_char_label_mode", False)):
                return self._select_hovered_preview_char_box(event)
            return None
        if keysym == "t":
            if active_label_idx is None:
                return self._edit_selected_preview_char_symbol(event)
            return None
        return None

    def _on_preview_canvas_keyrelease(self, event=None):
        if event is None:
            return None
        keysym = str(getattr(event, "keysym", "") or "").lower()
        if keysym == "d" and bool(getattr(self, "_preview_char_add_modifier_down", False)):
            self._preview_char_add_modifier_down = False
            self._apply_preview_canvas_cursor()
            if getattr(self, "_preview_char_add_state", None) is None:
                self._update_preview_edit_status()
            return "break"
        return None

    def _toggle_preview_fullscreen(self):
        self._set_preview_fullscreen(not bool(getattr(self, "_preview_fullscreen_active", False)))

    def _get_preview_legend_font(self, size: int, weight: str = "normal"):
        cache = getattr(self, "_preview_legend_font_cache", None)
        if cache is None:
            cache = {}
            self._preview_legend_font_cache = cache

        key = (int(size), str(weight))
        font_obj = cache.get(key)
        if font_obj is None:
            font_obj = tkfont.Font(self.frame, family="Segoe UI", size=int(size), weight=str(weight))
            cache[key] = font_obj
        return font_obj

    @staticmethod
    def _truncate_preview_filename(filename: str, max_chars: int = 44) -> str:
        text = str(filename or "").strip()
        if len(text) <= max_chars:
            return text
        head = max(10, (max_chars // 2) - 2)
        tail = max(10, max_chars - head - 3)
        return f"{text[:head]}...{text[-tail:]}"

    def _get_preview_legend_context(self):
        current_idx = self._get_current_preview_list_index()
        total = len(getattr(self, "_listbox_pid_by_index", []))
        current_no = (int(current_idx) + 1) if current_idx is not None and total > 0 else 0
        pid = str(getattr(self, "_preview_active_pid", "") or "Brak tablicy")
        active_data = self._get_preview_active_data(create=False) or {}
        source_image = str(active_data.get("source_image", "") or "")
        filename = self._truncate_preview_filename(Path(source_image).name if source_image else pid)
        chars = self._get_preview_active_character_records(create=False)
        mode_text = (
            "Tryb: nowy box" if self._preview_char_add_requested() else
            ("Tryb: znakowanie" if bool(getattr(self, "_preview_char_label_mode", False)) else
             ("Tryb: edycja" if self._preview_char_edit_mode else "Tryb: podglad"))
        )
        return {
            "filename": filename or "Brak obrazu",
            "image_text": f"Tablica: {current_no}/{total}",
            "vehicle_text": mode_text,
            "plate_text": f"Boxy: {len(chars)}",
        }

    @staticmethod
    def _legend_color_is_light(color: str) -> bool:
        value = str(color or "").strip().lstrip("#")
        if len(value) == 3:
            value = "".join(ch * 2 for ch in value)
        if len(value) != 6:
            return False
        try:
            red = int(value[0:2], 16)
            green = int(value[2:4], 16)
            blue = int(value[4:6], 16)
        except Exception:
            return False
        luminance = ((0.2126 * red) + (0.7152 * green) + (0.0722 * blue)) / 255.0
        return luminance >= 0.62

    def _get_preview_legend_text_color(self, fill: str) -> str:
        palette = getattr(self.app, "palette", {})
        if self._legend_color_is_light(fill):
            return palette.get("fg", "#111111")
        return palette.get("accent_text", "#ffffff")

    def _get_preview_legend_theme(self) -> dict:
        palette = getattr(self.app, "palette", {})
        panel = palette.get("panel", "#252526")
        panel_alt = palette.get("panel_alt", panel)
        field = palette.get("field", panel)
        border = palette.get("panel_border", palette.get("border", "#3c3c3c"))
        accent = palette.get("accent", "#0e639c")
        success = palette.get("success", "#2fbf71")
        warning = palette.get("warning", "#f59e0b")

        return {
            "canvas_bg": panel,
            "panel_fill": panel_alt,
            "panel_outline": border,
            "label_fill": palette.get("fg", "#f3f3f3"),
            "muted_fill": palette.get("muted_dim", palette.get("muted", "#8f98a3")),
            "entry_fill": blend_hex_colors(panel_alt, panel, 0.28),
            "entry_text": palette.get("fg", "#f3f3f3"),
            "section_fill": blend_hex_colors(panel_alt, panel, 0.18),
            "section_title": palette.get("fg", "#f3f3f3"),
            "section_muted": blend_hex_colors(palette.get("fg", "#f3f3f3"), panel_alt, 0.18),
            "token_fill": field,
            "token_text": palette.get("fg", "#f8fafc"),
            "badge_file_fill": palette.get("surface_info", blend_hex_colors(accent, panel_alt, 0.72)),
            "badge_file_outline": accent,
            "badge_image_fill": palette.get("surface_warning", blend_hex_colors(warning, panel_alt, 0.72)),
            "badge_image_outline": warning,
            "badge_plate_fill": palette.get("surface_success", blend_hex_colors(success, panel_alt, 0.72)),
            "badge_plate_outline": success,
        }

    def _measure_preview_legend_token(self, token_kind: str, token_text: str, font_obj) -> float:
        if token_kind == "mouse":
            return max(42.0, float(font_obj.measure(str(token_text))) + 32.0)
        return max(24.0, float(font_obj.measure(str(token_text))) + 12.0)

    def _draw_preview_legend_badge(self, canvas, x: float, y: float, text: str, *, fill: str, outline: str, text_fill: str):
        font_obj = self._get_preview_legend_font(10, "bold")
        text_id = canvas.create_text(
            x + 12,
            y + 9,
            text=str(text),
            fill=text_fill,
            anchor="nw",
            font=font_obj,
            tags=("preview_legend",)
        )
        bbox = canvas.bbox(text_id) or (x, y, x + 40, y + 18)
        rect_id = canvas.create_rectangle(
            bbox[0] - 8,
            bbox[1] - 5,
            bbox[2] + 8,
            bbox[3] + 5,
            fill=fill,
            outline=outline,
            width=1,
            tags=("preview_legend",)
        )
        canvas.tag_lower(rect_id, text_id)
        final_bbox = canvas.bbox(rect_id) or bbox
        return float(final_bbox[2] - final_bbox[0]), float(final_bbox[3] - final_bbox[1])

    def _draw_preview_legend_keycap(self, canvas, x: float, y: float, text: str, *, fill: str, outline: str, text_fill: str):
        font_obj = self._get_preview_legend_font(8, "bold")
        width = self._measure_preview_legend_token("key", text, font_obj)
        height = 21.0
        canvas.create_rectangle(
            x,
            y,
            x + width,
            y + height,
            fill=fill,
            outline=outline,
            width=1,
            tags=("preview_legend",)
        )
        canvas.create_line(
            x + 1,
            y + 1,
            x + width - 1,
            y + 1,
            fill="#ffffff",
            width=1,
            tags=("preview_legend",)
        )
        canvas.create_text(
            x + (width / 2.0),
            y + (height / 2.0) + 0.5,
            text=str(text),
            fill=text_fill,
            anchor="center",
            font=font_obj,
            tags=("preview_legend",)
        )
        return float(width), float(height)

    def _draw_preview_legend_mousecap(self, canvas, x: float, y: float, text: str, *, fill: str, outline: str, text_fill: str):
        font_obj = self._get_preview_legend_font(7, "bold")
        width = self._measure_preview_legend_token("mouse", text, font_obj)
        height = 24.0
        rect_id = canvas.create_rectangle(
            x,
            y,
            x + width,
            y + height,
            fill=fill,
            outline=outline,
            width=1,
            tags=("preview_legend",)
        )
        body_left = x + 7
        body_top = y + 3
        body_right = body_left + 16
        body_bottom = y + 21
        center_x = (body_left + body_right) / 2.0
        highlight_left = str(text).upper() == "LPM"
        highlight_right = str(text).upper() == "PPM"
        canvas.create_oval(
            body_left,
            body_top,
            body_right,
            body_bottom,
            fill="#f7f9fb",
            outline=outline,
            width=1,
            tags=("preview_legend",)
        )
        canvas.create_rectangle(
            body_left + 1,
            body_top + 1,
            center_x - 1,
            body_top + 8,
            fill=(outline if highlight_left else "#f7f9fb"),
            outline="",
            tags=("preview_legend",)
        )
        canvas.create_rectangle(
            center_x + 1,
            body_top + 1,
            body_right - 1,
            body_top + 8,
            fill=(outline if highlight_right else "#f7f9fb"),
            outline="",
            tags=("preview_legend",)
        )
        canvas.create_line(
            center_x,
            body_top + 1,
            center_x,
            body_top + 9,
            fill=outline,
            width=1,
            tags=("preview_legend",)
        )
        canvas.create_text(
            body_right + 8,
            y + (height / 2.0) + 0.5,
            text=str(text),
            fill=text_fill,
            anchor="w",
            font=font_obj,
            tags=("preview_legend",)
        )
        canvas.tag_lower(rect_id)
        return float(width), float(height)

    def _build_preview_legend_sections(self):
        return [
            {
                "title": "Nawigacja",
                "accent": "#2f80ed",
                "items": [
                    {"tokens": ["Q", "E"], "connector": "/", "label": "zmiana tablic"},
                    {"tokens": ["F"], "label": "dopasuj widok"},
                    {"tokens": ["Rolka"], "label": "zoom in / out"},
                    {"tokens": ["Enter"], "label": "pełny ekran / wyjście"},
                ],
            },
            {
                "title": "Boxy",
                "accent": "#22c55e",
                "items": [
                    {"tokens": ["D", "LPM"], "connector": "+", "label": "nowy box"},
                    {"tokens": ["S"], "label": "select / off"},
                    {"tokens": ["LPM"], "label": "przesuń lub resize"},
                    {"tokens": ["PPM"], "label": "usuń aktywny"},
                    {"tokens": ["Ctrl+Z", "Ctrl+Y"], "connector": "/", "label": "historia"},
                ],
            },
            {
                "title": "Znaki",
                "accent": "#f59e0b",
                "items": [
                    {"tokens": ["Alt+W"], "label": "tryb wpisywania"},
                    {"tokens": ["LPM"], "label": "wybierz pole"},
                    {"tokens": ["←", "→"], "connector": "/", "label": "pole +/-"},
                    {"tokens": ["0-9/A-Z"], "label": "wpisz znak"},
                    {"tokens": ["Esc"], "label": "wyjdz z wpisywania"},
                ],
            },
        ]

    def _refresh_preview_controls_legend(self):
        canvas = getattr(self, "preview_controls_canvas", None)
        if canvas is None:
            return

        if not bool(getattr(self, "_preview_fullscreen_active", False)):
            try:
                canvas.delete("all")
                canvas.configure(height=1)
            except Exception:
                pass
            return

        try:
            canvas.update_idletasks()
        except Exception:
            pass

        width = max(420.0, float(canvas.winfo_width() or 0.0))
        canvas.delete("all")
        legend_theme = self._get_preview_legend_theme()
        bg_fill = legend_theme["panel_fill"]
        bg_outline = legend_theme["panel_outline"]
        plus_fill = legend_theme["muted_fill"]
        try:
            canvas.configure(bg=legend_theme["canvas_bg"])
        except Exception:
            pass

        sections = self._build_preview_legend_sections()
        background_id = canvas.create_rectangle(
            1,
            1,
            width - 2,
            96,
            fill=bg_fill,
            outline=bg_outline,
            width=1,
            tags=("preview_legend",)
        )

        outer_pad_x = 14.0
        outer_pad_y = 7.0
        section_gap_x = 10.0
        section_gap_y = 8.0
        section_pad_x = 10.0
        section_pad_y = 8.0
        title_gap_y = 6.0
        item_gap_y = 6.0
        token_gap = 5.0
        label_gap_x = 8.0
        item_row_height = 22.0
        title_font = self._get_preview_legend_font(8, "bold")
        desc_font = self._get_preview_legend_font(8, "bold")

        if width >= 920.0:
            column_count = 3
        elif width >= 620.0:
            column_count = 2
        else:
            column_count = 1

        column_count = max(1, min(column_count, len(sections)))
        section_width = max(
            180.0,
            (width - (outer_pad_x * 2.0) - (section_gap_x * (column_count - 1))) / float(column_count),
        )

        section_heights = []
        for section in sections:
            item_count = len(section.get("items", []))
            section_height = (
                section_pad_y
                + float(title_font.metrics("linespace"))
                + title_gap_y
                + max(1, item_count) * item_row_height
                + max(0, item_count - 1) * item_gap_y
                + section_pad_y
            )
            section_heights.append(section_height)

        row_heights = []
        for start_idx in range(0, len(sections), column_count):
            row_heights.append(max(section_heights[start_idx:start_idx + column_count]))

        y_offsets = []
        current_y = outer_pad_y
        for row_height in row_heights:
            y_offsets.append(current_y)
            current_y += row_height + section_gap_y

        max_bottom = outer_pad_y
        for idx, section in enumerate(sections):
            row_idx = idx // column_count
            col_idx = idx % column_count
            section_x = outer_pad_x + (col_idx * (section_width + section_gap_x))
            section_y = y_offsets[row_idx]
            section_height = section_heights[idx]
            accent = str(section.get("accent", "#3498db"))

            section_rect = canvas.create_rectangle(
                section_x,
                section_y,
                section_x + section_width,
                section_y + section_height,
                fill=legend_theme["section_fill"],
                outline=accent,
                width=1,
                tags=("preview_legend",)
            )
            canvas.tag_lower(section_rect)

            canvas.create_text(
                section_x + section_pad_x,
                section_y + section_pad_y,
                text=str(section.get("title", "")),
                fill=legend_theme["section_title"],
                anchor="nw",
                font=title_font,
                tags=("preview_legend",)
            )

            item_y = section_y + section_pad_y + float(title_font.metrics("linespace")) + title_gap_y
            for item in section.get("items", []):
                tokens = [str(token) for token in item.get("tokens", [])]
                connector = str(item.get("connector", "") or "")
                label = str(item.get("label", "") or "")
                token_x = section_x + section_pad_x
                prev_right = None

                for token_idx, token_text in enumerate(tokens):
                    if token_idx > 0 and connector:
                        connector_x = float(prev_right) + (token_gap / 2.0)
                        canvas.create_text(
                        connector_x,
                            item_y + 10.0,
                            text=connector,
                            fill=plus_fill,
                            anchor="center",
                            font=self._get_preview_legend_font(7, "bold"),
                            tags=("preview_legend",)
                        )
                    token_w, _token_h = self._draw_preview_legend_keycap(
                        canvas,
                        token_x,
                        item_y,
                        token_text,
                        fill=legend_theme["token_fill"],
                        outline=accent,
                        text_fill=legend_theme["token_text"],
                    )
                    prev_right = token_x + float(token_w)
                    if token_idx < (len(tokens) - 1):
                        token_x = prev_right + token_gap

                    label_x = min(
                    section_x + section_width - section_pad_x - 56.0,
                    max(section_x + section_pad_x + 88.0, float(prev_right or token_x) + label_gap_x),
                )
                canvas.create_text(
                    label_x,
                    item_y + 10.0,
                    text=label,
                    fill=legend_theme["section_muted"],
                    anchor="w",
                    width=max(48.0, (section_x + section_width - section_pad_x) - label_x),
                    font=desc_font,
                    tags=("preview_legend",)
                )
                item_y += item_row_height + item_gap_y

            max_bottom = max(max_bottom, section_y + section_height)

        total_height = max(86.0, max_bottom + outer_pad_y)
        canvas.coords(background_id, 1, 1, width - 2, total_height - 2)
        try:
            canvas.configure(height=int(total_height))
        except Exception:
            pass

    def _apply_preview_fullscreen_chrome(self):
        preview_tools = getattr(self, "preview_tools", None)
        preview_hint_frame = getattr(self, "preview_hint_frame", None)

        if bool(getattr(self, "_preview_fullscreen_active", False)):
            try:
                if preview_tools is not None:
                    preview_tools.grid_remove()
            except Exception:
                pass
            try:
                if preview_hint_frame is not None:
                    preview_hint_frame.grid()
                    self._refresh_preview_controls_legend()
            except Exception:
                pass
            self._sync_preview_edit_status_visibility()
            self._refresh_preview_typing_overlay_visibility()
            return

        try:
            if preview_hint_frame is not None:
                preview_hint_frame.grid_remove()
        except Exception:
            pass
        try:
            if preview_tools is not None:
                preview_tools.grid()
        except Exception:
            pass
        self._sync_preview_edit_status_visibility()
        self._refresh_preview_typing_overlay_visibility()

    def _set_preview_fullscreen(self, active: bool):
        next_state = bool(active)
        if next_state == bool(getattr(self, "_preview_fullscreen_active", False)):
            if next_state:
                self._focus_preview_canvas()
            return

        has_image = bool(getattr(self, "_preview_render_state", None))
        if next_state and not has_image:
            self._update_preview_edit_status("Pełny ekran jest dostępny po zaladowaniu obrazu podgladu.", tone="warning")
            return

        root = getattr(self.app, "root", None)
        try:
            windowing_system = str(self.frame.tk.call("tk", "windowingsystem")).lower()
        except Exception:
            windowing_system = ""
        use_native_root_fullscreen = windowing_system not in {"win32"}

        split = getattr(self, "detect_split", None)
        right_panel = getattr(self, "detect_right_panel", None)
        preview_split = getattr(self, "preview_vertical_split", None)
        list_panel = getattr(self, "preview_list_lf", None)
        footer_nav = getattr(self, "detect_footer_nav", None)
        log_frame = getattr(self, "detection_log_frame", None)

        if next_state:
            self._preview_fullscreen_restore_log_visible = bool(getattr(self, "_detection_log_visible", False))
            try:
                self._preview_fullscreen_restore_root_state = bool(root.attributes("-fullscreen")) if root is not None else False
            except Exception:
                self._preview_fullscreen_restore_root_state = False
            try:
                self._preview_fullscreen_restore_window_state = str(root.state()) if root is not None else "normal"
            except Exception:
                self._preview_fullscreen_restore_window_state = "normal"
            try:
                self._preview_fullscreen_restore_geometry = str(root.geometry()) if root is not None else ""
            except Exception:
                self._preview_fullscreen_restore_geometry = ""

            try:
                if self._pane_has_child(split, right_panel):
                    split.forget(right_panel)
            except Exception:
                pass
            try:
                if self._pane_has_child(preview_split, list_panel):
                    preview_split.forget(list_panel)
            except Exception:
                pass
            try:
                if log_frame is not None:
                    log_frame.grid_remove()
            except Exception:
                pass
            try:
                if footer_nav is not None:
                    footer_nav.grid_remove()
            except Exception:
                pass

            self._set_detection_process_log_visibility(False)
            if root is not None:
                try:
                    if use_native_root_fullscreen:
                        root.attributes("-fullscreen", True)
                    else:
                        root.attributes("-fullscreen", False)
                        try:
                            root.state("zoomed")
                        except Exception:
                            screen_w = int(root.winfo_screenwidth())
                            screen_h = int(root.winfo_screenheight())
                            root.geometry(f"{screen_w}x{screen_h}+0+0")
                except Exception:
                    pass
            self._preview_fullscreen_active = True
            self._preview_mode_overlay_position = self._get_preview_mode_overlay_default_position(fullscreen=True)
        else:
            if root is not None:
                try:
                    if use_native_root_fullscreen:
                        root.attributes("-fullscreen", bool(getattr(self, "_preview_fullscreen_restore_root_state", False)))
                    else:
                        root.attributes("-fullscreen", False)
                        restore_state = str(getattr(self, "_preview_fullscreen_restore_window_state", "normal") or "normal")
                        restore_geometry = str(getattr(self, "_preview_fullscreen_restore_geometry", "") or "")
                        try:
                            root.state(restore_state if restore_state in {"normal", "zoomed"} else "normal")
                        except Exception:
                            pass
                        if restore_state != "zoomed" and restore_geometry:
                            try:
                                root.geometry(restore_geometry)
                            except Exception:
                                pass
                except Exception:
                    pass

            try:
                if not self._pane_has_child(split, right_panel) and right_panel is not None:
                    split.add(right_panel, weight=2)
            except Exception:
                pass
            try:
                if not self._pane_has_child(preview_split, list_panel) and list_panel is not None:
                    preview_split.add(list_panel, minsize=240, before=getattr(self, "preview_lf", None))
            except Exception:
                pass
            try:
                if footer_nav is not None:
                    footer_nav.grid()
            except Exception:
                pass
            self._set_detection_process_log_visibility(bool(getattr(self, "_preview_fullscreen_restore_log_visible", False)))
            self._preview_fullscreen_active = False

        self._apply_preview_fullscreen_chrome()
        self._update_preview_toolbar_state()
        self._refresh_preview_controls_legend()
        self._on_preview_select(None)
        try:
            self.frame.after_idle(self._ensure_preview_mode_overlay_position)
        except Exception:
            self._ensure_preview_mode_overlay_position()
        self._focus_preview_canvas()

    def _update_preview_toolbar_state(self):
        total = len(getattr(self, "_listbox_pid_by_index", []))
        current_idx = self._get_current_preview_list_index()
        has_selection = current_idx is not None and total > 0
        has_image = bool(getattr(self, "_preview_render_state", None))
        can_go_prev = has_selection and int(current_idx) > 0
        can_go_next = has_selection and int(current_idx) < (total - 1)

        button_specs = (
            ("preview_prev_btn", can_go_prev),
            ("preview_next_btn", can_go_next),
            ("preview_fit_btn", has_image),
            ("preview_fullscreen_btn", has_image),
        )
        for attr_name, enabled in button_specs:
            widget = getattr(self, attr_name, None)
            if widget is None:
                continue
            try:
                widget.configure(state=(tk.NORMAL if enabled else tk.DISABLED))
            except Exception:
                pass

        fullscreen_btn = getattr(self, "preview_fullscreen_btn", None)
        if fullscreen_btn is not None:
            try:
                fullscreen_btn.configure(
                    text=("Wyjdz z pelnego ekranu (Enter)" if self._preview_fullscreen_active else "Pełny ekran (Enter)")
                )
            except Exception:
                pass

    def _extract_preview_badge_key_from_current_item(self):
        canvas = getattr(self, "preview_canvas", None)
        if canvas is None:
            return None

        try:
            tags = canvas.gettags("current")
        except Exception:
            return None

        for tag in tags:
            if str(tag).startswith("preview_badge::"):
                return str(tag).split("preview_badge::", 1)[1]
        return None

    def _extract_preview_action_from_current_item(self):
        canvas = getattr(self, "preview_canvas", None)
        if canvas is None:
            return None

        try:
            tags = canvas.gettags("current")
        except Exception:
            return None

        for tag in tags:
            if str(tag).startswith("preview_action::"):
                return str(tag).split("preview_action::", 1)[1]
        return None

    def _on_preview_canvas_press(self, event):
        self._focus_preview_canvas()
        action_key = self._extract_preview_action_from_current_item()
        if action_key == "reset_view":
            self._reset_current_preview_view()
            return "break"
        if action_key == "edit_source_filename":
            return self._edit_preview_source_filename(event)

        badge_key = self._extract_preview_badge_key_from_current_item()
        if badge_key:
            self._set_preview_selected_badge(badge_key)
            self._preview_pan_drag_state = None
            start_dx, start_dy = self._get_preview_badge_offset(self._preview_active_pid, badge_key)
            self._preview_badge_drag_state = {
                "badge_key": str(badge_key),
                "start_x": float(event.x),
                "start_y": float(event.y),
                "start_dx": float(start_dx),
                "start_dy": float(start_dy),
            }
            try:
                self.preview_canvas.configure(cursor="hand2")
            except Exception:
                pass
            return "break"

        if not getattr(self, "_preview_render_state", None):
            return

        self._set_preview_selected_badge(None)
        self._preview_badge_drag_state = None
        self._preview_pan_drag_state = None
        label_hit = self._find_preview_char_label_hit(event.x, event.y)
        box_hit = self._find_preview_character_box_hit(event.x, event.y)

        if bool(getattr(self, "_preview_char_label_mode", False)):
            target_idx = label_hit if label_hit is not None else box_hit
            if target_idx is not None:
                return self._select_preview_character_box(
                    int(target_idx),
                    activate_label=True,
                    status_message="Wpisywanie znaków: wpisz 0-9 lub A-Z, aby nadpisac znak w aktywnym boxie.",
                )

        if label_hit is not None and getattr(self, "_preview_char_label_active_index", None) is not None:
            self._preview_char_edit_mode = True
            self._preview_char_selected_index = int(label_hit)
            self._preview_char_hover_label_index = int(label_hit)
            self._refresh_preview_editor_toolbar()
            self._activate_preview_char_label_input(
                int(label_hit),
                status_message="Pole znaku pozostaje aktywne. Wpisz 0-9 lub A-Z, aby nadpisać etykietę, albo Esc aby wyjść.",
            )
            return "break"

        if getattr(self, "_preview_char_label_active_index", None) is not None:
            self._preview_char_label_active_index = None

        if self._preview_char_add_requested() and self._preview_point_inside_image(event.x, event.y):
            self._preview_char_edit_mode = False
            img_x, img_y = self._preview_canvas_to_image_point(event.x, event.y)
            self._preview_char_selected_index = None
            self._preview_char_add_state = {
                "start_img_x": float(img_x),
                "start_img_y": float(img_y),
                "bbox": [float(img_x), float(img_y), float(img_x), float(img_y)],
                "dirty": False,
            }
            self._refresh_preview_editor_toolbar()
            try:
                self.preview_canvas.configure(cursor="crosshair")
            except Exception:
                pass
            self._on_preview_select(None)
            return "break"

        handle_hit = self._find_preview_character_handle_hit(event.x, event.y)
        if handle_hit is not None and bool(getattr(self, "_preview_char_edit_mode", False)):
            char_idx, handle_name = handle_hit
            chars = self._get_preview_active_character_records(create=False)
            if 0 <= int(char_idx) < len(chars):
                rec = chars[int(char_idx)]
                bbox = self._char_record_bbox(rec)
                if bbox:
                    img_x, img_y = self._preview_canvas_to_image_point(event.x, event.y)
                    self._preview_char_selected_index = int(char_idx)
                    self._preview_char_drag_state = {
                        "index": int(char_idx),
                        "mode": "resize",
                        "handle": str(handle_name),
                        "start_img_x": float(img_x),
                        "start_img_y": float(img_y),
                        "start_bbox": list(bbox),
                        "dirty": False,
                        "history_pushed": False,
                    }
                    self._refresh_preview_editor_toolbar()
                    try:
                        self.preview_canvas.configure(cursor="crosshair")
                    except Exception:
                        pass
                    self._on_preview_select(None)
                    return "break"

        if box_hit is not None:
            self._refresh_preview_editor_toolbar()
            if (
                bool(getattr(self, "_preview_char_edit_mode", False))
                and getattr(self, "_preview_char_selected_index", None) is not None
                and int(self._preview_char_selected_index) == int(box_hit)
            ):
                chars = self._get_preview_active_character_records(create=False)
                if 0 <= int(box_hit) < len(chars):
                    rec = chars[int(box_hit)]
                    bbox = self._char_record_bbox(rec)
                    if bbox:
                        img_x, img_y = self._preview_canvas_to_image_point(event.x, event.y)
                        self._preview_char_drag_state = {
                            "index": int(box_hit),
                            "mode": "move",
                            "start_img_x": float(img_x),
                            "start_img_y": float(img_y),
                            "start_bbox": list(bbox),
                            "dirty": False,
                            "history_pushed": False,
                        }
                        try:
                            self.preview_canvas.configure(cursor="fleur")
                        except Exception:
                            pass
                self._on_preview_select(None)
                return "break"

            self._update_preview_edit_status(
                "Najedz kursorem na box i nacisnij S, aby go zaznaczyc. Zaznaczony box przesuniesz LPM, zmienisz uchwytami i usuniesz PPM.",
                tone="info",
            )
            return "break"

        self._preview_char_selected_index = None
        self._refresh_preview_editor_toolbar()
        self._preview_pan_drag_state = {
            "start_x": float(event.x),
            "start_y": float(event.y),
            "start_pan_x": float(self._preview_pan_x),
            "start_pan_y": float(self._preview_pan_y),
        }
        try:
            self.preview_canvas.configure(cursor="fleur")
        except Exception:
            pass
        self._on_preview_select(None)
        return "break"

    def _on_preview_canvas_secondary_press(self, event=None):
        self._focus_preview_canvas()
        if event is None or not getattr(self, "_preview_render_state", None):
            return None

        box_hit = self._find_preview_character_box_hit(event.x, event.y)
        if box_hit is None:
            if getattr(self, "_preview_char_label_active_index", None) is not None:
                self._preview_char_label_active_index = None
                self._update_preview_edit_status("Zamknieto aktywne pole znaku.", tone="muted")
                self._on_preview_select(None)
                return "break"
            return None

        selected_idx = getattr(self, "_preview_char_selected_index", None)
        if selected_idx is None or int(selected_idx) != int(box_hit):
            self._update_preview_edit_status(
                "PPM usuwa tylko aktywny box. Najedz kursorem na wybrany box i nacisnij S, aby go zaznaczyc.",
                tone="warning",
            )
            self._on_preview_select(None)
            return "break"

        self._preview_char_label_active_index = None
        self._preview_char_hover_label_index = None
        self._refresh_preview_editor_toolbar()
        return self._delete_selected_preview_char_box(event)

    def _on_preview_canvas_drag(self, event):
        drag_state = self._preview_badge_drag_state
        if isinstance(drag_state, dict):
            badge_key = drag_state.get("badge_key")
            new_dx = float(drag_state.get("start_dx", 0.0)) + (float(event.x) - float(drag_state.get("start_x", 0.0)))
            new_dy = float(drag_state.get("start_dy", 0.0)) + (float(event.y) - float(drag_state.get("start_y", 0.0)))
            new_dx, new_dy = self._clamp_preview_badge_offset(badge_key, new_dx, new_dy)
            self._set_preview_badge_offset(self._preview_active_pid, badge_key, new_dx, new_dy)
            self._move_preview_badge_to_offset(badge_key, new_dx, new_dy)
            return "break"

        char_drag_state = getattr(self, "_preview_char_drag_state", None)
        if isinstance(char_drag_state, dict):
            chars = self._get_preview_active_character_records(create=False)
            char_idx = int(char_drag_state.get("index", -1))
            if 0 <= char_idx < len(chars):
                rec = chars[char_idx]
                bbox = list(char_drag_state.get("start_bbox", rec.get("bbox", [0, 0, 0, 0])))
                img_x, img_y = self._preview_canvas_to_image_point(event.x, event.y)
                mode = str(char_drag_state.get("mode", "move") or "move").lower()

                if mode == "move":
                    start_x = float(char_drag_state.get("start_img_x", img_x))
                    start_y = float(char_drag_state.get("start_img_y", img_y))
                    delta_x = float(img_x) - start_x
                    delta_y = float(img_y) - start_y
                    width = max(1.0, float(bbox[2]) - float(bbox[0]))
                    height = max(1.0, float(bbox[3]) - float(bbox[1]))
                    state = getattr(self, "_preview_render_state", None) or {}
                    max_w = max(width, float(state.get("orig_w", width)))
                    max_h = max(height, float(state.get("orig_h", height)))
                    new_x1 = min(max(0.0, float(bbox[0]) + delta_x), max_w - width)
                    new_y1 = min(max(0.0, float(bbox[1]) + delta_y), max_h - height)
                    new_bbox = [new_x1, new_y1, new_x1 + width, new_y1 + height]
                else:
                    handle_name = str(char_drag_state.get("handle", "se") or "se").lower()
                    x1, y1, x2, y2 = bbox
                    if "w" in handle_name:
                        x1 = float(img_x)
                    else:
                        x2 = float(img_x)
                    if "n" in handle_name:
                        y1 = float(img_y)
                    else:
                        y2 = float(img_y)
                    new_bbox = [x1, y1, x2, y2]

                normalized_bbox = self._normalize_preview_char_bbox(new_bbox)
                if normalized_bbox is not None:
                    if not bool(char_drag_state.get("history_pushed")):
                        self._push_preview_history_snapshot()
                        char_drag_state["history_pushed"] = True
                    rec["bbox"] = normalized_bbox
                    self._mark_preview_char_record_manual(rec)
                    char_drag_state["dirty"] = True
                    self._on_preview_select(None)
            return "break"

        char_add_state = getattr(self, "_preview_char_add_state", None)
        if isinstance(char_add_state, dict):
            img_x, img_y = self._preview_canvas_to_image_point(event.x, event.y)
            char_add_state["bbox"] = [
                float(char_add_state.get("start_img_x", img_x)),
                float(char_add_state.get("start_img_y", img_y)),
                float(img_x),
                float(img_y),
            ]
            char_add_state["dirty"] = True
            self._on_preview_select(None)
            return "break"

        pan_state = self._preview_pan_drag_state
        if not isinstance(pan_state, dict):
            return

        self._preview_pan_x = float(pan_state.get("start_pan_x", 0.0)) + (float(event.x) - float(pan_state.get("start_x", 0.0)))
        self._preview_pan_y = float(pan_state.get("start_pan_y", 0.0)) + (float(event.y) - float(pan_state.get("start_y", 0.0)))
        self._on_preview_select(None)
        return "break"

    def _on_preview_canvas_release(self, event):
        char_drag_state = getattr(self, "_preview_char_drag_state", None)
        if isinstance(char_drag_state, dict):
            self._preview_char_drag_state = None
            try:
                self.preview_canvas.configure(cursor="arrow")
            except Exception:
                pass
            if bool(char_drag_state.get("dirty")):
                chars = self._get_preview_active_character_records(create=False)
                char_idx = int(char_drag_state.get("index", -1))
                selected_record = chars[char_idx] if 0 <= char_idx < len(chars) else None
                self._persist_active_preview_characters(
                    selected_record=selected_record,
                    success_message="Zapisano ręczna korekte boxu znaku w metadata.json.",
                )
            else:
                self._on_preview_select(None)
            return "break"

        char_add_state = getattr(self, "_preview_char_add_state", None)
        if isinstance(char_add_state, dict):
            self._preview_char_add_state = None
            try:
                self.preview_canvas.configure(cursor=("crosshair" if self._preview_char_add_requested() else "arrow"))
            except Exception:
                pass

            bbox = self._normalize_preview_char_bbox(char_add_state.get("bbox"))
            if bbox is None:
                self._on_preview_select(None)
                return "break"

            width = float(bbox[2]) - float(bbox[0])
            height = float(bbox[3]) - float(bbox[1])
            if width < 6.0 or height < 6.0:
                self._set_preview_box_info("Nowy box jest zbyt maly. Sprobuj ponownie.", "warning")
                self._update_preview_edit_status("Nowy box jest zbyt maly. Sprobuj ponownie.", tone="warning")
                self._on_preview_select(None)
                return "break"

            chars = self._get_preview_active_character_records(create=True)
            self._push_preview_history_snapshot()
            new_record = {
                "character": "",
                "bbox": bbox,
                "confidence": 1.0,
                "method": "manual",
                "source_tag": "ocr",
            }
            chars.append(new_record)
            self._mark_preview_char_record_manual(new_record)
            self._preview_char_edit_mode = True
            self._preview_char_label_active_index = None
            self._preview_char_hover_label_index = None
            self._persist_active_preview_characters(
                selected_record=new_record,
                success_message="Dodano nowy box znaku do metadata.json.",
            )
            self._update_preview_edit_status(
                "Dodano nowy box. Pozostaje zaznaczony do dalszej korekty, ale nie wlacza pola wpisywania znaku.",
                tone="success",
            )
            self._on_preview_select(None)
            return "break"

        if self._preview_badge_drag_state is None and self._preview_pan_drag_state is None:
            return
        self._preview_badge_drag_state = None
        self._preview_pan_drag_state = None
        try:
            self.preview_canvas.configure(cursor=("crosshair" if self._preview_char_add_requested() else "arrow"))
        except Exception:
            pass
        return "break"

    def _on_preview_canvas_mousewheel(self, event):
        if not getattr(self, "_preview_render_state", None):
            return
        if (
            self._preview_badge_drag_state is not None
            or self._preview_pan_drag_state is not None
            or self._preview_char_drag_state is not None
            or self._preview_char_add_state is not None
        ):
            return "break"

        delta = 0
        if hasattr(event, "delta") and event.delta:
            delta = int(event.delta)
        elif hasattr(event, "num"):
            if int(event.num) == 4:
                delta = 120
            elif int(event.num) == 5:
                delta = -120

        if delta == 0:
            return

        current_zoom = float(self._preview_zoom_level)
        target_zoom = current_zoom * self._preview_zoom_step if delta > 0 else current_zoom / self._preview_zoom_step
        target_zoom = max(self._preview_zoom_min, min(self._preview_zoom_max, target_zoom))
        if abs(target_zoom - current_zoom) < 1e-6:
            return "break"

        state = dict(self._preview_render_state)
        canvas_x = float(event.x)
        canvas_y = float(event.y)
        image_left = float(state.get("image_left", 0.0))
        image_top = float(state.get("image_top", 0.0))
        image_right = float(state.get("image_right", image_left))
        image_bottom = float(state.get("image_bottom", image_top))
        current_display_w = max(1.0, image_right - image_left)
        current_display_h = max(1.0, image_bottom - image_top)
        orig_w = max(1.0, float(state.get("orig_w", 1.0)))
        orig_h = max(1.0, float(state.get("orig_h", 1.0)))

        if image_left <= canvas_x <= image_right and image_top <= canvas_y <= image_bottom:
            rel_x = (canvas_x - image_left) / current_display_w
            rel_y = (canvas_y - image_top) / current_display_h
            anchor_x = canvas_x
            anchor_y = canvas_y
        else:
            rel_x = 0.5
            rel_y = 0.5
            anchor_x = float(getattr(self.preview_canvas, "winfo_width", lambda: 0)() or 0) / 2.0
            anchor_y = float(getattr(self.preview_canvas, "winfo_height", lambda: 0)() or 0) / 2.0

        fit_scale = max(0.001, float(state.get("fit_scale", state.get("scale", 1.0))))
        fit_x_off = float(state.get("fit_x_off", image_left))
        fit_y_off = float(state.get("fit_y_off", image_top))
        fit_new_w = max(1.0, float(state.get("fit_new_w", max(1, int(orig_w * fit_scale)))))
        fit_new_h = max(1.0, float(state.get("fit_new_h", max(1, int(orig_h * fit_scale)))))

        next_scale = fit_scale * target_zoom
        next_w = max(1.0, float(max(1, int(orig_w * next_scale))))
        next_h = max(1.0, float(max(1, int(orig_h * next_scale))))
        base_x_off = fit_x_off - ((next_w - fit_new_w) / 2.0)
        base_y_off = fit_y_off - ((next_h - fit_new_h) / 2.0)
        canvas_w = float(getattr(self.preview_canvas, "winfo_width", lambda: 0)() or 0)
        canvas_h = float(getattr(self.preview_canvas, "winfo_height", lambda: 0)() or 0)
        top_reserved = max(0.0, float(state.get("top_reserved", 0.0) or 0.0))
        available_h = max(48.0, canvas_h - top_reserved)
        fits_x = next_w <= canvas_w + 0.5
        fits_y = next_h <= available_h + 0.5

        self._preview_zoom_level = float(target_zoom)
        self._preview_pan_x = 0.0 if fits_x else (anchor_x - base_x_off - (rel_x * next_w))
        self._preview_pan_y = 0.0 if fits_y else (anchor_y - base_y_off - (rel_y * next_h))
        self._on_preview_select(None)
        return "break"

    def _char_record_to_symbol_and_x(self, rec, fallback_index: int = 0):
        symbol = ""
        x_key = float(fallback_index)

        if isinstance(rec, dict):
            symbol = str(
                rec.get("character")
                or rec.get("text")
                or rec.get("char")
                or ""
            )

            bbox = rec.get("bbox")
            if isinstance(bbox, (list, tuple)) and len(bbox) >= 4:
                try:
                    x_key = (float(bbox[0]) + float(bbox[2])) / 2.0
                except Exception:
                    pass

            return symbol, x_key

        if isinstance(rec, str):
            return rec, x_key

        try:
            symbol = str(getattr(rec, "character", getattr(rec, "text", "")) or "")
        except Exception:
            symbol = ""

        try:
            bbox = getattr(rec, "bbox", None)
            if isinstance(bbox, (list, tuple)) and len(bbox) >= 4:
                x_key = (float(bbox[0]) + float(bbox[2])) / 2.0
        except Exception:
            pass

        return symbol, x_key
        
    def _get_preview_dir_plate_count(self, preview_dir=None) -> int:
        preview_dir_raw = str(preview_dir if preview_dir is not None else (self.preview_dir_var.get() or "")).strip()
        if not preview_dir_raw:
            return 0

        try:
            preview_path = Path(preview_dir_raw)
            meta_path = preview_path / "metadata.json"
            images_dir = preview_path / "images"
            if not meta_path.exists() or not images_dir.exists() or not images_dir.is_dir():
                return 0

            with open(meta_path, "r", encoding="utf-8") as f:
                loaded = json.load(f)
            if not isinstance(loaded, dict):
                return 0

            return sum(1 for pid in loaded.keys() if str(pid or "").strip())
        except Exception:
            return 0

    def _preview_dir_has_plate_entries(self, preview_dir=None) -> bool:
        return self._get_preview_dir_plate_count(preview_dir) > 0

    def _find_latest_preview_run_dir(self, require_plates: bool = False) -> str:
        """
        Szuka najnowszej poprawnej paczki preview w katalogu chars projektu.
        Poprawna paczka to katalog zawierający:
        - metadata.json
        - images/
        """
        chars_root = getattr(self, "_campaign_chars_dir", None)
        if not chars_root:
            return ""

        root = Path(chars_root)
        if not root.exists() or not root.is_dir():
            return ""

        candidates = []
        try:
            for p in root.rglob("*"):
                if not p.is_dir():
                    continue

                meta_file = p / "metadata.json"
                images_dir = p / "images"

                if meta_file.exists() and images_dir.exists() and images_dir.is_dir():
                    if require_plates and not self._preview_dir_has_plate_entries(p):
                        continue
                    candidates.append(p)
        except Exception:
            return ""

        if not candidates:
            return ""

        candidates.sort(key=lambda p: p.stat().st_mtime, reverse=True)
        return str(candidates[0])

    def _load_json_file_safely(self, path: Path):
        try:
            with open(path, "r", encoding="utf-8-sig") as f:
                return json.load(f)
        except Exception:
            return None

    def _find_preview_plate_image_path(self, images_dir: Path, pid: str) -> Path | None:
        pid_str = str(pid or "").strip()
        if not pid_str:
            return None
        for ext in sorted(CONFIG.IMAGE_EXTENSIONS):
            candidate = images_dir / f"{pid_str}{ext}"
            if candidate.exists() and candidate.is_file():
                return candidate
        return None

    def _get_preview_plate_image_size(self, preview_dir: Path | None, pid: str) -> tuple[int, int] | None:
        try:
            if preview_dir is None:
                return None
            images_dir = Path(preview_dir) / "images"
            img_path = self._find_preview_plate_image_path(images_dir, pid)
            if img_path is None:
                return None
            img = cv2.imread(str(img_path))
            if img is None:
                return None
            h, w = img.shape[:2]
            if h <= 0 or w <= 0:
                return None
            return int(w), int(h)
        except Exception:
            return None

    def _build_live_ocr_sample_pool(self) -> list[dict]:
        preview_dir_raw = str(self.preview_dir_var.get() or "").strip()
        if not preview_dir_raw or not self.preview_plate_ids:
            return []

        images_dir = Path(preview_dir_raw) / "images"
        if not images_dir.exists() or not images_dir.is_dir():
            return []

        samples = []
        for pid in self.preview_plate_ids:
            pid_str = str(pid or "").strip()
            if not pid_str:
                continue
            img_path = self._find_preview_plate_image_path(images_dir, pid_str)
            if img_path is None:
                continue
            data = self.preview_metadata.get(pid_str, {}) if isinstance(self.preview_metadata, dict) else {}
            expected_texts = self._get_preview_expected_texts(data)
            label = f"ID: {pid_str}"
            if expected_texts:
                label = f"{label}  |  Oczek: {expected_texts[0]}"
            samples.append({
                "sample_id": pid_str,
                "image_path": str(img_path),
                "expected_texts": expected_texts,
                "label": label,
                "source": "preview",
            })
        return samples

    def _get_ocr_demo_dir(self) -> Path:
        demo_dir = self.session_file.parent / "ocr_demo_samples"
        demo_dir.mkdir(parents=True, exist_ok=True)
        return demo_dir

    def _load_cached_ocr_demo_samples(self, limit: int = 3) -> list[dict]:
        demo_dir = self._get_ocr_demo_dir()
        manifest_path = demo_dir / "manifest.json"
        manifest = self._load_json_file_safely(manifest_path)
        if not isinstance(manifest, dict):
            return []

        samples = []
        for idx, item in enumerate(manifest.get("samples") or [], start=1):
            if not isinstance(item, dict):
                continue
            rel_image = str(item.get("image", "") or "").strip()
            if not rel_image:
                continue
            img_path = demo_dir / rel_image
            if not img_path.exists() or not img_path.is_file():
                continue
            expected_texts = [
                str(text or "").strip().upper()
                for text in (item.get("expected_texts") or [])
                if str(text or "").strip()
            ]
            label = str(item.get("label", "") or "").strip()
            if not label:
                label = f"Demo {idx}"
                if expected_texts:
                    label = f"{label}  |  Oczek: {expected_texts[0]}"
            samples.append({
                "sample_id": str(item.get("sample_id", f"demo_{idx:03d}") or f"demo_{idx:03d}"),
                "image_path": str(img_path),
                "expected_texts": expected_texts,
                "label": label,
                "source": "demo",
            })
        return samples[:limit]

    def _iter_ocr_demo_source_run_dirs(self) -> list[Path]:
        roots = []
        preview_dir_raw = str(self.preview_dir_var.get() or "").strip()
        if preview_dir_raw:
            roots.append(Path(preview_dir_raw))

        campaign_chars_dir = getattr(self, "_campaign_chars_dir", None)
        if campaign_chars_dir:
            roots.append(Path(campaign_chars_dir))

        roots.append(Path(CONFIG.DIR_3_CHARS))

        seen = set()
        run_dirs = []

        def add_run_dir(candidate: Path):
            try:
                key = candidate.resolve()
            except Exception:
                key = candidate
            if key in seen:
                return
            meta_path = candidate / "metadata.json"
            images_dir = candidate / "images"
            if meta_path.exists() and images_dir.exists() and images_dir.is_dir():
                seen.add(key)
                run_dirs.append(candidate)

        for root in roots:
            if root is None or not root.exists() or not root.is_dir():
                continue
            add_run_dir(root)
            try:
                for meta_path in root.rglob("metadata.json"):
                    add_run_dir(meta_path.parent)
            except Exception:
                continue

        run_dirs.sort(key=lambda item: item.stat().st_mtime, reverse=True)
        return run_dirs

    def _seed_ocr_demo_samples(self, limit: int = 3) -> list[dict]:
        selected = []
        selected_keys = set()

        for run_dir in self._iter_ocr_demo_source_run_dirs():
            metadata = self._load_json_file_safely(run_dir / "metadata.json")
            if not isinstance(metadata, dict):
                continue

            perfect_samples = []
            fallback_samples = []
            images_dir = run_dir / "images"

            for pid, data in metadata.items():
                if not isinstance(data, dict):
                    continue
                img_path = self._find_preview_plate_image_path(images_dir, str(pid or "").strip())
                if img_path is None:
                    continue
                expected_texts = self._get_preview_expected_texts(data)
                if not expected_texts:
                    continue
                sample_key = tuple(expected_texts)
                if sample_key in selected_keys:
                    continue
                label = f"Demo {len(selected) + len(perfect_samples) + len(fallback_samples) + 1}"
                label = f"{label}  |  Oczek: {expected_texts[0]}"
                sample = {
                    "sample_id": str(pid or "").strip() or f"demo_{len(selected) + 1:03d}",
                    "image_path": str(img_path),
                    "expected_texts": expected_texts,
                    "label": label,
                    "source": "demo",
                }
                status = str(data.get("status", "") or "").strip().lower()
                if status == "perfect":
                    perfect_samples.append(sample)
                else:
                    fallback_samples.append(sample)

            for sample in perfect_samples + fallback_samples:
                sample_key = tuple(sample.get("expected_texts") or [])
                if sample_key in selected_keys:
                    continue
                selected_keys.add(sample_key)
                selected.append(sample)
                if len(selected) >= limit:
                    break

            if len(selected) >= limit:
                break

        if not selected:
            return []

        demo_dir = self._get_ocr_demo_dir()
        manifest_samples = []
        for index, sample in enumerate(selected[:limit], start=1):
            src_path = Path(sample["image_path"])
            ext = src_path.suffix if src_path.suffix else ".jpg"
            dst_name = f"sample_{index:03d}{ext.lower()}"
            dst_path = demo_dir / dst_name
            try:
                shutil.copy2(src_path, dst_path)
            except Exception:
                continue
            manifest_samples.append({
                "sample_id": str(sample.get("sample_id") or f"demo_{index:03d}"),
                "image": dst_name,
                "expected_texts": list(sample.get("expected_texts") or []),
                "label": str(sample.get("label") or f"Demo {index}"),
            })

        if not manifest_samples:
            return []

        self._atomic_write_json(
            demo_dir / "manifest.json",
            {"samples": manifest_samples},
        )
        return self._load_cached_ocr_demo_samples(limit=limit)

    def _get_ocr_demo_samples(self, limit: int = 3) -> list[dict]:
        cached = self._load_cached_ocr_demo_samples(limit=limit)
        if len(cached) >= limit:
            return cached[:limit]
        seeded = self._seed_ocr_demo_samples(limit=limit)
        return seeded[:limit] if seeded else cached[:limit]

    def _get_ocr_lab_sample_bundle(self) -> dict:
        live_samples = self._build_live_ocr_sample_pool()
        if live_samples:
            preview_dir = Path(str(self.preview_dir_var.get() or "").strip())
            meta_path = preview_dir / "metadata.json"
            try:
                preview_key = str(preview_dir.resolve())
            except Exception:
                preview_key = str(preview_dir)
            meta_mtime = meta_path.stat().st_mtime_ns if meta_path.exists() else 0
            return {
                "mode": "preview",
                "samples": live_samples,
                "allow_random": len(live_samples) > 3,
                "dataset_signature": f"preview:{preview_key}:{meta_mtime}:{len(live_samples)}",
                "description": "losowanie z wczytanej listy tablic",
            }

        demo_samples = self._get_ocr_demo_samples(limit=3)
        if demo_samples:
            manifest_path = self._get_ocr_demo_dir() / "manifest.json"
            manifest_mtime = manifest_path.stat().st_mtime_ns if manifest_path.exists() else 0
            return {
                "mode": "demo",
                "samples": demo_samples,
                "allow_random": False,
                "dataset_signature": f"demo:{manifest_mtime}:{len(demo_samples)}",
                "description": "3 próbki demo z danych aplikacji",
            }

        return {
            "mode": "empty",
            "samples": [],
            "allow_random": False,
            "dataset_signature": "",
            "description": "",
            "message": (
                "Brak wczytanej listy tablic i brak próbek demo OCR. "
                "Wykonaj przynajmniej jeden run wycinania PZ1 albo wczytaj katalog wyodrebnionych tablic."
            ),
        }

    def _get_ocr_ranking_sample_bundle(self) -> dict:
        bundle = self._get_ocr_lab_sample_bundle()
        if bundle.get("mode") == "empty":
            return bundle
        if bundle.get("mode") == "demo":
            return {
                "mode": "empty",
                "samples": [],
                "allow_random": False,
                "dataset_signature": "",
                "description": "",
                "message": (
                    "Ranking OCR wymaga wczytanego katalogu wyodrebnionych tablic. "
                    "Probki demo są dostępne tylko w Laboratorium OCR."
                ),
            }

        ranked_samples = [
            sample
            for sample in (bundle.get("samples") or [])
            if sample.get("expected_texts")
        ]
        if not ranked_samples:
            return {
                "mode": "empty",
                "samples": [],
                "allow_random": False,
                "dataset_signature": "",
                "description": "",
                "message": "Brak próbek z oczekiwanym tekstem do rankingu OCR.",
            }

        return {
            "mode": bundle.get("mode"),
            "samples": ranked_samples,
            "allow_random": bundle.get("allow_random", False),
            "dataset_signature": bundle.get("dataset_signature", ""),
            "description": bundle.get("description", ""),
            "cache_file": self.presets_dir / "global_ranking.json",
        }
        
    def _restore_preview_context_from_project(self, require_plates: bool = False):
        """
        Przywraca ostatnią paczkę preview projektu, jeśli istnieje.
        """
        preview_dir = ""
        try:
            saved_preview_dir = str(CAMPAIGN.get_step3_preview_dir() or "").strip()
        except Exception:
            saved_preview_dir = ""
        if saved_preview_dir:
            try:
                candidate = Path(saved_preview_dir)
                if (
                    candidate.exists()
                    and candidate.is_dir()
                    and (candidate / "metadata.json").exists()
                    and (candidate / "images").exists()
                    and (not require_plates or self._preview_dir_has_plate_entries(candidate))
                ):
                    preview_dir = str(candidate)
            except Exception:
                preview_dir = ""
        if not preview_dir:
            preview_dir = self._find_latest_preview_run_dir(require_plates=require_plates)
        if not preview_dir:
            return False

        try:
            self.preview_dir_var.set(preview_dir)
            self._reset_preview_cache()
            self._load_preview_data(quiet=True)
            return True
        except Exception as e:
            logger.debug(f"Nie udało się przywrócić preview paczki projektu: {e}")
            return False

    def _ensure_detection_preview_loaded(self, force_reload: bool = False) -> bool:
        if not hasattr(self, "plates_listbox"):
            return False

        preview_dir = str(self.preview_dir_var.get() or "").strip()
        if not self._preview_dir_has_plate_entries(preview_dir):
            preview_dir = self._find_latest_preview_run_dir(require_plates=True)
            if not preview_dir:
                return False

        meta_path = Path(preview_dir) / "metadata.json"
        current_meta_path = getattr(self, "_loaded_meta_path", None)
        preview_changed = preview_dir != str(self.preview_dir_var.get() or "").strip()
        needs_reload = (
            force_reload
            or preview_changed
            or not bool(self.preview_metadata)
            or current_meta_path != meta_path
        )

        if preview_changed:
            try:
                self.preview_dir_var.set(preview_dir)
            except Exception:
                return False

        if not needs_reload:
            if not getattr(self, "_listbox_pid_by_index", None) and self.preview_metadata:
                try:
                    self._apply_preview_metadata_update(self.preview_metadata, preserve_selection=True)
                except Exception:
                    return False
            return bool(self.preview_plate_ids or self.preview_metadata)

        try:
            self._reset_preview_cache()
            self._load_preview_data(quiet=True)
        except Exception as e:
            logger.debug(f"Nie udało się automatycznie wczytać paczki PZ2: {e}")
            return False

        return bool(self.preview_plate_ids)

    def _schedule_detection_preview_autoload(self):
        if not hasattr(self, "frame"):
            return

        after_id = getattr(self, "_detect_preview_autoload_after_id", None)
        if after_id is not None:
            try:
                self.frame.after_cancel(after_id)
            except Exception:
                pass
            finally:
                self._detect_preview_autoload_after_id = None

        def _run():
            self._detect_preview_autoload_after_id = None
            try:
                self._ensure_detection_preview_loaded()
            except Exception as e:
                logger.debug(f"Nie udało się zaplanować autoload PZ2: {e}")

        try:
            self._detect_preview_autoload_after_id = self.frame.after_idle(_run)
        except Exception:
            self._detect_preview_autoload_after_id = None

    def _metadata_has_detection_results(self, metadata_map) -> bool:
        for _, data in (metadata_map or {}).items():
            if not isinstance(data, dict):
                continue

            status = str(data.get("status", "unknown")).strip().lower()
            if status in ("perfect", "needs_fix"):
                return True

            if isinstance(data.get("characters"), list) and data.get("characters"):
                return True

            for key in ("yolo_detections", "yolo_nms_detections", "yolo_raw_detections"):
                if isinstance(data.get(key), list) and data.get(key):
                    return True

            if str(data.get("fusion_strategy", "") or "").strip():
                return True

        return False

    def _preview_dir_has_completed_detection_output(self, preview_dir=None) -> bool:
        preview_dir_raw = str(preview_dir if preview_dir is not None else (self.preview_dir_var.get() or "")).strip()
        if not preview_dir_raw:
            return False

        try:
            meta_path = Path(preview_dir_raw) / "metadata.json"
            if not meta_path.exists():
                return False

            with open(meta_path, "r", encoding="utf-8") as f:
                loaded = json.load(f)
            if not isinstance(loaded, dict):
                return False

            return self._metadata_has_detection_results(loaded)
        except Exception:
            return False

    def _sync_step3_access_from_preview_state(self, metadata_map=None):
        stage1_ready = False
        stage2_ready = False

        try:
            stage1_ready = self.can_restore_step3_substep(2)
        except Exception:
            stage1_ready = False

        if metadata_map is not None:
            stage2_ready = self._metadata_has_detection_results(metadata_map)
        if not stage2_ready:
            stage2_ready = self._preview_dir_has_completed_detection_output()

        if stage1_ready:
            try:
                self._set_button_state("btn_to_detect", True)
                self._set_subtab_state(self.tab_detect, "normal")
            except Exception:
                pass
            if self._step3_linear_mode:
                try:
                    CAMPAIGN.set_step3_stage1_done(True)
                except Exception:
                    pass

        if stage2_ready:
            try:
                self._set_button_state("btn_to_dataset", True)
                self._set_subtab_state(self.tab_dataset, "normal")
            except Exception:
                pass
            if self._step3_linear_mode:
                try:
                    CAMPAIGN.set_step3_stage2_done(True)
                except Exception:
                    pass

        try:
            self._sync_step3_nav_buttons()
        except Exception:
            pass

        try:
            self._update_step3_finish_button_state()
        except Exception:
            pass

    def _sort_character_records_by_x(self, chars):
        if not isinstance(chars, list):
            return []

        prepared = []
        for i, rec in enumerate(chars):
            _, x_key = self._char_record_to_symbol_and_x(rec, fallback_index=i)
            prepared.append((x_key, i, rec))

        prepared.sort(key=lambda item: (item[0], item[1]))
        return [rec for _, _, rec in prepared]

    def _normalize_character_source_tag(self, raw_tag=None, method=None) -> str:
        tag = str(raw_tag or "").strip().lower().replace("-", "_")
        method_name = str(method or "").strip().lower()

        if tag in ("manual", "manual_correction", "cvat_manual"):
            return "manual"
        if tag in ("yolo_box_ocr", "yolo_ocr", "yolo_box_plus_ocr"):
            return "yolo_box_ocr"
        if tag in ("yolo_rescue", "rescue", "yolorescue"):
            return "yolo_rescue"
        if tag == "yolo":
            return "yolo"
        if tag == "ocr":
            return "ocr"

        if method_name in {"manual", "cvat_manual"}:
            return "manual"
        if method_name in {"yolo_ocr"}:
            return "yolo_box_ocr"
        if method_name == "yolo":
            return "yolo"
        return "ocr"

    def _normalize_character_source_kind(self, rec, data=None, plate_source_bucket: str = "") -> str:
        raw_kind = ""
        raw_tag = ""
        method_name = ""
        if isinstance(rec, dict):
            raw_kind = str(rec.get("source_kind", "") or "").strip().lower().replace("-", "_")
            raw_tag = rec.get("source_tag")
            method_name = str(rec.get("method", "") or "").strip().lower()
        else:
            raw_kind = str(getattr(rec, "source_kind", "") or "").strip().lower().replace("-", "_")
            raw_tag = getattr(rec, "source_tag", None)
            method_name = str(getattr(rec, "method", "") or "").strip().lower()

        if raw_kind in {"cvat_manual", "local_manual", "yolo_box_ocr", "yolo_rescue", "yolo", "ocr"}:
            return raw_kind

        if method_name == "cvat_manual":
            return "cvat_manual"
        if method_name == "manual":
            if str(plate_source_bucket or "").strip().lower() == "cvat_manual":
                return "cvat_manual"
            return "local_manual"

        normalized_tag = self._normalize_character_source_tag(raw_tag=raw_tag, method=method_name)
        if normalized_tag == "manual":
            if str(plate_source_bucket or "").strip().lower() == "cvat_manual":
                return "cvat_manual"
            if isinstance(data, dict):
                source_info = data.get("source_info", {})
                if isinstance(source_info, dict) and str(source_info.get("bucket", "") or "").strip().lower() == "cvat_manual":
                    return "cvat_manual"
            return "local_manual"
        if normalized_tag in {"yolo_box_ocr", "yolo_rescue", "yolo", "ocr"}:
            return normalized_tag
        return "ocr"

    def _normalize_plate_source_bucket(self, raw_bucket=None, data=None, meta_path: Path | None = None) -> str:
        bucket = str(raw_bucket or "").strip().lower().replace("-", "_")
        if bucket in {"auto_preview", "auto", "preview", "pz2_detect"}:
            return "auto_preview"
        if bucket in {"local_manual", "manual", "preview_editor", "manual_correction"}:
            return "local_manual"
        if bucket in {"cvat_manual", "cvat", "cvat_import", "manual_pool"}:
            return "cvat_manual"

        if isinstance(data, dict):
            source_info = data.get("source_info", {})
            if isinstance(source_info, dict):
                nested_bucket = str(source_info.get("bucket", "") or "").strip()
                if nested_bucket:
                    normalized_nested = self._normalize_plate_source_bucket(nested_bucket, data=None, meta_path=meta_path)
                    if normalized_nested:
                        return normalized_nested

            chars = list(data.get("characters", []) or [])
            if any(str((rec or {}).get("method", "") or "").strip().lower() == "cvat_manual" for rec in chars if isinstance(rec, dict)):
                return "cvat_manual"
            if str(data.get("fusion_strategy", "") or "").strip().lower() == "manual_correction":
                return "local_manual"
            if any(self._normalize_character_source_kind(rec, data=data) in {"local_manual", "cvat_manual"} for rec in chars if isinstance(rec, dict)):
                if any(self._normalize_character_source_kind(rec, data=data) == "cvat_manual" for rec in chars if isinstance(rec, dict)):
                    return "cvat_manual"
                return "local_manual"

        if meta_path is not None:
            path_parts = {part.lower() for part in meta_path.parts}
            if "manual_char_pool" in path_parts:
                return "cvat_manual"

        return "auto_preview"

    def _normalize_plate_source_origin(self, raw_origin=None, bucket: str = "") -> str:
        origin = str(raw_origin or "").strip().lower().replace("-", "_")
        if origin in {"pz2_detect", "detect", "auto_detect"}:
            return "pz2_detect"
        if origin in {"preview_editor", "manual_correction", "local_manual"}:
            return "preview_editor"
        if origin in {"cvat_import", "cvat", "manual_pool"}:
            return "cvat_import"

        normalized_bucket = self._normalize_plate_source_bucket(bucket)
        if normalized_bucket == "cvat_manual":
            return "cvat_import"
        if normalized_bucket == "local_manual":
            return "preview_editor"
        return "pz2_detect"

    def _empty_gold_source_counts(self):
        return {key: 0 for key, _ in GOLD_SOURCE_BUCKETS}

    def _get_plate_source_bucket(self, data: dict, meta_path: Path | None = None) -> str:
        if not isinstance(data, dict):
            return "auto_preview"
        source_info = data.get("source_info", {})
        bucket = source_info.get("bucket") if isinstance(source_info, dict) else ""
        return self._normalize_plate_source_bucket(bucket, data=data, meta_path=meta_path)

    def _ensure_plate_source_metadata(
        self,
        data: dict,
        *,
        plate_id: str = "",
        meta_path: Path | None = None,
        default_bucket: str | None = None,
        default_origin: str | None = None,
        import_batch_id: str = "",
        review_manifest_id: str = "",
        modified_by: str = "",
    ) -> bool:
        if not isinstance(data, dict):
            return False

        changed = False
        source_info = data.get("source_info")
        if not isinstance(source_info, dict):
            source_info = {}
            data["source_info"] = source_info
            changed = True

        bucket = self._normalize_plate_source_bucket(
            default_bucket if default_bucket is not None else source_info.get("bucket", ""),
            data=data,
            meta_path=meta_path,
        )
        if str(source_info.get("bucket", "") or "") != bucket:
            source_info["bucket"] = bucket
            changed = True

        origin = self._normalize_plate_source_origin(
            default_origin if default_origin is not None else source_info.get("origin", ""),
            bucket=bucket,
        )
        if str(source_info.get("origin", "") or "") != origin:
            source_info["origin"] = origin
            changed = True

        run_id = str(source_info.get("run_id", "") or "").strip()
        if not run_id:
            candidate_run_id = ""
            if meta_path is not None:
                try:
                    candidate_run_id = str(meta_path.parent.name or "").strip()
                except Exception:
                    candidate_run_id = ""
            if not candidate_run_id:
                candidate_run_id = str(getattr(self, "preview_dir_var", None).get() if hasattr(self, "preview_dir_var") else "").strip()
                candidate_run_id = Path(candidate_run_id).name if candidate_run_id else ""
            if candidate_run_id:
                source_info["run_id"] = candidate_run_id
                changed = True

        if review_manifest_id and str(source_info.get("review_manifest_id", "") or "").strip() != str(review_manifest_id):
            source_info["review_manifest_id"] = str(review_manifest_id)
            changed = True
        elif "review_manifest_id" not in source_info:
            source_info["review_manifest_id"] = str(source_info.get("review_manifest_id", "") or "")
            changed = True

        if import_batch_id and str(source_info.get("import_batch_id", "") or "").strip() != str(import_batch_id):
            source_info["import_batch_id"] = str(import_batch_id)
            changed = True
        elif "import_batch_id" not in source_info:
            source_info["import_batch_id"] = str(source_info.get("import_batch_id", "") or "")
            changed = True

        if "last_modified_at" not in source_info:
            source_info["last_modified_at"] = str(source_info.get("last_modified_at", "") or "")
            changed = True
        if "last_modified_by" not in source_info:
            source_info["last_modified_by"] = str(source_info.get("last_modified_by", "") or "")
            changed = True

        if modified_by:
            from datetime import datetime
            now = datetime.now().isoformat(timespec="seconds")
            if str(source_info.get("last_modified_by", "") or "") != str(modified_by):
                source_info["last_modified_by"] = str(modified_by)
                changed = True
            if str(source_info.get("last_modified_at", "") or "") != now:
                source_info["last_modified_at"] = now
                changed = True

        gold_state = data.get("gold_state")
        if not isinstance(gold_state, dict):
            gold_state = {}
            data["gold_state"] = gold_state
            changed = True

        status = str(data.get("status", "unknown") or "unknown").strip().lower()
        candidate = bool(status == "perfect")
        if bool(gold_state.get("candidate", False)) != candidate:
            gold_state["candidate"] = candidate
            changed = True

        approved = bool(gold_state.get("approved", False))
        if meta_path is not None:
            path_parts = {part.lower() for part in meta_path.parts}
            if "gold_char_pool" in path_parts:
                approved = True
        if bool(gold_state.get("approved", False)) != approved:
            gold_state["approved"] = approved
            changed = True

        approved_from_bucket = str(gold_state.get("approved_from_bucket", "") or "").strip()
        if approved and not approved_from_bucket:
            gold_state["approved_from_bucket"] = bucket
            changed = True
        elif not approved and "approved_from_bucket" not in gold_state:
            gold_state["approved_from_bucket"] = approved_from_bucket
            changed = True

        excluded = bool(gold_state.get("excluded", False))
        if bool(gold_state.get("excluded", False)) != excluded:
            gold_state["excluded"] = excluded
            changed = True
        if "excluded_reason" not in gold_state:
            gold_state["excluded_reason"] = str(gold_state.get("excluded_reason", "") or "")
            changed = True

        for list_key in ("characters", "yolo_detections", "yolo_nms_detections", "yolo_raw_detections"):
            records = data.get(list_key)
            if not isinstance(records, list):
                continue
            for rec in records:
                if not isinstance(rec, dict):
                    continue
                source_kind = self._normalize_character_source_kind(rec, data=data, plate_source_bucket=bucket)
                if str(rec.get("source_kind", "") or "") != source_kind:
                    rec["source_kind"] = source_kind
                    changed = True
                if "source_batch_id" not in rec:
                    rec["source_batch_id"] = ""
                    changed = True
                if import_batch_id and source_kind == "cvat_manual" and str(rec.get("source_batch_id", "") or "") != str(import_batch_id):
                    rec["source_batch_id"] = str(import_batch_id)
                    changed = True

        return changed

    def _build_character_source_tags(self, chars, fusion_strategy="", fusion_details=None):
        ordered = self._sort_character_records_by_x(list(chars or []))
        rescue_positions = set()
        if str(fusion_strategy or "").strip().lower() == "ocr_yolo_rescue" and isinstance(fusion_details, dict):
            try:
                rescue_positions = {
                    int(idx) for idx in (fusion_details.get("mismatch_positions", []) or [])
                    if str(idx).strip() != ""
                }
            except Exception:
                rescue_positions = set()

        tags = []
        for idx, rec in enumerate(ordered):
            method_name = ""
            raw_tag = None
            if isinstance(rec, dict):
                raw_tag = rec.get("source_tag")
                method_name = rec.get("method", "")
            else:
                raw_tag = getattr(rec, "source_tag", None)
                method_name = getattr(rec, "method", "")

            normalized = self._normalize_character_source_tag(raw_tag=raw_tag, method=method_name)
            if idx in rescue_positions:
                normalized = "yolo_rescue"
            tags.append(normalized)

        return tags

    def _serialize_character_records(self, chars, fusion_strategy="", fusion_details=None):
        ordered = self._sort_character_records_by_x(list(chars or []))
        source_tags = self._build_character_source_tags(ordered, fusion_strategy=fusion_strategy, fusion_details=fusion_details)
        clean = []

        for idx, c in enumerate(ordered):
            source_tag = source_tags[idx] if idx < len(source_tags) else self._normalize_character_source_tag(
                method=(c.get("method", "") if isinstance(c, dict) else getattr(c, "method", ""))
            )
            source_kind = self._normalize_character_source_kind(c)
            clean.append({
                "character": str(c["character"] if isinstance(c, dict) else c.character),
                "bbox": [float(x) for x in (c["bbox"] if isinstance(c, dict) else c.bbox)],
                "confidence": float(c["confidence"] if isinstance(c, dict) else c.confidence),
                "method": str(c["method"] if isinstance(c, dict) else c.method),
                "source_tag": str(source_tag),
                "source_kind": str(source_kind),
                "source_batch_id": str((c.get("source_batch_id", "") if isinstance(c, dict) else getattr(c, "source_batch_id", "")) or ""),
            })

        return clean

    def _get_character_source_tag(self, rec, data=None, fallback_index: int = 0) -> str:
        raw_tag = None
        method_name = ""

        if isinstance(rec, dict):
            raw_tag = rec.get("source_tag")
            method_name = rec.get("method", "")
        else:
            raw_tag = getattr(rec, "source_tag", None)
            method_name = getattr(rec, "method", "")

        normalized = self._normalize_character_source_tag(raw_tag=raw_tag, method=method_name)
        if raw_tag:
            return normalized

        if isinstance(data, dict):
            strategy = str(data.get("fusion_strategy", "") or "").strip().lower()
            if strategy == "ocr_yolo_rescue":
                details = data.get("fusion_details", {})
                if isinstance(details, dict):
                    mismatch_positions = details.get("mismatch_positions", []) or []
                    try:
                        if int(fallback_index) in {int(idx) for idx in mismatch_positions}:
                            return "yolo_rescue"
                    except Exception:
                        pass
            elif strategy in {"yolo_box_ocr", "yolo_box_ocr_no_gt", "yolo_box_ocr_fallback"}:
                return "yolo_box_ocr"

        return normalized

    def _get_character_source_kind(self, rec, data=None) -> str:
        plate_bucket = self._get_plate_source_bucket(data) if isinstance(data, dict) else ""
        return self._normalize_character_source_kind(rec, data=data, plate_source_bucket=plate_bucket)

    def _count_character_sources(self, chars, data=None):
        counts = {"ocr": 0, "yolo": 0, "yolo_box_ocr": 0, "yolo_rescue": 0, "manual": 0}
        for idx, rec in enumerate(list(chars or [])):
            tag = self._get_character_source_tag(rec, data=data, fallback_index=idx)
            if tag not in counts:
                continue
            counts[tag] += 1
        return counts

    def _get_preview_clearable_source_counts(self, data: dict | None = None) -> dict:
        source_data = data if isinstance(data, dict) else self._get_preview_active_data(create=False)
        final_chars = list(source_data.get("characters", []) or []) if isinstance(source_data, dict) else []
        yolo_filtered = list(source_data.get("yolo_detections", []) or []) if isinstance(source_data, dict) else []

        final_yolo = 0
        final_ocr = 0
        final_manual = 0
        for idx, rec in enumerate(final_chars):
            if self._is_manual_character_record(rec, data=source_data):
                final_manual += 1
                continue
            tag = self._get_character_source_tag(rec, data=source_data, fallback_index=idx)
            if tag in {"yolo", "yolo_box_ocr", "yolo_rescue"}:
                final_yolo += 1
            elif tag == "ocr":
                final_ocr += 1

        yolo_count = max(int(final_yolo), len(yolo_filtered))
        auto_count = int(final_ocr) + int(yolo_count)
        total_count = int(len(final_chars))
        return {
            "yolo": int(yolo_count),
            "ocr": int(final_ocr),
            "auto": int(auto_count),
            "manual": int(final_manual),
            "all": int(total_count),
        }

    def _get_preview_selected_plate_ids(self) -> list[str]:
        pid_map = list(getattr(self, "_listbox_pid_by_index", []) or [])
        listbox = getattr(self, "plates_listbox", None)
        if listbox is None or not pid_map:
            return []

        selected = []
        try:
            for raw_idx in listbox.curselection():
                idx = int(raw_idx)
                if 0 <= idx < len(pid_map):
                    pid = str(pid_map[idx] or "").strip()
                    if pid and pid not in selected:
                        selected.append(pid)
        except Exception:
            return []
        return selected

    def _get_preview_scope_plate_ids(self, scope: str) -> list[str]:
        normalized = str(scope or "").strip().lower()
        if normalized == "run":
            return [
                str(pid or "").strip()
                for pid in list(getattr(self, "_listbox_pid_by_index", []) or [])
                if str(pid or "").strip()
            ]
        if normalized == "selected":
            return self._get_preview_selected_plate_ids()

        active_pid = str(getattr(self, "_preview_active_pid", "") or "").strip()
        return [active_pid] if active_pid else []

    def _get_preview_clearable_source_counts_for_scope(self, scope: str) -> dict:
        totals = {"yolo": 0, "ocr": 0, "auto": 0, "manual": 0, "all": 0}
        for pid in self._get_preview_scope_plate_ids(scope):
            data = self.preview_metadata.get(pid, {}) if isinstance(getattr(self, "preview_metadata", {}), dict) else {}
            counts = self._get_preview_clearable_source_counts(data if isinstance(data, dict) else None)
            for key in totals:
                totals[key] += int(counts.get(key, 0) or 0)
        return totals

    def _should_clear_character_record_for_preset(self, rec, preset: str, *, data=None, fallback_index: int = 0) -> bool:
        normalized = str(preset or "").strip().lower()
        if normalized == "all":
            return True

        if self._is_manual_character_record(rec, data=data):
            return False

        tag = self._get_character_source_tag(rec, data=data, fallback_index=fallback_index)
        if normalized == "yolo":
            return tag in {"yolo", "yolo_box_ocr", "yolo_rescue"}
        if normalized == "ocr":
            return tag == "ocr"
        if normalized == "auto":
            return tag in {"yolo", "yolo_box_ocr", "yolo_rescue", "ocr"}
        return False

    def _refresh_preview_clear_sources_menu(self):
        btn = getattr(self, "preview_clear_sources_btn", None)
        menu = getattr(self, "preview_clear_sources_menu", None)
        if btn is None or menu is None:
            return

        data = self._get_preview_active_data(create=False)
        has_plate = isinstance(data, dict)
        selected_pids = self._get_preview_selected_plate_ids()
        selected_count = len(selected_pids)
        scope_counts = {
            "active": self._get_preview_clearable_source_counts_for_scope("active"),
            "selected": self._get_preview_clearable_source_counts_for_scope("selected"),
            "run": self._get_preview_clearable_source_counts_for_scope("run"),
        }

        try:
            btn.configure(
                state=(tk.NORMAL if has_plate else tk.DISABLED),
                text="Wyczyść wg źródła",
            )
        except Exception:
            pass

        scope_labels = {
            "active": "Aktywna tablica",
            "selected": f"Zaznaczone na liście ({selected_count})",
            "run": "Cały preview run",
        }
        preset_labels = {
            "yolo": "Usuń tylko YOLO",
            "ocr": "Usuń tylko OCR",
            "auto": "Usuń całe AUTO",
            "all": "Usuń wszystko",
        }

        for preset in ("yolo", "ocr", "auto", "all"):
            submenu = getattr(self, f"_preview_clear_scope_menu_{preset}", None)
            if submenu is None:
                continue
            for idx, scope in enumerate(("active", "selected", "run")):
                count = int(scope_counts.get(scope, {}).get(preset, 0) or 0)
                try:
                    submenu.entryconfigure(
                        idx,
                        label=f"{scope_labels[scope]} ({count})",
                        state=(
                            tk.NORMAL
                            if has_plate and count > 0 and (scope != "selected" or selected_count > 0)
                            else tk.DISABLED
                        ),
                    )
                except Exception:
                    pass
            try:
                menu.entryconfigure(
                    preset_labels[preset],
                    state=(tk.NORMAL if has_plate else tk.DISABLED),
                )
            except Exception:
                pass

    def _clear_preview_characters_for_pid_by_source_preset(self, plate_id: str, preset: str) -> dict:
        pid = str(plate_id or "").strip()
        normalized = str(preset or "").strip().lower()
        if normalized not in {"yolo", "ocr", "auto", "all"}:
            return {"removed_final": 0, "removed_yolo_layers": 0}

        data = self.preview_metadata.get(pid)
        if not isinstance(data, dict):
            return {"removed_final": 0, "removed_yolo_layers": 0}

        counts = self._get_preview_clearable_source_counts(data)
        target_count = int(counts.get(normalized, 0) or 0)
        if target_count <= 0:
            return {"removed_final": 0, "removed_yolo_layers": 0}

        self._push_preview_history_snapshot(pid)

        current_chars = list(data.get("characters", []) or [])
        filtered_chars = []
        removed_final = 0
        for idx, rec in enumerate(current_chars):
            if self._should_clear_character_record_for_preset(rec, normalized, data=data, fallback_index=idx):
                removed_final += 1
                continue
            filtered_chars.append(rec)

        data["characters"] = self._sort_character_records_by_x(filtered_chars)

        removed_yolo_layers = 0
        if normalized in {"yolo", "auto", "all"}:
            for key in ("yolo_detections", "yolo_nms_detections", "yolo_raw_detections"):
                records = list(data.get(key, []) or [])
                removed_yolo_layers += len(records)
                data[key] = []

        data["status"] = self._derive_preview_status_from_data(data, data.get("characters", []))
        data["fusion_strategy"] = "manual_correction"
        data["fusion_details"] = {
            "source": "preview_editor",
            "clear_preset": normalized,
            "removed_final_count": int(removed_final),
            "removed_yolo_layer_count": int(removed_yolo_layers),
        }
        self._ensure_plate_source_metadata(
            data,
            plate_id=str(pid or data.get("plate_id", "") or ""),
            default_bucket="local_manual",
            default_origin="preview_editor",
            modified_by="human",
        )

        return {
            "removed_final": int(removed_final),
            "removed_yolo_layers": int(removed_yolo_layers),
        }

    def _clear_active_preview_characters_by_source_preset(self, preset: str, scope: str = "active"):
        normalized = str(preset or "").strip().lower()
        if normalized not in {"yolo", "ocr", "auto", "all"}:
            return

        target_pids = self._get_preview_scope_plate_ids(scope)
        if not target_pids:
            self._update_preview_edit_status("Najpierw wybierz tablicę albo zaznaczone pozycje do czyszczenia boxów.", tone="warning")
            return

        scope_label = {
            "active": "aktywnej tablicy",
            "selected": "zaznaczonych tablic",
            "run": "całego preview runu",
        }.get(str(scope or "").strip().lower(), "wybranego zakresu")

        if normalized == "all":
            confirmed = messagebox.askyesno(
                "Usuń wszystkie boxy?",
                f"Ta operacja usunie wszystkie boxy znaków z {scope_label}, również ręczne.\n\nCzy chcesz kontynuować?",
                parent=self.frame,
            )
            if not confirmed:
                return

        total_removed_final = 0
        total_removed_yolo_layers = 0
        touched = 0
        for pid in target_pids:
            outcome = self._clear_preview_characters_for_pid_by_source_preset(pid, normalized)
            removed_final = int(outcome.get("removed_final", 0) or 0)
            removed_yolo_layers = int(outcome.get("removed_yolo_layers", 0) or 0)
            if removed_final > 0 or removed_yolo_layers > 0:
                touched += 1
            total_removed_final += removed_final
            total_removed_yolo_layers += removed_yolo_layers

        if touched <= 0:
            self._update_preview_edit_status("Dla wybranego źródła i zakresu nie było boxów do usunięcia.", tone="warning")
            return

        active_pid = str(getattr(self, "_preview_active_pid", "") or "").strip()
        self._preview_char_selected_index = None
        self._preview_char_hover_index = None
        self._preview_char_hover_label_index = None
        self._preview_char_label_active_index = None
        if active_pid and active_pid in self.preview_metadata:
            active_data = self.preview_metadata.get(active_pid)
            if isinstance(active_data, dict):
                self._refresh_preview_live_metadata_ui(
                    status_message=None,
                    status_tone="muted",
                    render_preview=True,
                )

        self._persist_preview_metadata(success_message=None, refresh_list=True)

        preset_label = {
            "yolo": "YOLO",
            "ocr": "OCR",
            "auto": "AUTO",
            "all": "WSZYSTKO",
        }[normalized]
        message = (
            f"Wyczyszczono źródło {preset_label} dla {touched} tablic: "
            f"final={int(total_removed_final)}, warstwy YOLO={int(total_removed_yolo_layers)}."
        )
        self._update_preview_edit_status(message, tone="success")
        self._set_preview_box_info(message, "success")

    def _is_manual_character_record(self, rec, data=None) -> bool:
        try:
            source_kind = str(self._get_character_source_kind(rec, data=data) or "").strip().lower()
        except Exception:
            source_kind = ""
        if source_kind in {"local_manual", "cvat_manual"}:
            return True

        try:
            source_tag = str(self._get_character_source_tag(rec, data=data) or "").strip().lower()
        except Exception:
            source_tag = ""
        if source_tag == "manual":
            return True

        try:
            method_name = str(rec.get("method", "") if isinstance(rec, dict) else getattr(rec, "method", "")).strip().lower()
        except Exception:
            method_name = ""
        return method_name in {"manual", "cvat_manual"}

    def _character_record_overlap_score(self, left, right) -> float:
        left_bbox = self._char_record_bbox(left)
        right_bbox = self._char_record_bbox(right)
        if not left_bbox or not right_bbox:
            return 0.0

        lx1, ly1, lx2, ly2 = left_bbox
        rx1, ry1, rx2, ry2 = right_bbox
        inter_x1 = max(float(lx1), float(rx1))
        inter_y1 = max(float(ly1), float(ry1))
        inter_x2 = min(float(lx2), float(rx2))
        inter_y2 = min(float(ly2), float(ry2))
        inter_w = max(0.0, inter_x2 - inter_x1)
        inter_h = max(0.0, inter_y2 - inter_y1)
        inter_area = inter_w * inter_h
        if inter_area <= 0.0:
            return 0.0

        left_area = max(1.0, (float(lx2) - float(lx1)) * (float(ly2) - float(ly1)))
        right_area = max(1.0, (float(rx2) - float(rx1)) * (float(ry2) - float(ry1)))
        union_area = max(1.0, left_area + right_area - inter_area)
        return float(inter_area / union_area)

    def _character_record_collides_with_manual(self, rec, manual_records) -> bool:
        bbox = self._char_record_bbox(rec)
        if not bbox:
            return False

        cx = (float(bbox[0]) + float(bbox[2])) / 2.0
        cy = (float(bbox[1]) + float(bbox[3])) / 2.0
        width = max(1.0, float(bbox[2]) - float(bbox[0]))
        height = max(1.0, float(bbox[3]) - float(bbox[1]))

        for manual_rec in list(manual_records or []):
            manual_bbox = self._char_record_bbox(manual_rec)
            if not manual_bbox:
                continue

            iou = self._character_record_overlap_score(rec, manual_rec)
            if iou >= 0.15:
                return True

            mx = (float(manual_bbox[0]) + float(manual_bbox[2])) / 2.0
            my = (float(manual_bbox[1]) + float(manual_bbox[3])) / 2.0
            mw = max(1.0, float(manual_bbox[2]) - float(manual_bbox[0]))
            mh = max(1.0, float(manual_bbox[3]) - float(manual_bbox[1]))

            center_dx = abs(cx - mx)
            center_dy = abs(cy - my)
            if center_dx <= max(width, mw) * 0.45 and center_dy <= max(height, mh) * 0.45:
                return True

        return False

    def _clone_base_record_with_candidate_bbox(self, base_rec, candidate_rec):
        candidate_bbox = self._char_record_bbox(candidate_rec)
        if not candidate_bbox:
            return copy.deepcopy(base_rec) if isinstance(base_rec, dict) else self._clone_character_detection(base_rec)

        candidate_confidence = self._char_record_confidence(candidate_rec)
        if isinstance(base_rec, dict):
            updated = copy.deepcopy(base_rec)
            updated["bbox"] = [float(v) for v in candidate_bbox[:4]]
            try:
                existing_confidence = float(updated.get("confidence", 0.0) or 0.0)
            except Exception:
                existing_confidence = 0.0
            updated["confidence"] = float(max(existing_confidence, candidate_confidence))
            return updated

        symbol, _ = self._char_record_to_symbol_and_x(base_rec)
        return CharacterDetection(
            character=str(symbol or ""),
            bbox=tuple(float(v) for v in candidate_bbox[:4]),
            confidence=float(max(self._char_record_confidence(base_rec), candidate_confidence)),
            method=str(getattr(base_rec, "method", "ocr") or "ocr"),
        )

    def _is_existing_plate_perfect(self, existing_chars, data=None) -> bool:
        ordered_existing = self._sort_character_records_by_x(list(existing_chars or []))
        if not ordered_existing:
            return False
        return str(self._derive_preview_status_from_data(data, ordered_existing) or "").strip().lower() == "perfect"

    def _preserve_existing_perfect_plate_during_detection(self, existing_chars, yolo_detections, data=None):
        ordered_existing = self._sort_character_records_by_x(list(existing_chars or []))
        if not ordered_existing:
            return [], None

        rebuilt, backend_details = self._apply_yolo_box_backend(
            ordered_existing,
            yolo_detections,
            preserve_base_record_metadata=True,
        )
        final_chars = rebuilt or ordered_existing

        fusion_strategy = str((data or {}).get("fusion_strategy", "") or "").strip() if isinstance(data, dict) else ""
        fusion_details = (data or {}).get("fusion_details", {}) if isinstance(data, dict) else {}
        serialized = self._serialize_character_records(
            final_chars,
            fusion_strategy=fusion_strategy,
            fusion_details=fusion_details if isinstance(fusion_details, dict) else None,
        )
        return serialized, backend_details

    def _merge_detected_characters_preserving_manual(self, existing_chars, detected_chars, data=None) -> tuple[list[dict], dict]:
        existing_ordered = self._sort_character_records_by_x(list(existing_chars or []))
        detected_ordered = self._sort_character_records_by_x(list(detected_chars or []))

        manual_records = [
            copy.deepcopy(rec)
            for rec in existing_ordered
            if isinstance(rec, dict) and self._is_manual_character_record(rec, data=data)
        ]
        if not manual_records:
            return detected_ordered, {
                "manual_preserved_count": 0,
                "auto_appended_count": int(len(detected_ordered)),
                "auto_skipped_due_manual": 0,
            }

        merged_records = list(manual_records)
        skipped_auto = 0
        appended_auto = 0

        for rec in detected_ordered:
            if not isinstance(rec, dict):
                continue
            if self._character_record_collides_with_manual(rec, manual_records):
                skipped_auto += 1
                continue
            merged_records.append(rec)
            appended_auto += 1

        return self._sort_character_records_by_x(merged_records), {
            "manual_preserved_count": int(len(manual_records)),
            "auto_appended_count": int(appended_auto),
            "auto_skipped_due_manual": int(skipped_auto),
        }

    def _get_perfect_strategy_bucket(self, data: dict) -> str:
        if not isinstance(data, dict):
            return "other_perfect"

        raw_strategy = str(data.get("fusion_strategy", "") or "").strip().lower()
        if raw_strategy in ("ocr_exact", "ocr_only"):
            return "ocr_exact"
        if raw_strategy in ("yolo_exact", "yolo_only"):
            return "yolo_exact"
        if raw_strategy == "ocr_yolo_rescue":
            return "ocr_yolo_rescue"
        if raw_strategy in ("yolo_box_ocr", "yolo_box_ocr_exact"):
            return "yolo_box_ocr"

        return "other_perfect"

    def _empty_perfect_strategy_counts(self):
        return {key: 0 for key, _ in PERFECT_STRATEGY_BUCKETS}

    def _format_perfect_strategy_counts(self, counts: dict) -> str:
        safe_counts = counts if isinstance(counts, dict) else {}
        parts = [
            f"{label}: {int(safe_counts.get(key, 0))}"
            for key, label in PERFECT_STRATEGY_BUCKETS
        ]
        return "Tablice perfect wg strategii: " + " | ".join(parts)

    def _get_selected_gold_export_strategy_buckets(self):
        selected = set()
        if bool(getattr(self, "gold_include_ocr_exact_var", None).get() if hasattr(self, "gold_include_ocr_exact_var") else True):
            selected.add("ocr_exact")
        if bool(getattr(self, "gold_include_yolo_exact_var", None).get() if hasattr(self, "gold_include_yolo_exact_var") else True):
            selected.add("yolo_exact")
        if bool(getattr(self, "gold_include_ocr_yolo_rescue_var", None).get() if hasattr(self, "gold_include_ocr_yolo_rescue_var") else True):
            selected.add("ocr_yolo_rescue")
        if bool(getattr(self, "gold_include_yolo_box_ocr_var", None).get() if hasattr(self, "gold_include_yolo_box_ocr_var") else True):
            selected.add("yolo_box_ocr")
        if bool(getattr(self, "gold_include_other_perfect_var", None).get() if hasattr(self, "gold_include_other_perfect_var") else True):
            selected.add("other_perfect")
        return selected

    def _format_selected_gold_export_strategy_labels(self) -> str:
        selected = self._get_selected_gold_export_strategy_buckets()
        labels = [label for key, label in PERFECT_STRATEGY_BUCKETS if key in selected]
        return ", ".join(labels) if labels else "brak"

    def _get_selected_gold_export_source_buckets(self):
        selected = set()
        if bool(getattr(self, "gold_include_source_auto_var", None).get() if hasattr(self, "gold_include_source_auto_var") else True):
            selected.add("auto_preview")
        if bool(getattr(self, "gold_include_source_local_manual_var", None).get() if hasattr(self, "gold_include_source_local_manual_var") else True):
            selected.add("local_manual")
        if bool(getattr(self, "gold_include_source_cvat_manual_var", None).get() if hasattr(self, "gold_include_source_cvat_manual_var") else True):
            selected.add("cvat_manual")
        return selected

    def _format_selected_gold_export_source_labels(self) -> str:
        selected = self._get_selected_gold_export_source_buckets()
        labels = [label for key, label in GOLD_SOURCE_BUCKETS if key in selected]
        return ", ".join(labels) if labels else "brak"

    def _count_exportable_characters_in_data(self, data: dict) -> int:
        if not isinstance(data, dict):
            return 0

        valid_chars = set(CHAR_CLASS_ALPHABET)
        count = 0
        for rec in list(data.get("characters", []) or []):
            if isinstance(rec, dict):
                symbol = rec.get("character", "")
            else:
                symbol = getattr(rec, "character", "")
            symbol = str(symbol or "").strip().upper()
            if symbol and symbol in valid_chars:
                count += 1
        return count

    def _matches_selected_gold_export_sources(self, data: dict, selected_sources=None) -> bool:
        selected = set(selected_sources or [])
        if not selected:
            return False
        bucket = self._get_plate_source_bucket(data)
        return bucket in selected

    def _build_contextual_gold_export_counts(self, *, selected_strategies=None, selected_sources=None):
        strategy_filter = set(selected_strategies or [])
        source_filter = set(selected_sources or [])
        use_strategy_filter = bool(strategy_filter)
        use_source_filter = bool(source_filter)

        strategy_counts = self._empty_perfect_strategy_counts()
        strategy_char_counts = self._empty_perfect_strategy_counts()
        source_counts = self._empty_gold_source_counts()
        source_char_counts = self._empty_gold_source_counts()

        for _pid, data in (self.preview_metadata or {}).items():
            if not isinstance(data, dict):
                continue
            if str(data.get("status", "unknown") or "unknown").strip().lower() != "perfect":
                continue

            strategy_bucket = self._get_perfect_strategy_bucket(data)
            source_bucket = self._get_plate_source_bucket(data)
            char_count = self._count_exportable_characters_in_data(data)

            if (not use_source_filter) or source_bucket in source_filter:
                if strategy_bucket in strategy_counts:
                    strategy_counts[strategy_bucket] += 1
                    strategy_char_counts[strategy_bucket] += char_count

            if (not use_strategy_filter) or strategy_bucket in strategy_filter:
                if source_bucket in source_counts:
                    source_counts[source_bucket] += 1
                    source_char_counts[source_bucket] += char_count

        return {
            "strategy_counts": strategy_counts,
            "strategy_char_counts": strategy_char_counts,
            "source_counts": source_counts,
            "source_char_counts": source_char_counts,
        }

    def _count_statuses_in_metadata_mapping(self, metadata_map):
        perfect = 0
        needs_fix = 0
        unknown = 0
        char_boxes = 0
        strategy_counts = self._empty_perfect_strategy_counts()
        strategy_char_counts = self._empty_perfect_strategy_counts()
        source_counts = self._empty_gold_source_counts()
        source_char_counts = self._empty_gold_source_counts()

        for _, data in (metadata_map or {}).items():
            if not isinstance(data, dict):
                unknown += 1
                continue

            try:
                char_boxes += len(list(data.get("characters", []) or []))
            except Exception:
                pass

            status = str(data.get("status", "unknown")).strip().lower()
            if status == "perfect":
                perfect += 1
                bucket = self._get_perfect_strategy_bucket(data)
                source_bucket = self._get_plate_source_bucket(data)
                strategy_counts[bucket] += 1
                strategy_char_counts[bucket] += self._count_exportable_characters_in_data(data)
                if source_bucket in source_counts:
                    source_counts[source_bucket] += 1
                    source_char_counts[source_bucket] += self._count_exportable_characters_in_data(data)
            elif status == "needs_fix":
                needs_fix += 1
            else:
                unknown += 1

        return {
            "perfect": perfect,
            "needs_fix": needs_fix,
            "unknown": unknown,
            "total": perfect + needs_fix + unknown,
            "char_boxes": int(char_boxes),
            "strategy_counts": strategy_counts,
            "strategy_char_counts": strategy_char_counts,
            "source_counts": source_counts,
            "source_char_counts": source_char_counts,
        }

    def _build_merged_gold_export_counts(self, *, selected_strategies=None, selected_sources=None):
        strategy_filter = set(selected_strategies or [])
        source_filter = set(selected_sources or [])
        use_strategy_filter = bool(strategy_filter)
        use_source_filter = bool(source_filter)

        strategy_counts = self._empty_perfect_strategy_counts()
        strategy_char_counts = self._empty_perfect_strategy_counts()
        source_counts = self._empty_gold_source_counts()
        source_char_counts = self._empty_gold_source_counts()
        selected_plate_count = 0
        selected_char_count = 0

        meta_candidates = self._get_gold_export_meta_candidates()

        seen = set()
        for meta in meta_candidates:
            try:
                with open(meta, "r", encoding="utf-8") as f:
                    metadata = json.load(f)
            except Exception:
                continue
            if not isinstance(metadata, dict):
                continue

            for pid, data in metadata.items():
                if not isinstance(data, dict):
                    continue
                if str(data.get("status", "unknown") or "unknown").strip().lower() != "perfect":
                    continue

                try:
                    self._ensure_plate_source_metadata(data, plate_id=str(pid or ""), meta_path=meta)
                except Exception:
                    pass

                unique_key = self._build_gold_export_plate_unique_key(data)
                if unique_key in seen:
                    continue
                seen.add(unique_key)

                strategy_bucket = self._get_perfect_strategy_bucket(data)
                source_bucket = self._get_plate_source_bucket(data, meta_path=meta)
                char_count = self._count_exportable_characters_in_data(data)
                strategy_match = (not use_strategy_filter) or (strategy_bucket in strategy_filter)
                source_match = (not use_source_filter) or (source_bucket in source_filter)

                if source_match and strategy_bucket in strategy_counts:
                    strategy_counts[strategy_bucket] += 1
                    strategy_char_counts[strategy_bucket] += char_count

                if strategy_match and source_bucket in source_counts:
                    source_counts[source_bucket] += 1
                    source_char_counts[source_bucket] += char_count

                if strategy_match and source_match:
                    selected_plate_count += 1
                    selected_char_count += char_count

        return {
            "strategy_counts": strategy_counts,
            "strategy_char_counts": strategy_char_counts,
            "source_counts": source_counts,
            "source_char_counts": source_char_counts,
            "selected_plate_count": int(selected_plate_count),
            "selected_char_count": int(selected_char_count),
        }

    def _build_campaign_aware_gold_export_counts(self, *, selected_strategies=None, selected_sources=None):
        try:
            in_campaign = bool(getattr(self, "_step3_linear_mode", False) and CAMPAIGN.get_active_project_name())
        except Exception:
            in_campaign = False

        if in_campaign:
            contextual = self._build_contextual_gold_export_counts(
                selected_strategies=selected_strategies,
                selected_sources=selected_sources,
            )
            strategy_counts = dict(contextual.get("strategy_counts", {}) or {})
            strategy_char_counts = dict(contextual.get("strategy_char_counts", {}) or {})
            source_counts = dict(contextual.get("source_counts", {}) or {})
            source_char_counts = dict(contextual.get("source_char_counts", {}) or {})
            selected_plate_count = int(sum(int(v or 0) for v in strategy_counts.values()))
            selected_char_count = int(sum(int(v or 0) for v in strategy_char_counts.values()))
            return {
                "strategy_counts": strategy_counts,
                "strategy_char_counts": strategy_char_counts,
                "source_counts": source_counts,
                "source_char_counts": source_char_counts,
                "selected_plate_count": int(selected_plate_count),
                "selected_char_count": int(selected_char_count),
            }

        return self._build_merged_gold_export_counts(
            selected_strategies=selected_strategies,
            selected_sources=selected_sources,
        )

    def _get_gold_export_meta_candidates(self) -> list[Path]:
        in_campaign = bool(getattr(self, "_step3_linear_mode", False) and CAMPAIGN.get_active_project_name())

        if not in_campaign:
            preview_dir_raw = str(self.preview_dir_var.get() or "").strip()
            if not preview_dir_raw:
                return []
            try:
                preview_dir = Path(preview_dir_raw)
            except Exception:
                return []
            meta_path = preview_dir / "metadata.json"
            images_dir = preview_dir / "images"
            if meta_path.exists() and images_dir.exists():
                return [meta_path]
            return []

        base_chars_dir = self._get_step3_chars_root_dir()
        meta_candidates: list[Path] = []
        try:
            for meta in base_chars_dir.rglob("metadata.json"):
                run_dir = meta.parent
                if (run_dir / "images").exists():
                    meta_candidates.append(meta)
        except Exception:
            meta_candidates = []

        try:
            meta_candidates.sort(key=lambda p: p.stat().st_mtime, reverse=True)
        except Exception:
            pass
        return meta_candidates

    def _char_record_bbox(self, rec):
        bbox = None

        if isinstance(rec, dict):
            bbox = rec.get("bbox")
        else:
            try:
                bbox = getattr(rec, "bbox", None)
            except Exception:
                bbox = None

        if not isinstance(bbox, (list, tuple)) or len(bbox) < 4:
            return None

        try:
            return tuple(float(v) for v in bbox[:4])
        except Exception:
            return None

    def _char_record_width(self, rec) -> float:
        bbox = self._char_record_bbox(rec)
        if not bbox:
            return 0.0
        return max(0.0, float(bbox[2]) - float(bbox[0]))

    def _char_record_height(self, rec) -> float:
        bbox = self._char_record_bbox(rec)
        if not bbox:
            return 0.0
        return max(0.0, float(bbox[3]) - float(bbox[1]))

    def _char_record_center_y(self, rec) -> float:
        bbox = self._char_record_bbox(rec)
        if not bbox:
            return 0.0
        return (float(bbox[1]) + float(bbox[3])) / 2.0

    def _build_char_record_geometry_stats(self, records):
        prepared = list(records or [])
        widths = [self._char_record_width(rec) for rec in prepared if self._char_record_width(rec) > 0.0]
        heights = [self._char_record_height(rec) for rec in prepared if self._char_record_height(rec) > 0.0]
        centers_y = [self._char_record_center_y(rec) for rec in prepared if self._char_record_bbox(rec)]

        median_width = float(sorted(widths)[len(widths) // 2]) if widths else 0.0
        median_height = float(sorted(heights)[len(heights) // 2]) if heights else 0.0
        median_center_y = float(sorted(centers_y)[len(centers_y) // 2]) if centers_y else 0.0
        return {
            "median_width": median_width,
            "median_height": median_height,
            "median_center_y": median_center_y,
            "count": int(len(prepared)),
        }

    def _char_record_confidence(self, rec) -> float:
        if isinstance(rec, dict):
            try:
                return float(rec.get("confidence", 0.0))
            except Exception:
                return 0.0

        try:
            return float(getattr(rec, "confidence", 0.0))
        except Exception:
            return 0.0

    def _clone_character_detection(self, rec, character=None, method=None):
        symbol, _ = self._char_record_to_symbol_and_x(rec)
        bbox = self._char_record_bbox(rec) or (0.0, 0.0, 1.0, 1.0)
        confidence = self._char_record_confidence(rec)

        return CharacterDetection(
            character=str(character if character is not None else symbol or ""),
            bbox=tuple(float(v) for v in bbox[:4]),
            confidence=float(confidence),
            method=str(method if method is not None else getattr(rec, "method", "ocr") if not isinstance(rec, dict) else rec.get("method", "ocr")),
        )

    def _levenshtein_distance(self, left: str, right: str) -> int:
        left = str(left or "")
        right = str(right or "")

        if left == right:
            return 0
        if not left:
            return len(right)
        if not right:
            return len(left)

        previous = list(range(len(right) + 1))
        for i, left_char in enumerate(left, start=1):
            current = [i]
            for j, right_char in enumerate(right, start=1):
                cost = 0 if left_char == right_char else 1
                current.append(
                    min(
                        previous[j] + 1,
                        current[j - 1] + 1,
                        previous[j - 1] + cost,
                    )
                )
            previous = current

        return previous[-1]

    def _best_text_distance(self, candidate_text: str, true_texts) -> int:
        normalized = [str(item or "").strip().upper() for item in (true_texts or []) if str(item or "").strip()]
        if not normalized:
            return 10 ** 9

        candidate = str(candidate_text or "").strip().upper()
        return min(self._levenshtein_distance(candidate, truth) for truth in normalized)

    def _fit_detection_count_to_truths(self, detections, true_texts):
        ordered = self._sort_character_records_by_x(list(detections or []))
        normalized_truths = [
            str(item or "").strip().upper()
            for item in (true_texts or [])
            if str(item or "").strip()
        ]
        if not ordered or not normalized_truths:
            return ordered, None

        detection_count = len(ordered)
        if detection_count <= 0:
            return ordered, None

        if any(len(truth) == detection_count for truth in normalized_truths):
            return ordered, None

        candidates = [truth for truth in normalized_truths if 0 < len(truth) <= detection_count]
        if not candidates:
            return ordered, None

        best_window = None
        best_details = None
        best_score = None

        for truth in candidates:
            expected_len = len(truth)
            for start_idx in range(0, detection_count - expected_len + 1):
                window = ordered[start_idx:start_idx + expected_len]
                candidate_text = self._characters_to_text(window)
                distance = self._levenshtein_distance(candidate_text, truth)
                avg_conf = (
                    sum(self._char_record_confidence(rec) for rec in window) / float(len(window))
                    if window else 0.0
                )
                dropped_left = int(start_idx)
                dropped_right = int(detection_count - (start_idx + expected_len))
                score = (distance, -avg_conf, dropped_left + dropped_right, dropped_left)
                if best_score is None or score < best_score:
                    best_score = score
                    best_window = window
                    best_details = {
                        "expected_text": truth,
                        "window_text": candidate_text,
                        "original_box_count": int(detection_count),
                        "trimmed_box_count": int(expected_len),
                        "trimmed_extra_boxes": int(detection_count - expected_len),
                        "trimmed_left_boxes": dropped_left,
                        "trimmed_right_boxes": dropped_right,
                        "distance": int(distance),
                    }

        if best_window is None or best_details is None:
            return ordered, None
        if int(best_details.get("trimmed_extra_boxes", 0) or 0) <= 0:
            return ordered, None
        return list(best_window), best_details

    def _apply_final_truth_count_guard(self, characters, true_texts, fusion_details: dict | None = None):
        ordered_chars = self._sort_character_records_by_x(list(characters or []))
        fitted_chars, trim_details = self._fit_detection_count_to_truths(ordered_chars, true_texts)
        if not isinstance(trim_details, dict) or not trim_details:
            return ordered_chars, fusion_details

        merged_details = dict(fusion_details or {})
        merged_details.update(trim_details)
        merged_details["gt_count_guard_applied"] = True
        merged_details["gt_count_guard_stage"] = "final_characters"
        return self._sort_character_records_by_x(list(fitted_chars or [])), merged_details

    def _pick_best_true_text(self, candidate_text: str, true_texts, same_length_only: bool = False) -> str:
        normalized = [str(item or "").strip().upper() for item in (true_texts or []) if str(item or "").strip()]
        if same_length_only:
            normalized = [item for item in normalized if len(item) == len(str(candidate_text or ""))]

        if not normalized:
            return ""

        candidate = str(candidate_text or "").strip().upper()
        return min(
            normalized,
            key=lambda item: (
                self._levenshtein_distance(candidate, item),
                abs(len(candidate) - len(item)),
                item,
            )
        )

    def _get_text_mismatch_positions(self, candidate_text: str, expected_text: str):
        candidate = str(candidate_text or "").strip().upper()
        expected = str(expected_text or "").strip().upper()

        if not candidate or not expected or len(candidate) != len(expected):
            return []

        return [idx for idx, (left, right) in enumerate(zip(candidate, expected)) if left != right]

    def _find_best_yolo_rescue_index(self, slot_index: int, expected_char: str, ocr_detections, yolo_detections, used_indices, min_index: int | None = None):
        if slot_index < 0 or slot_index >= len(ocr_detections):
            return None

        expected_char = str(expected_char or "").strip().upper()
        if not expected_char:
            return None

        _, slot_center_x = self._char_record_to_symbol_and_x(ocr_detections[slot_index], fallback_index=slot_index)
        ocr_width = max(1.0, self._char_record_width(ocr_detections[slot_index]))
        all_ocr_widths = [self._char_record_width(det) for det in ocr_detections if self._char_record_width(det) > 0.0]
        if all_ocr_widths:
            sorted_widths = sorted(all_ocr_widths)
            median_width = float(sorted_widths[len(sorted_widths) // 2])
        else:
            median_width = ocr_width

        allowed_gap = max(6.0, ocr_width * 0.85, median_width * 0.75)

        if slot_index < len(yolo_detections) and slot_index not in used_indices:
            aligned_det = yolo_detections[slot_index]
            aligned_char, aligned_center_x = self._char_record_to_symbol_and_x(aligned_det, fallback_index=slot_index)
            if (min_index is None or slot_index >= int(min_index)) and str(aligned_char or "").strip().upper() == expected_char:
                if abs(aligned_center_x - slot_center_x) <= allowed_gap * 1.35:
                    return slot_index

        best_index = None
        best_score = None

        for idx, det in enumerate(yolo_detections):
            if idx in used_indices:
                continue
            if min_index is not None and idx < int(min_index):
                continue

            det_char, det_center_x = self._char_record_to_symbol_and_x(det, fallback_index=idx)
            if str(det_char or "").strip().upper() != expected_char:
                continue

            center_gap = abs(float(det_center_x) - float(slot_center_x))
            if center_gap > allowed_gap * 1.35:
                continue

            score = (
                (center_gap / allowed_gap)
                + (0.12 * abs(idx - slot_index))
                - min(0.20, self._char_record_confidence(det) * 0.10)
            )

            if best_score is None or score < best_score:
                best_index = idx
                best_score = score

        return best_index

    def _apply_yolo_box_backend(self, base_detections, yolo_detections, *, preserve_base_record_metadata: bool = False):
        ordered_base = self._sort_character_records_by_x(list(base_detections or []))
        ordered_yolo = self._sort_character_records_by_x(list(yolo_detections or []))

        if not ordered_base or not ordered_yolo:
            return ordered_base, None

        expected_text = self._characters_to_text(ordered_base)
        if not expected_text:
            return ordered_base, None

        # W trybie hybrydowym OCR ma pilnować tekstu i kolejności slotów,
        # ale sama geometria powinna być oceniana względem przefiltrowanego YOLO.
        yolo_stats = self._build_char_record_geometry_stats(ordered_yolo)
        yolo_median_width = max(1.0, float(yolo_stats.get("median_width", 0.0) or 0.0))
        yolo_median_height = max(1.0, float(yolo_stats.get("median_height", 0.0) or 0.0))
        yolo_median_center_y = float(yolo_stats.get("median_center_y", 0.0) or 0.0)

        used_yolo_indices = set()
        replaced = [self._clone_character_detection(det) for det in ordered_base]
        replaced_positions = []
        last_yolo_index = -1

        for slot_index, det in enumerate(ordered_base):
            expected_char = expected_text[slot_index] if slot_index < len(expected_text) else ""
            rescue_index = self._find_best_yolo_rescue_index(
                slot_index,
                expected_char,
                ordered_base,
                ordered_yolo,
                used_yolo_indices,
                min_index=last_yolo_index + 1,
            )
            if rescue_index is None:
                continue

            candidate = ordered_yolo[rescue_index]
            candidate_bbox = self._char_record_bbox(candidate)
            if not candidate_bbox:
                continue

            candidate_width = max(1.0, self._char_record_width(candidate))
            candidate_height = max(1.0, self._char_record_height(candidate))
            candidate_center_y = (float(candidate_bbox[1]) + float(candidate_bbox[3])) / 2.0

            width_ratio = candidate_width / yolo_median_width
            height_ratio = candidate_height / yolo_median_height
            median_center_y_gap = abs(candidate_center_y - yolo_median_center_y) if yolo_median_center_y > 0.0 else 0.0
            allowed_center_y_gap = max(8.0, yolo_median_height * 0.42)

            if width_ratio < 0.28 or width_ratio > 2.45:
                continue
            if height_ratio < 0.55 or height_ratio > 1.95:
                continue
            if yolo_median_center_y > 0.0 and median_center_y_gap > allowed_center_y_gap:
                continue
            if self._char_record_confidence(candidate) < 0.18:
                continue

            if preserve_base_record_metadata:
                replaced[slot_index] = self._clone_base_record_with_candidate_bbox(det, candidate)
            else:
                replaced[slot_index] = self._clone_character_detection(
                    candidate,
                    character=expected_char,
                    method="yolo",
                )
            used_yolo_indices.add(rescue_index)
            replaced_positions.append(slot_index)
            last_yolo_index = rescue_index

        if not replaced_positions:
            return ordered_base, None

        replaced = self._sort_character_records_by_x(replaced)
        if self._characters_to_text(replaced) != expected_text:
            return ordered_base, None

        details = {
            "box_backend": "yolo",
            "box_backend_positions": list(replaced_positions),
            "box_backend_count": int(len(replaced_positions)),
            "box_backend_reference": "yolo_filtered",
            "box_backend_reference_count": int(yolo_stats.get("count", 0) or 0),
        }
        return replaced, details

    def _repair_ocr_with_yolo_boxes(self, ocr_detections, yolo_detections, true_texts, max_mismatch_count: int = 2):
        ordered_ocr = self._sort_character_records_by_x(list(ocr_detections or []))
        ordered_yolo = self._sort_character_records_by_x(list(yolo_detections or []))

        if not ordered_ocr or not ordered_yolo:
            return None, None

        max_mismatch_count = max(1, min(5, int(max_mismatch_count or 2)))

        ocr_text = self._characters_to_text(ordered_ocr)
        expected_text = self._pick_best_true_text(ocr_text, true_texts, same_length_only=True)
        if not expected_text:
            return None, None

        mismatch_positions = self._get_text_mismatch_positions(ocr_text, expected_text)
        if not mismatch_positions or len(mismatch_positions) > max_mismatch_count:
            return None, None

        repaired = [self._clone_character_detection(det) for det in ordered_ocr]
        used_yolo_indices = set()

        for slot_index in mismatch_positions:
            rescue_index = self._find_best_yolo_rescue_index(
                slot_index,
                expected_text[slot_index],
                ordered_ocr,
                ordered_yolo,
                used_yolo_indices,
            )
            if rescue_index is None:
                return None, None

            used_yolo_indices.add(rescue_index)
            repaired[slot_index] = self._clone_character_detection(
                ordered_yolo[rescue_index],
                character=expected_text[slot_index],
                method="yolo",
            )

        repaired = self._sort_character_records_by_x(repaired)
        repaired_text = self._characters_to_text(repaired)
        if repaired_text != expected_text:
            return None, None

        details = {
            "ocr_text": ocr_text,
            "yolo_text": self._characters_to_text(ordered_yolo),
            "expected_text": expected_text,
            "mismatch_positions": list(mismatch_positions),
            "max_mismatch_count": int(max_mismatch_count),
        }
        return repaired, details

    def _resolve_canonical_detections(self, method, combined_detections, ocr_detections, yolo_detections, true_texts, hybrid_rescue_max_chars: int = 2, prefer_yolo_box_positions: bool = False):
        ordered_combined = self._sort_character_records_by_x(list(combined_detections or []))
        ordered_ocr = self._sort_character_records_by_x(list(ocr_detections or []))
        ordered_yolo = self._sort_character_records_by_x(list(yolo_detections or []))
        normalized_truths = [
            str(item or "").strip().upper()
            for item in (true_texts or [])
            if str(item or "").strip()
        ]

        def apply_truth_count_guard(source_records, strategy_name: str, details: dict | None = None):
            fitted_records, trim_details = self._fit_detection_count_to_truths(source_records, normalized_truths)
            if not isinstance(trim_details, dict) or not trim_details:
                return source_records, strategy_name, details
            merged_details = dict(details or {})
            merged_details.update(trim_details)
            return fitted_records, strategy_name, merged_details

        if method == DetectionMethod.OCR:
            return apply_truth_count_guard(ordered_ocr or ordered_combined, "ocr_only", None)

        if method == DetectionMethod.YOLO:
            return apply_truth_count_guard(ordered_yolo or ordered_combined, "yolo_only", None)

        if method == DetectionMethod.YOLO_OCR:
            combined_text = self._characters_to_text(ordered_combined)
            details = {
                "box_source": "yolo_nms",
                "box_count": int(len(ordered_combined)),
                "ocr_filled_count": int(sum(1 for rec in ordered_combined if self._preview_record_has_symbol(rec))),
            }

            if normalized_truths:
                if combined_text and combined_text in normalized_truths:
                    details.update({"final_text": combined_text})
                    return apply_truth_count_guard(ordered_combined, "yolo_box_ocr", details)
                details.update({"distance": self._best_text_distance(combined_text, normalized_truths)})
                return apply_truth_count_guard(ordered_combined, "yolo_box_ocr_fallback", details)

            return ordered_combined, "yolo_box_ocr_no_gt", details

        if normalized_truths:
            ocr_text = self._characters_to_text(ordered_ocr)
            yolo_text = self._characters_to_text(ordered_yolo)

            if ocr_text and ocr_text in normalized_truths:
                details = {"final_text": ocr_text}
                if prefer_yolo_box_positions:
                    rebuilt, backend_details = self._apply_yolo_box_backend(ordered_ocr, ordered_yolo)
                    if backend_details:
                        details.update(backend_details)
                        return apply_truth_count_guard(rebuilt, "ocr_exact", details)
                return apply_truth_count_guard(ordered_ocr, "ocr_exact", details)

            if yolo_text and yolo_text in normalized_truths:
                return apply_truth_count_guard(ordered_yolo, "yolo_exact", {"final_text": yolo_text})

            if int(hybrid_rescue_max_chars or 0) > 0:
                rescued, rescue_details = self._repair_ocr_with_yolo_boxes(
                    ordered_ocr,
                    ordered_yolo,
                    normalized_truths,
                    max_mismatch_count=hybrid_rescue_max_chars,
                )
                if rescued:
                    if prefer_yolo_box_positions:
                        rebuilt, backend_details = self._apply_yolo_box_backend(rescued, ordered_yolo)
                        if backend_details:
                            if not isinstance(rescue_details, dict):
                                rescue_details = {}
                            rescue_details.update(backend_details)
                            return apply_truth_count_guard(rebuilt, "ocr_yolo_rescue", rescue_details)
                    return apply_truth_count_guard(rescued, "ocr_yolo_rescue", rescue_details)

            best_source = ordered_ocr or ordered_yolo or ordered_combined
            best_strategy = "ocr_fallback" if ordered_ocr else ("yolo_fallback" if ordered_yolo else "both_combined")
            best_distance = self._best_text_distance(self._characters_to_text(best_source), normalized_truths)

            for candidate_source, candidate_strategy in (
                (ordered_yolo, "yolo_fallback"),
                (ordered_combined, "both_combined"),
            ):
                if not candidate_source:
                    continue

                candidate_distance = self._best_text_distance(self._characters_to_text(candidate_source), normalized_truths)
                if candidate_distance < best_distance:
                    best_source = candidate_source
                    best_strategy = candidate_strategy
                    best_distance = candidate_distance

            return apply_truth_count_guard(best_source, best_strategy, {"distance": best_distance})

        return ordered_combined, "both_combined_no_gt", None

    def _get_preview_box_mode_key(self) -> str:
        raw_value = str((getattr(self, "preview_box_mode_var", None).get() if hasattr(self, "preview_box_mode_var") else "AUTO") or "AUTO").strip()
        if not raw_value:
            return "AUTO"

        direct_key = raw_value.upper()
        if direct_key in PREVIEW_BOX_MODE_LABELS:
            return direct_key

        return PREVIEW_BOX_MODE_BY_LABEL.get(raw_value, "AUTO")

    def _normalize_detection_method_key(self, raw_value=None) -> str:
        value = str(raw_value or "").strip()
        if not value:
            return "OCR"

        upper_value = value.upper()
        if upper_value in DETECTION_METHOD_LABELS:
            return upper_value

        return DETECTION_METHOD_KEY_BY_LABEL.get(value, "OCR")

    def _get_detection_method_key(self) -> str:
        raw_value = getattr(self, "detection_method_var", None).get() if hasattr(self, "detection_method_var") else "OCR"
        return self._normalize_detection_method_key(raw_value)

    def _get_hybrid_rescue_max_chars(self) -> int:
        try:
            value = int(self.hybrid_rescue_max_chars_var.get())
        except Exception:
            value = 2
        return max(0, min(5, value))

    def _use_hybrid_yolo_box_backend(self) -> bool:
        try:
            return bool(self.hybrid_yolo_box_backend_var.get())
        except Exception:
            return True

    def _get_hybrid_detection_status_text(self) -> str:
        rescue_chars = self._get_hybrid_rescue_max_chars()
        backend_state = "ON" if self._use_hybrid_yolo_box_backend() else "OFF"
        rescue_text = "OFF" if rescue_chars <= 0 else f"YOLO rescue <= {rescue_chars}"
        return (
            f"odczyt: OCR | dopasowanie pozycji: YOLO | rescue: {rescue_text} | "
            f"koncowe ramki z YOLO: {backend_state}"
        )

    def _get_yolo_box_ocr_status_text(self) -> str:
        return "boxy: YOLO | odczyt cropow: OCR | koncowe ramki z YOLO"

    def _get_detection_pipeline_blocks(self, method_key: str | None = None) -> list[str]:
        resolved_method = self._normalize_detection_method_key(method_key or self._get_detection_method_key())
        if resolved_method == "YOLO":
            return ["yolo_box", "yolo_symbol"]
        if resolved_method == "BOTH":
            blocks = ["ocr_symbol", "yolo_box"]
            if self._get_hybrid_rescue_max_chars() > 0:
                blocks.append("yolo_symbol")
            return blocks
        if resolved_method == "YOLO_OCR":
            return ["yolo_box", "ocr_symbol"]
        return ["ocr_symbol"]

    def _compile_detection_pipeline_blocks(self, blocks=None) -> dict:
        prepared = [
            str(block or "").strip().lower().replace("-", "_")
            for block in (blocks or [])
            if str(block or "").strip()
        ]
        valid_patterns = {
            ("ocr_symbol",): ("OCR", False),
            ("yolo_box", "yolo_symbol"): ("YOLO", False),
            ("ocr_symbol", "yolo_box"): ("BOTH", False),
            ("ocr_symbol", "yolo_box", "yolo_symbol"): ("BOTH", True),
            ("yolo_box", "ocr_symbol"): ("YOLO_OCR", False),
        }
        compiled = valid_patterns.get(tuple(prepared))
        if compiled is None:
            return {
                "valid": False,
                "blocks": prepared,
                "method_key": None,
                "rescue_enabled": False,
                "requires_yolo": any(block.startswith("yolo") for block in prepared),
                "status_text": (
                    "Ten lancuch nie jest jeszcze wspierany. "
                    "Dozwolone uklady: O | YB->YS | O->YB | O->YB->YS | YB->O."
                ),
            }

        method_key, rescue_enabled = compiled
        label = DETECTION_METHOD_CARD_META.get(method_key, {}).get("title", method_key)
        status_text = f"Builder zlozy ten pipeline jako tryb: {label}"
        if method_key == "BOTH":
            status_text += " z rescue" if rescue_enabled else " bez rescue"
        return {
            "valid": True,
            "blocks": prepared,
            "method_key": method_key,
            "rescue_enabled": bool(rescue_enabled),
            "requires_yolo": method_key in {"YOLO", "BOTH", "YOLO_OCR"},
            "status_text": status_text,
        }

    def _apply_detection_pipeline_blocks(self, blocks, *, save: bool = True, prompt_for_yolo_model: bool = True) -> bool:
        compiled = self._compile_detection_pipeline_blocks(blocks)
        if not bool(compiled.get("valid")):
            return False

        method_key = str(compiled.get("method_key") or "OCR")
        requires_yolo = bool(compiled.get("requires_yolo"))
        if requires_yolo and not self._has_configured_yolo_detection_model():
            if prompt_for_yolo_model:
                selected_model = str(self._pick_yolo_model() or "").strip()
                if not selected_model or not self._has_configured_yolo_detection_model():
                    messagebox.showinfo(
                        "Brak modelu YOLO",
                        "Ten pipeline wymaga modelu YOLO znaków. Wskaż poprawny plik .pt, aby go zatwierdzic.",
                    )
                    return False
            else:
                return False

        if method_key == "BOTH":
            rescue_enabled = bool(compiled.get("rescue_enabled"))
            current_rescue = self._get_hybrid_rescue_max_chars()
            target_rescue = current_rescue if current_rescue > 0 else 2
            try:
                self.hybrid_rescue_max_chars_var.set(target_rescue if rescue_enabled else 0)
            except Exception:
                pass

        self._set_detection_method_key(method_key, save=save)
        self._refresh_detection_workflow_info_label()
        return True

    def _get_detection_workflow_text(self, method_key: str | None = None) -> str:
        resolved_method = self._normalize_detection_method_key(method_key or self._get_detection_method_key())
        if resolved_method == "YOLO":
            return (
                "Pipeline wybranego trybu:\n"
                "1. YOLO wykrywa znaki na tablicy.\n"
                "2. YOLO przypisuje klasę każdemu znakowi.\n"
                "3. Koncowe ramki i odczyt pochodza z YOLO."
            )
        if resolved_method == "BOTH":
            rescue_chars = self._get_hybrid_rescue_max_chars()
            return (
                "Pipeline wybranego trybu:\n"
                "1. OCR odczytuje napis i ustala kolejność znaków.\n"
                "2. YOLO dopasowuje znaki do realnych pozycji na tablicy.\n"
                f"3. Rescue YOLO jest {'wlaczone' if rescue_chars > 0 else 'wylaczone'}"
                + (f" (max {rescue_chars} pozycji).\n" if rescue_chars > 0 else ".\n")
                + "4. Opcjonalnie YOLO przejmuje koncowe ramki do treningu."
            )
        if resolved_method == "YOLO_OCR":
            return (
                "Pipeline wybranego trybu:\n"
                "1. YOLO wykrywa boxy znaków i porządkuje ich kolejność.\n"
                "2. Kazdy box jest wycinany jako osobny crop znaku.\n"
                "3. OCR czyta cropy, a koncowe ramki zostaja z YOLO."
            )
        return (
            "Pipeline wybranego trybu:\n"
            "1. OCR odczytuje cały napis z tablicy.\n"
            "2. System dzieli wspólny box OCR na techniczne segmenty znaków.\n"
            "3. Koncowe ramki pochodza z segmentacji OCR."
        )

    def _refresh_detection_workflow_info_label(self):
        label = getattr(self, "detect_workflow_info_lbl", None)
        if label is None:
            return
        try:
            label.configure(text=self._get_detection_workflow_text())
        except Exception:
            pass
        try:
            self._refresh_detection_active_model_label()
        except Exception:
            pass

    def _get_detection_active_model_status(self) -> tuple[str, str]:
        method_key = self._get_detection_method_key()
        uses_yolo = method_key in ("YOLO", "BOTH", "YOLO_OCR")
        model_path = str(self._get_effective_yolo_model_path() or "").strip()
        path_locked = bool(getattr(self, "_step3_linear_mode", False))

        if model_path and Path(model_path).exists():
            model_name = Path(model_path).name
            version, size = self._infer_yolo_arch_from_model_path(model_path)
            if version and size:
                model_name = f"{model_name} (YOLOv{version}{size})"

            source_suffix = " z projektu" if path_locked else ""
            if uses_yolo:
                return f"Aktywny model YOLO: {model_name}{source_suffix}", "neutral"
            return f"Model YOLO gotowy: {model_name}{source_suffix} | w tym trybie nie jest używany", "muted"

        if uses_yolo:
            return "Aktywny model YOLO: brak wybranego modelu", "warning"
        if path_locked:
            return "Aktywny model YOLO: sterowany przez projekt i nieużywany w trybie OCR", "muted"
        return "Aktywny model YOLO: nieużywany w trybie OCR", "muted"

    def _refresh_detection_active_model_label(self):
        label = getattr(self, "detect_active_model_lbl", None)
        if label is None:
            return
        text, tone = self._get_detection_active_model_status()
        self._set_themed_label_state(label, text=text, tone=tone)

    def _get_preview_box_mode_label(self, key=None) -> str:
        resolved_key = (key or self._get_preview_box_mode_key() or "AUTO").upper().strip()
        return PREVIEW_BOX_MODE_LABELS.get(resolved_key, PREVIEW_BOX_MODE_LABELS["AUTO"])

    @staticmethod
    def _normalize_preview_sort_mode_key(mode_key: str | None) -> str:
        normalized = str(mode_key or "DEFAULT").strip().upper() or "DEFAULT"
        legacy_aliases = {
            "PERFECT": "OK",
            "MANUAL": "M",
        }
        normalized = legacy_aliases.get(normalized, normalized)
        return normalized if normalized in PREVIEW_SORT_LABELS else "DEFAULT"

    def _get_preview_sort_mode_key(self) -> str:
        raw_value = (getattr(self, "preview_sort_mode_var", None).get() if hasattr(self, "preview_sort_mode_var") else "DEFAULT")
        return self._normalize_preview_sort_mode_key(raw_value)

    def _get_preview_sort_source_count(self, mode_key: str, data: dict | None = None) -> int:
        normalized_key = str(mode_key or "").strip().upper()
        source_data = data if isinstance(data, dict) else {}
        chars = list(source_data.get("characters", []) or []) if isinstance(source_data, dict) else []
        if not chars:
            return 0

        counts = self._count_character_sources(chars, data=source_data)
        if normalized_key == "YOLO":
            return int(counts.get("yolo", 0)) + int(counts.get("yolo_box_ocr", 0))
        if normalized_key == "OCR":
            return int(counts.get("ocr", 0))
        if normalized_key == "M":
            return int(counts.get("manual", 0))
        return 0

    def _get_preview_sort_priority(self, pid: str, data: dict, original_index: int):
        mode_key = self._get_preview_sort_mode_key()
        status = str((data or {}).get("status", "unknown")).strip().lower()
        strategy_bucket = self._get_perfect_strategy_bucket(data)
        total_boxes = len(list((data or {}).get("characters", []) or [])) if isinstance(data, dict) else 0

        if mode_key == "DEFAULT":
            return (0, int(original_index))

        if mode_key == "OK":
            if status == "perfect":
                return (0, -int(total_boxes), int(original_index))
            if status == "needs_fix":
                return (1, -int(total_boxes), int(original_index))
            return (2, -int(total_boxes), int(original_index))

        preferred_bucket = {
            "YOLO": {"yolo_exact", "yolo_box_ocr"},
            "OCR": {"ocr_exact"},
            "M": {"other_perfect"},
        }.get(mode_key)

        if preferred_bucket:
            source_count = self._get_preview_sort_source_count(mode_key, data=data)
            return (
                -int(source_count),
                -int(total_boxes),
                0 if (status == "perfect" and strategy_bucket in preferred_bucket) else 1,
                0 if status == "perfect" else (1 if status == "needs_fix" else 2),
                int(original_index),
            )

        return (0, int(original_index))

    def _get_sorted_preview_plate_ids(self, ordered_pids):
        base_order = list(ordered_pids or [])
        mode_key = self._get_preview_sort_mode_key()
        if mode_key == "DEFAULT":
            return base_order

        indexed = list(enumerate(base_order))
        indexed.sort(
            key=lambda item: self._get_preview_sort_priority(
                item[1],
                self.preview_metadata.get(item[1], {}),
                item[0],
            )
        )
        return [pid for _, pid in indexed]

    def _set_preview_sort_hover(self, mode_key: str, hovered: bool):
        normalized_key = str(mode_key or "").strip().upper()
        if hovered:
            self._preview_sort_hover_key = normalized_key
        elif self._preview_sort_hover_key == normalized_key:
            self._preview_sort_hover_key = None
        self._apply_preview_sort_bar_style()

    def _get_readable_text_color(self, background: str, preferred: str = None) -> str:
        def _normalize_hex(color_value):
            raw = str(color_value or "").strip()
            if not raw.startswith("#"):
                return None
            hex_part = raw[1:]
            if len(hex_part) == 3:
                hex_part = "".join(ch * 2 for ch in hex_part)
            if len(hex_part) != 6:
                return None
            try:
                return tuple(int(hex_part[i:i + 2], 16) for i in (0, 2, 4))
            except Exception:
                return None

        def _relative_luminance(rgb):
            channels = []
            for channel in rgb:
                normalized = channel / 255.0
                if normalized <= 0.03928:
                    channels.append(normalized / 12.92)
                else:
                    channels.append(((normalized + 0.055) / 1.055) ** 2.4)
            return (0.2126 * channels[0]) + (0.7152 * channels[1]) + (0.0722 * channels[2])

        def _contrast_ratio(color_a, color_b):
            lum_a = _relative_luminance(color_a)
            lum_b = _relative_luminance(color_b)
            lighter = max(lum_a, lum_b)
            darker = min(lum_a, lum_b)
            return (lighter + 0.05) / (darker + 0.05)

        bg_rgb = _normalize_hex(background)
        if bg_rgb is None:
            return preferred or "#ffffff"

        preferred_rgb = _normalize_hex(preferred)
        if preferred_rgb is not None and _contrast_ratio(bg_rgb, preferred_rgb) >= 4.5:
            return preferred

        dark_text = "#111111"
        light_text = "#ffffff"
        dark_rgb = _normalize_hex(dark_text)
        light_rgb = _normalize_hex(light_text)
        if dark_rgb is None or light_rgb is None:
            return preferred or light_text

        dark_ratio = _contrast_ratio(bg_rgb, dark_rgb)
        light_ratio = _contrast_ratio(bg_rgb, light_rgb)
        return dark_text if dark_ratio >= light_ratio else light_text

    def _apply_preview_sort_bar_style(self):
        palette = getattr(self.app, "palette", {})
        frame = getattr(self, "preview_sort_bar", None)
        label = getattr(self, "preview_sort_title_lbl", None)
        if frame is not None:
            try:
                frame.configure(
                    bg=palette.get("panel_alt", palette.get("panel", "#252526")),
                    highlightbackground=palette.get("border", "#3c3c3c"),
                    highlightcolor=palette.get("border", "#3c3c3c"),
                )
            except Exception:
                pass
        if label is not None:
            try:
                label.configure(
                    text="Sortowanie listy:",
                    bg=palette.get("panel_alt", palette.get("panel", "#252526")),
                    fg=palette.get("muted", "#a0a0a0"),
                )
            except Exception:
                pass
        buttons_frame = getattr(self, "preview_sort_buttons_frame", None)
        if buttons_frame is not None:
            try:
                buttons_frame.configure(bg=palette.get("panel_alt", palette.get("panel", "#252526")))
            except Exception:
                pass
            for child in buttons_frame.winfo_children():
                if isinstance(child, tk.Frame):
                    try:
                        child.configure(bg=palette.get("border", "#3c3c3c"))
                    except Exception:
                        pass

        active_key = self._get_preview_sort_mode_key()
        hover_key = str(getattr(self, "_preview_sort_hover_key", "") or "").strip().upper()
        for mode_key, button in getattr(self, "preview_sort_buttons", {}).items():
            if button is None:
                continue
            is_active = mode_key == active_key
            is_hovered = mode_key == hover_key
            bg = palette.get("panel_alt", palette.get("panel", "#2d2d30"))
            fg = palette.get("fg", "#f3f3f3")
            relief = tk.RAISED
            border = 1

            if is_active:
                bg = palette.get("surface_info", palette.get("button_hover", "#3a3d41"))
                relief = tk.SUNKEN
            elif is_hovered:
                bg = palette.get("button_hover", palette.get("surface_info", "#34373b"))

            resolved_fg = self._get_readable_text_color(bg, preferred=fg)
            active_bg = bg if is_active else palette.get("button_hover", bg)
            active_fg = self._get_readable_text_color(active_bg, preferred=resolved_fg)

            try:
                button.configure(
                    text=str(PREVIEW_SORT_LABELS.get(mode_key, mode_key) or mode_key),
                    bg=bg,
                    fg=resolved_fg,
                    activebackground=active_bg,
                    activeforeground=active_fg,
                    relief=relief,
                    bd=border,
                    highlightbackground=palette.get("border", "#3c3c3c"),
                    highlightcolor=palette.get("border", "#3c3c3c"),
                    disabledforeground=resolved_fg,
                )
            except Exception:
                pass

    def _on_preview_sort_mode_change(self, mode_key: str = None):
        normalized_key = self._normalize_preview_sort_mode_key(
            mode_key or self._get_preview_sort_mode_key()
        )

        try:
            if self.preview_sort_mode_var.get() != normalized_key:
                self.preview_sort_mode_var.set(normalized_key)
        except Exception:
            pass

        try:
            self._save_local_setting("char_preview_sort_mode", normalized_key)
        except Exception:
            pass

        self._apply_preview_sort_bar_style()

        if hasattr(self, "plates_listbox"):
            self._rebuild_preview_listbox(preserve_selection=True)
            try:
                self._on_preview_select(None)
            except Exception:
                pass

    def _get_preview_box_variants(self, data: dict) -> dict:
        if not isinstance(data, dict):
            data = {}
        canonical_chars = self._sort_character_records_by_x(data.get("characters", []))
        yolo_filtered = self._sort_character_records_by_x(data.get("yolo_detections", []))
        yolo_nms = self._sort_character_records_by_x(data.get("yolo_nms_detections", []))
        yolo_raw = self._sort_character_records_by_x(data.get("yolo_raw_detections", []))

        if not yolo_filtered:
            yolo_from_canonical = [
                rec for rec in canonical_chars
                if isinstance(rec, dict) and str(rec.get("method", "")).strip().lower() == "yolo"
            ]
            yolo_filtered = self._sort_character_records_by_x(yolo_from_canonical)

        return {
            "FINAL": canonical_chars,
            "YOLO_FILTERED": yolo_filtered,
            "YOLO_NMS": yolo_nms,
            "YOLO_RAW": yolo_raw,
        }

    def _get_preview_box_records(self, data: dict):
        variants = self._get_preview_box_variants(data)
        method_name = self._get_detection_method_key()
        mode_key = self._get_preview_box_mode_key()

        if mode_key == "AUTO":
            final_records = list(variants.get("FINAL", []) or [])
            if final_records:
                return final_records, "FINAL"
            if method_name == "YOLO":
                for candidate_key in ("YOLO_FILTERED", "YOLO_NMS", "YOLO_RAW"):
                    candidate_records = variants.get(candidate_key, [])
                    if candidate_records:
                        return candidate_records, candidate_key
            for candidate_key in ("YOLO_FILTERED", "YOLO_NMS", "YOLO_RAW"):
                candidate_records = variants.get(candidate_key, [])
                if candidate_records:
                    return candidate_records, candidate_key
            return final_records, "FINAL"

        return variants.get(mode_key, []), mode_key

    def _get_preview_box_palette(self, index: int):
        palettes = [
            ("#ff6b6b", "#ffc1c1", "#ffe9e9"),
            ("#4ecdc4", "#a6f4ef", "#e8fffd"),
            ("#ffd166", "#ffe29a", "#fff7db"),
            ("#6c5ce7", "#c8bfff", "#f0edff"),
            ("#00b894", "#7ee6ca", "#ebfff8"),
            ("#0984e3", "#74b9ff", "#ecf7ff"),
            ("#e17055", "#fab1a0", "#fff1ec"),
            ("#a29bfe", "#d6d1ff", "#f5f4ff"),
            ("#e84393", "#ffb0d5", "#fff0f7"),
            ("#2d98da", "#8fd0ff", "#eef8ff"),
        ]
        return palettes[index % len(palettes)]

