    # Pickers
    # =========================================================

    def _pick_xml_file(self):
        initial_dir = ""
        try:
            initial_dir = str(CAMPAIGN.get_dir("auto_ann") or "")
        except Exception:
            initial_dir = ""
        if not initial_dir:
            initial_dir = str(Path(CONFIG.get_auto_annotations_dir("plate")).absolute())
        p = filedialog.askopenfilename(
            initialdir=initial_dir,
            title="Wybierz annotations.xml dla tego samego katalogu obrazów",
            filetypes=[("XML", "*.xml")]
        )
        if p:
            self.xml_path_var.set(p)

    def _pick_images_dir(self):
        initial_dir = ""
        try:
            initial_dir = str(CAMPAIGN.get_dir("raw") or "")
        except Exception:
            initial_dir = ""
        if not initial_dir:
            initial_dir = str(Path(CONFIG.DIR_1_RAW).absolute())
        p = filedialog.askdirectory(
            initialdir=initial_dir,
            title="Wybierz katalog obrazów powiazany z annotations.xml"
        )
        if p:
            self.images_dir_var.set(p)

    def _pick_yolo_model(self):
        initial_dir = CONFIG.get_trained_models_dir("char")
        if not initial_dir.exists():
            initial_dir = CONFIG.DIR_6_MODELS
        p = filedialog.askopenfilename(
            initialdir=str(Path(initial_dir).absolute()),
            title="Wybierz model YOLO (.pt)",
            filetypes=[("PyTorch", "*.pt")]
        )
        if not p:
            return ""

        try:
            chosen = Path(p)
        except Exception:
            return ""

        if chosen.suffix.lower() != ".pt" or not chosen.exists():
            messagebox.showwarning(
                "Błędny model YOLO",
                "Wskaż poprawny, wytrenowany model YOLO znaków z rozszerzeniem .pt.",
            )
            return ""

        self.yolo_model_path_var.set(str(chosen))
        try:
            self._force_save_all()
        except Exception:
            pass
        self._refresh_detect_mode_cards()
        self._update_yolo_visibility()
        return str(chosen)

    def _pick_and_load_preview_dir(self):
        initial = str(self._get_step3_chars_root_dir())
        p = filedialog.askdirectory(initialdir=str(initial), title="Wybierz folder wyników (zawierający metadata.json)")
        if p:
            self.preview_dir_var.set(p)
            self._force_save_all()
            self._reset_preview_cache()
            self._load_preview_data()

    # =========================================================
    # Logging helper
    # =========================================================

    def _log(self, txt_widget, msg: str, tag: str = "INFO"):
        try:
            if hasattr(self.app, "append_global_terminal"):
                self.app.append_global_terminal(msg, source="PZ2")
        except Exception:
            pass

        if txt_widget in (getattr(self, "export_console", None), getattr(self, "import_console", None)):
            try:
                refresh = getattr(self, "_refresh_pz3_cards_ui", None)
                if callable(refresh):
                    refresh()
            except Exception:
                pass
            if not isinstance(txt_widget, tk.Text):
                return

        def do_log():
            try:
                txt_widget.configure(state="normal")

                if not txt_widget.tag_names():
                    txt_widget.tag_config("SUCCESS", foreground="#27ae60", font=("Consolas", 9, "bold"))
                    txt_widget.tag_config("ERROR", foreground="#c0392b", font=("Consolas", 9, "bold"))
                    txt_widget.tag_config("WARNING", foreground="#d35400", font=("Consolas", 9, "bold"))
                    txt_widget.tag_config("INFO", foreground="#2980b9", font=("Consolas", 9))
                    txt_widget.tag_config("HEADER", foreground="#8e44ad", font=("Consolas", 10, "bold"))

                final_tag = tag
                if tag == "INFO":
                    if "✅" in msg:
                        final_tag = "SUCCESS"
                    elif "❌" in msg:
                        final_tag = "ERROR"

                txt_widget.insert(tk.END, msg + "\n", final_tag)
                txt_widget.see(tk.END)
                txt_widget.update_idletasks()

            finally:
                try:
                    txt_widget.configure(state="disabled")
                except Exception:
                    pass

        self.frame.after(0, do_log)

    def _build_step3_local_success_message(self, title: str, target_path, next_hint: str) -> str:
        lines = [f"Proces zakończył się sukcesem: {title}"]
        if target_path:
            lines.append(f"Ścieżka: {target_path}")
        if next_hint:
            lines.append(f"Dalej: {next_hint}")
        return "\n".join(lines)

    def _get_true_texts_from_filename(self, filename: str) -> list:
        stem = Path(str(filename or "")).stem.upper()
        if not stem:
            return []
        import re
        ignore_tokens = {
            "PLATE",
            "PLATES",
            "TABLICA",
            "TABLICE",
            "IMG",
            "IMAGE",
            "PHOTO",
            "RAW",
            "SOURCE",
            "RUN",
            "SAMPLE",
            "SAMPLES",
            "FRAME",
            "CAPTURE",
            "PREVIEW",
            "FILE",
            "PLIK",
            "CROP",
        }
        parts = re.findall(r"[A-Z0-9]+", stem)
        strict_candidates = []
        numeric_fallback = []
        seen = set()
        for raw_part in parts:
            part = str(raw_part or "").strip().upper()
            if not part or part in seen or part in ignore_tokens:
                continue
            if len(part) < 4 or len(part) > 12:
                continue
            has_letter = any(ch.isalpha() for ch in part)
            has_digit = any(ch.isdigit() for ch in part)
            seen.add(part)
            if has_letter and has_digit:
                strict_candidates.append(part)
                continue
            if part.isdigit():
                numeric_fallback.append(part)

        # Prefer klasyczne tablice alfa-numeryczne, ale gdy nazwa zawiera
        # wyłącznie poprawny numer zapisany cyframi, użyj go jako wzorca.
        return strict_candidates if strict_candidates else numeric_fallback

    def _get_current_prep_params(self):
        return {
            "target_height": self.prep_height_var.get(),
            "manual_angle": self.prep_angle_var.get(),
            "clip_thresh": self.prep_clip_var.get(),
            "denoise_h": self.prep_denoise_var.get(),
            "clahe_clip": self.prep_clahe_var.get() if self.do_clahe_var.get() else 0.0,
            "use_binarization": self.prep_use_bin_var.get(),
            "thresh_block": self.prep_block_var.get(),
            "thresh_c": self.prep_c_var.get(),
            "erode_iter": self.prep_erode_var.get(),
            "interpolation": self.interpolation_var.get(),
            "padding_pct": self.prep_padding_var.get(),
        }

    def _get_best_preset(self):
        cache_file = self.presets_dir / "global_ranking.json"
        if not cache_file.exists():
            return None, 0.0
        try:
            with open(cache_file, 'r', encoding='utf-8') as f:
                data = json.load(f)
            best_name, best_acc, best_params = None, -1.0, {}
            for preset_key, stats in data.items():
                acc = float(stats.get("acc", 0.0))
                if acc > best_acc:
                    best_acc, best_name, best_params = acc, str(stats.get("name", preset_key)), stats.get("params", {})
            if best_name:
                return {"name": best_name, "params": best_params}, best_acc
        except Exception:
            pass
        return None, 0.0

    def _normalize_extract_entry_mode(self, value: str | None = None) -> str:
        normalized = str(
            value if value is not None else (self.extract_entry_mode_var.get() if hasattr(self, "extract_entry_mode_var") else "")
            or ""
        ).strip().lower()
        if not normalized:
            return ""
        return normalized if normalized in {"continue", "manual"} else ""

    @staticmethod
    def _normalize_extract_workflow_step(step: str | None = None) -> str:
        normalized = str(step or "").strip().lower()
        return normalized if normalized in {"entry", "source", "start"} else "entry"

    def _coerce_extract_workflow_step(self, step: str | None = None) -> str:
        route = self._get_extract_entry_mode()
        current = self._normalize_extract_workflow_step(
            step if step is not None else getattr(self, "_extract_workflow_step", "entry")
        )
        has_preview = bool(str(self.preview_dir_var.get() or "").strip())
        source_ready = bool(getattr(self, "_extract_last_source_binding_result", {}).get("ok"))

        if not route:
            return "entry"
        if current == "entry":
            return "entry"
        if route == "continue":
            return "start"
        if current == "start" and not (source_ready or has_preview):
            return "source"
        return current if current in {"source", "start"} else "source"

    def _get_extract_workflow_step(self) -> str:
        current = self._coerce_extract_workflow_step()
        self._extract_workflow_step = current
        return current

    def _set_extract_workflow_step(self, step: str, *, refresh: bool = True):
        self._extract_workflow_step = self._coerce_extract_workflow_step(step)
        try:
            self._persist_step3_extract_state()
        except Exception:
            pass
        if refresh:
            self._refresh_extract_workflow_ui()

    def _get_extract_entry_mode(self) -> str:
        return self._normalize_extract_entry_mode()

    def _set_extract_entry_mode(self, mode: str, *, persist: bool = True):
        normalized = self._normalize_extract_entry_mode(mode)
        try:
            if self.extract_entry_mode_var.get() != normalized:
                self.extract_entry_mode_var.set(normalized)
        except Exception:
            pass

        self._set_extract_workflow_step("source" if normalized else "entry", refresh=False)
        if persist:
            try:
                self._persist_step3_extract_state()
            except Exception:
                pass
        self._refresh_extract_workflow_ui()

    def _handle_extract_entry_selection(self, mode: str):
        selected_mode = self._normalize_extract_entry_mode(mode)
        if selected_mode == "continue":
            if self._use_z2_source_on_demand(notify_on_failure=True, advance_to_start=True):
                return
            try:
                self.extract_entry_mode_var.set("")
            except Exception:
                pass
            self._set_extract_workflow_step("entry")
            return

        self._reset_extract_source_inputs()
        self._set_extract_entry_mode("manual")

    def _reset_extract_source_inputs(self):
        self._source_binding_sync_in_progress = True
        try:
            self.annotation_run_dir_var.set("")
            self.xml_path_var.set("")
            self.images_dir_var.set("")
            self.preview_dir_var.set("")
        finally:
            self._source_binding_sync_in_progress = False

        self._extract_last_source_binding_result = {"ok": False}

        try:
            self._reset_preview_cache()
        except Exception:
            pass

        try:
            self.ext_progress.config(value=0)
        except Exception:
            pass

        try:
            self._set_extraction_status("Gotowy", "neutral")
        except Exception:
            pass

        try:
            self._set_source_binding_status("", "warning")
        except Exception:
            pass

        try:
            self._force_save_all()
        except Exception:
            pass

        try:
            self._persist_step3_extract_state()
        except Exception:
            pass

    def _persist_step3_extract_state(self):
        if not CAMPAIGN.get_active_project_name():
            return

        try:
            entry_mode = self._get_extract_entry_mode()
        except Exception:
            entry_mode = ""

        try:
            workflow_step = self._get_extract_workflow_step()
        except Exception:
            workflow_step = "entry"

        try:
            annotation_run_dir = str(self.annotation_run_dir_var.get() or "").strip()
        except Exception:
            annotation_run_dir = ""

        try:
            xml_path = str(self.xml_path_var.get() or "").strip()
        except Exception:
            xml_path = ""

        try:
            images_dir = str(self.images_dir_var.get() or "").strip()
        except Exception:
            images_dir = ""

        try:
            CAMPAIGN.set_step3_extract_state(
                entry_mode=entry_mode,
                workflow_step=workflow_step,
                annotation_run_dir=annotation_run_dir,
                xml_path=xml_path,
                images_dir=images_dir,
            )
        except Exception:
            pass

        try:
            self._sync_campaign_step3_artifact_registry(
                entry_mode=entry_mode,
                workflow_step=workflow_step,
                annotation_run_dir=annotation_run_dir,
                xml_path=xml_path,
                images_dir=images_dir,
            )
        except Exception:
            pass

    def _sync_campaign_step3_artifact_registry(
        self,
        *,
        entry_mode: str = "",
        workflow_step: str = "entry",
        annotation_run_dir: str = "",
        xml_path: str = "",
        images_dir: str = "",
    ) -> None:
        if not CAMPAIGN.get_active_project_name():
            return

        try:
            iteration_num = int(CAMPAIGN.get_current_iteration_num() or 1)
        except Exception:
            iteration_num = 1

        package_images_dir = CAMPAIGN.get_master_pool_dir() or CAMPAIGN.get_iteration_raw_dir(iteration_num)
        if package_images_dir is None:
            return

        updates = {
            "step3_extract_source": {
                "entry_mode": str(entry_mode or "").strip(),
                "workflow_step": str(workflow_step or "entry").strip() or "entry",
                "annotation_run_dir": str(annotation_run_dir or "").strip(),
                "annotation_run_token": CAMPAIGN._build_registry_path_token(annotation_run_dir),
                "xml_path": str(xml_path or "").strip(),
                "xml_token": CAMPAIGN._build_registry_path_token(xml_path),
                "images_dir": str(images_dir or "").strip(),
                "images_token": CAMPAIGN._build_registry_path_token(images_dir),
            }
        }
        try:
            CAMPAIGN.upsert_iteration_artifact_bundle(
                images_dir=package_images_dir,
                iteration_num=iteration_num,
                updates=updates,
            )
        except Exception:
            pass

    def _restore_step3_extract_state_from_project(self):
        if not CAMPAIGN.get_active_project_name():
            return

        try:
            saved_state = CAMPAIGN.get_step3_extract_state()
        except Exception:
            saved_state = {}

        saved_mode = self._normalize_extract_entry_mode(saved_state.get("entry_mode"))
        saved_step = self._normalize_extract_workflow_step(saved_state.get("workflow_step"))
        saved_run_dir = str(saved_state.get("annotation_run_dir", "") or "").strip()
        saved_xml = str(saved_state.get("xml_path", "") or "").strip()
        saved_images = str(saved_state.get("images_dir", "") or "").strip()

        if not saved_mode:
            try:
                self.extract_entry_mode_var.set("")
            except Exception:
                pass
            self._extract_workflow_step = "entry"
            return

        if saved_mode == "continue":
            restored = False
            try:
                restored = self._use_z2_source_on_demand(
                    notify_on_failure=False,
                    advance_to_start=(saved_step == "start"),
                )
            except Exception:
                restored = False

            if restored:
                if saved_step != "start":
                    self._extract_workflow_step = self._coerce_extract_workflow_step(saved_step)
                try:
                    self._refresh_extract_workflow_ui()
                except Exception:
                    pass
                return

        self._source_binding_sync_in_progress = True
        try:
            self.annotation_run_dir_var.set(saved_run_dir)
            self.xml_path_var.set(saved_xml)
            self.images_dir_var.set(saved_images)
        finally:
            self._source_binding_sync_in_progress = False

        try:
            self._set_extract_entry_mode(saved_mode, persist=False)
        except Exception:
            self._extract_workflow_step = "source" if saved_mode else "entry"

        try:
            validation = self._refresh_source_binding_status(allow_autofind=True)
        except Exception:
            validation = {"ok": False}

        target_step = saved_step
        if target_step == "start" and not bool(validation.get("ok")) and not bool(str(self.preview_dir_var.get() or "").strip()):
            target_step = "source"

        self._extract_workflow_step = self._coerce_extract_workflow_step(target_step)
        try:
            self._refresh_extract_workflow_ui()
        except Exception:
            pass

    def _go_to_previous_extract_step(self):
        current = self._get_extract_workflow_step()
        route = self._get_extract_entry_mode()
        if current == "start":
            self._set_extract_workflow_step("entry" if route == "continue" else "source")
        elif current == "source":
            self._set_extract_workflow_step("entry")

    def _go_to_next_extract_step(self):
        current = self._get_extract_workflow_step()
        route = self._get_extract_entry_mode()
        has_preview = bool(str(self.preview_dir_var.get() or "").strip())

        if current == "entry":
            if route == "continue":
                if not self._use_z2_source_on_demand(notify_on_failure=True, advance_to_start=True):
                    try:
                        self.extract_entry_mode_var.set("")
                    except Exception:
                        pass
                    self._set_extract_workflow_step("entry")
            elif route == "manual":
                self._set_extract_workflow_step("source")
            return

        if current != "source":
            return

        if route == "continue":
            self._set_extract_workflow_step("start")
            return

        validation = self._refresh_source_binding_status(allow_autofind=True)
        if validation.get("ok") or has_preview:
            self._set_extract_workflow_step("start")

    def _get_step3_extract_workflow_view_model(self) -> Step3ExtractWorkflowViewModel:
        current = self._get_extract_workflow_step()
        route = self._get_extract_entry_mode()
        source_ready = bool(getattr(self, "_extract_last_source_binding_result", {}).get("ok"))
        has_preview = bool(str(self.preview_dir_var.get() or "").strip())
        has_run = bool(str(self.annotation_run_dir_var.get() or "").strip())
        linear_mode = bool(getattr(self, "_step3_linear_mode", False))
        candidate = self._get_preferred_z2_source_candidate()
        step3_status = ""
        if linear_mode:
            try:
                from ..campaign_manager import CAMPAIGN
                step3_status = str(CAMPAIGN.get_step3_status() or "").strip().lower()
            except Exception:
                step3_status = ""

        if linear_mode and step3_status == "needs_rework":
            source_intro = (
                "Wróciłeś do etapu 3 po poprawkach tablic w Z2. Z3 nadal pracuje na tej samej iteracji "
                "i użyje odświeżonego źródła tablic automatycznie."
            )
            source_hint = (
                "Nie musisz ponownie wskazywać runu, XML ani folderu obrazów. "
                "W tym kroku przebudujesz tylko paczkę tablic potrzebną do dalszej pracy nad znakami."
            )
        elif linear_mode:
            source_intro = (
                "Kampania ma już przypięte źródło tablic dla tego etapu. "
                "Nie musisz ręcznie wybierać runu Z2 ani przepisywać ścieżek."
            )
            source_hint = (
                "Gdy źródło tablic będzie spójne, Z3 samo przygotuje paczkę tablic dla PZ2."
            )
        elif route == "continue":
            source_intro = "Najpierw wybierz run anotacji Z2. Możesz skorzystac z ostatniego źródła z Z2 albo wskazać folder runu anotacji ręcznie."
            source_hint = "Wybrane pola XML i obrazów są wypelniane na Twoje polecenie z runu anotacji Z2, ale w razie potrzeby możesz je skorygowac."
        else:
            source_intro = "W tym trybie wskazujesz annotations.xml oraz oryginalny katalog obrazów. System dopilnuje zgodnosci XML z katalogiem."
            source_hint = "Po wskazaniu XML mogę dodatkowo sprobowac dopasowac katalog obrazów z Workspace/1_raw_images/."

        if linear_mode:
            if has_preview:
                start_hint = (
                    "Paczka tablic dla znaków jest już odświeżona. "
                    "Za chwilę otwieram PZ2, aby kontynuować OCR i korektę znaków."
                )
            elif source_ready:
                start_hint = (
                    "Źródło tablic tej iteracji jest już gotowe. "
                    "Wyodrębnianie uruchomi się automatycznie i odświeży paczkę tablic dla PZ2."
                )
            else:
                start_hint = (
                    "Czekam na spójne źródło tablic dla tej iteracji. "
                    "Gdy będzie gotowe, ponowne wycinanie uruchomi się automatycznie."
                )
        elif route == "continue":
            if has_run and source_ready:
                run_name = Path(str(self.annotation_run_dir_var.get() or "")).name
                start_hint = (
                    f"Źródła z ostatniego runu anotacji Z2 ({run_name}) zostały uzupelnione automatycznie. "
                    "Możesz od razu uruchomic wyodrebnianie tablic do PZ2."
                )
            else:
                start_hint = (
                    "Przy tej sciezce źródła z Z2 są uzupelniane automatycznie. "
                    "Jesli ostatni run anotacji Z2 nie jest gotowy, wróć i wybierz wskazanie anotacji ręcznie."
                )
        else:
            start_hint = (
                "Źródła są gotowe. Możesz uruchomic wyodrebnianie i przygotować katalog wyodrebnionych tablic do PZ2."
                if source_ready
                else "Najpierw potwierdz zgodnosc zrodel, a potem uruchom wyodrebnianie."
            )

        if linear_mode and step3_status == "needs_rework":
            run_hint = (
                "Źródło tablic dla tej iteracji jest już podpięte automatycznie. "
                "Po tym kroku odświeżysz paczkę tablic, a potem wrócisz do OCR i korekty znaków."
            )
            run_hint_tone = "success"
        elif linear_mode:
            run_hint = "Źródło tablic dla tej iteracji jest obsługiwane automatycznie przez kampanię."
            run_hint_tone = "success"
        elif route == "continue":
            if has_run:
                run_name = Path(str(self.annotation_run_dir_var.get() or "")).name
                run_hint = f"Wybrany run anotacji: {run_name}. Na jego podstawie uzupelnisz annotations.xml i katalog obrazów."
                run_hint_tone = "success"
            elif candidate:
                run_hint = (
                    f"Dostepne jest {candidate.get('label', 'źródło z Z2')}. "
                    "Kliknij 'Uzyj źródła z Z2', aby wypelnic pola."
                )
                run_hint_tone = "muted"
            else:
                run_hint = (
                    "Gdy zakonczysz Z2 albo masz otwarty run anotacji w zakładce autoanotacji, kliknij "
                    "'Uzyj źródła z Z2' zamiast przepisywac ścieżki ręcznie."
                )
                run_hint_tone = "muted"
        else:
            run_hint = "Ten tryb nie wymaga folderu runu anotacji. Wystarczy annotations.xml oraz zgodny katalog obrazów."
            run_hint_tone = "muted"

        step_state = {
            "entry": "done" if route else "active",
            "source": "active",
            "start": "pending",
        }
        if source_ready:
            step_state["source"] = "done"
            step_state["start"] = "done" if has_preview else "active"

        if linear_mode:
            source_title = "Potwierdź źródło tablic"
            start_title = "Przebuduj paczkę tablic"
            entry_card_description = "Kampania prowadzi ten etap na gotowym źródle tablic."
            source_card_description = "Źródło tablic tej iteracji jest obsługiwane automatycznie."
            start_card_description = (
                "Paczka tablic dla PZ2 jest już odświeżona." if has_preview
                else "Odśwież paczkę tablic, aby wrócić do OCR i korekty znaków."
            )
        else:
            source_title = "Źródła wejscia"
            start_title = "Uruchom wyodrebnianie"
            entry_card_description = (
                "Kontynuacja po runie anotacji Z2." if route == "continue"
                else "Wskazesz annotations.xml i obrazy."
            )
            source_card_description = (
                "Run anotacji jest gotowy do podpiecia." if route == "continue" and has_run
                else "Powiaz annotations.xml z katalogiem obrazów."
            )
            start_card_description = (
                "Katalog wyodrebnionych tablic do PZ2 jest już gotowy." if has_preview
                else "Wytnij tablice i przygotuj preview do PZ2."
            )

        next_enabled = False
        if current == "entry":
            next_enabled = bool(route)
        elif current == "source":
            next_enabled = bool(route and (source_ready or has_preview))

        return Step3ExtractWorkflowViewModel(
            route=route,
            current_step=current,
            linear_mode=linear_mode,
            show_entry=(current == "entry" and not linear_mode),
            show_source=(current == "source" and (route == "manual" or linear_mode)),
            show_start=(current == "start" or (linear_mode and current == "entry")),
            source_title=source_title,
            start_title=start_title,
            source_intro=source_intro,
            source_hint=source_hint,
            run_hint=run_hint,
            run_hint_tone=run_hint_tone,
            start_hint=start_hint,
            start_hint_tone=("success" if source_ready else "muted"),
            show_step_nav=current in {"source", "start"},
            prev_enabled=current in {"source", "start"},
            next_enabled=next_enabled,
            next_visible=current != "start",
            show_tab_nav=not linear_mode,
            show_back_nav=False,
            show_detect_nav=not linear_mode,
            clear_detect_emphasis=not linear_mode,
            step_cards=[
                Step3ExtractStepCardViewModel(
                    key="entry",
                    state=str(step_state.get("entry", "pending")),
                    title="Wybierz wejście",
                    description=entry_card_description,
                ),
                Step3ExtractStepCardViewModel(
                    key="source",
                    state=str(step_state.get("source", "pending")),
                    title="Potwierdź źródła",
                    description=source_card_description,
                ),
                Step3ExtractStepCardViewModel(
                    key="start",
                    state=str(step_state.get("start", "pending")),
                    title="Uruchom wyodrebnianie",
                    description=start_card_description,
                ),
            ],
        )

    def _refresh_extract_step_nav_buttons(self, vm: Step3ExtractWorkflowViewModel | None = None):
        workflow_vm = vm or self._get_step3_extract_workflow_view_model()
        nav_row = getattr(self, "extract_step_nav_row", None)
        prev_btn = getattr(self, "extract_step_back_btn", None)
        next_btn = getattr(self, "extract_step_next_btn", None)
        main_nav_panel = getattr(self, "extract_main_nav_panel", None)
        back_btn = getattr(self, "btn_back_to_wizard_step3", None)
        detect_frame = getattr(self, "btn_to_detect_frame", None)

        if prev_btn is not None:
            try:
                prev_btn.config(state=tk.NORMAL if workflow_vm.prev_enabled else tk.DISABLED)
            except Exception:
                pass

        if next_btn is not None:
            try:
                next_btn.config(state=tk.NORMAL if workflow_vm.next_enabled else tk.DISABLED)
            except Exception:
                pass

            try:
                if not workflow_vm.next_visible:
                    if str(next_btn.winfo_manager()):
                        next_btn.pack_forget()
                elif not str(next_btn.winfo_manager()):
                    next_btn.pack(side=tk.LEFT, padx=(8, 0))
            except Exception:
                pass

        if back_btn is not None:
            try:
                if workflow_vm.show_back_nav:
                    if not str(back_btn.winfo_manager()):
                        back_btn.grid(row=0, column=0, sticky="w")
                elif str(back_btn.winfo_manager()):
                    back_btn.grid_remove()
            except Exception:
                pass

        if detect_frame is not None:
            try:
                if not workflow_vm.show_detect_nav:
                    if str(detect_frame.winfo_manager()):
                        detect_frame.grid_remove()
                elif not str(detect_frame.winfo_manager()):
                    detect_frame.grid(row=0, column=2, sticky="e")
            except Exception:
                pass

        try:
            if nav_row is not None and str(nav_row.winfo_manager()):
                nav_row.pack_forget()
            if main_nav_panel is not None and str(main_nav_panel.winfo_manager()):
                main_nav_panel.grid_remove()

            if workflow_vm.show_step_nav and nav_row is not None:
                nav_row.pack(fill=tk.X, pady=(0, 8))

            if workflow_vm.show_tab_nav and main_nav_panel is not None:
                main_nav_panel.grid()
        except Exception:
            pass

        if workflow_vm.clear_detect_emphasis:
            try:
                self._set_button_emphasis("btn_to_detect_frame", False)
            except Exception:
                pass
        try:
            self._refresh_campaign_step3_navigation_visibility()
        except Exception:
            pass

    def _bind_extract_entry_card(self, card_widget, mode: str):
        def _select(_event=None, selected_mode=mode):
            self._handle_extract_entry_selection(selected_mode)
            return "break"

        def _hover(enabled: bool):
            self._extract_entry_hover_mode = mode if enabled else None
            self._refresh_extract_entry_cards()

        for widget in card_widget.winfo_children():
            self._bind_extract_entry_card(widget, mode)

        try:
            card_widget.bind("<Button-1>", _select, add="+")
            card_widget.bind("<Enter>", lambda _event: _hover(True), add="+")
            card_widget.bind("<Leave>", lambda _event: _hover(False), add="+")
        except Exception:
            pass

    def _refresh_extract_entry_cards(self):
        cards = getattr(self, "_extract_entry_cards", {}) or {}
        if not cards:
            return

        palette = getattr(self.app, "palette", {})
        selected_mode = self._get_extract_entry_mode()
        hover_mode = getattr(self, "_extract_entry_hover_mode", None)
        panel = palette.get("panel", "#252526")
        panel_alt = palette.get("panel_alt", "#2d2d30")
        hover_bg = palette.get("button_hover", panel_alt)
        border = palette.get("panel_border", palette.get("border", "#3c3c3c"))
        fg = palette.get("fg", "#f3f3f3")
        muted = palette.get("muted", "#c7c7c7")
        selected_bg = blend_hex_colors(panel_alt, hover_bg, 0.42)

        for mode, widgets in cards.items():
            is_selected = mode == selected_mode
            is_hovered = mode == hover_mode
            card_bg = selected_bg if is_selected else (hover_bg if is_hovered else panel_alt)
            border_color = border
            title_fg = fg
            desc_fg = fg if is_selected else muted
            badge_fg = fg if is_selected else muted

            for widget_name in ("frame", "badge", "title", "desc"):
                widget = widgets.get(widget_name)
                if widget is None:
                    continue
                try:
                    widget.configure(bg=card_bg, highlightbackground=border_color, highlightcolor=border_color)
                except Exception:
                    pass

            try:
                widgets["badge"].configure(fg=badge_fg)
            except Exception:
                pass
            try:
                widgets["title"].configure(fg=title_fg)
            except Exception:
                pass
            try:
                widgets["desc"].configure(fg=desc_fg)
            except Exception:
                pass

    def _register_extract_step_card(self, parent, key: str, number: str, title: str, description: str):
        card = tk.Frame(parent, bd=0, highlightthickness=1, padx=14, pady=12)
        card.grid_columnconfigure(0, weight=0)
        card.grid_columnconfigure(1, weight=1)

        badge = tk.Label(
            card,
            text=number,
            width=3,
            anchor="center",
            justify=tk.CENTER,
            font=("Segoe UI", 10, "bold"),
            bd=0,
            highlightthickness=0,
        )
        badge.grid(row=0, column=0, rowspan=2, sticky="nw", padx=(0, 10))

        title_lbl = tk.Label(
            card,
            text=title,
            anchor="w",
            justify=tk.LEFT,
            font=("Segoe UI", 10, "bold"),
            bd=0,
            highlightthickness=0,
        )
        title_lbl.grid(row=0, column=1, sticky="ew")

        desc_lbl = tk.Label(
            card,
            text=description,
            anchor="w",
            justify=tk.LEFT,
            wraplength=220,
            bd=0,
            highlightthickness=0,
        )
        desc_lbl.grid(row=1, column=1, sticky="ew", pady=(6, 0))

        self._extract_step_cards.append(
            {
                "key": key,
                "frame": card,
                "badge": badge,
                "title": title_lbl,
                "desc": desc_lbl,
                "number": number,
                "default_title": title,
                "default_desc": description,
            }
        )
        return card

    def _refresh_extract_step_cards(self, vm: Step3ExtractWorkflowViewModel | None = None):
        cards = getattr(self, "_extract_step_cards", []) or []
        if not cards:
            return

        palette = getattr(self.app, "palette", {})
        panel = palette.get("panel", "#252526")
        panel_alt = palette.get("panel_alt", "#2d2d30")
        hover_bg = palette.get("button_hover", panel_alt)
        border = palette.get("panel_border", palette.get("border", "#3c3c3c"))
        fg = palette.get("fg", "#f3f3f3")
        muted = palette.get("muted", "#c7c7c7")
        active_bg = blend_hex_colors(panel_alt, hover_bg, 0.42)
        done_bg = blend_hex_colors(panel_alt, hover_bg, 0.18)
        workflow_vm = vm or self._get_step3_extract_workflow_view_model()
        step_cards_by_key = {
            str(card.key or ""): card
            for card in list(getattr(workflow_vm, "step_cards", []) or [])
        }

        for entry in cards:
            key = str(entry.get("key") or "").strip()
            card_vm = step_cards_by_key.get(key)
            state = str(getattr(card_vm, "state", "pending") or "pending")
            frame = entry.get("frame")
            badge = entry.get("badge")
            title_lbl = entry.get("title")
            desc_lbl = entry.get("desc")

            if state == "done":
                card_bg = done_bg
                border_color = border
                badge_fg = fg
                title_fg = fg
                desc_fg = fg
            elif state == "active":
                card_bg = active_bg
                border_color = border
                badge_fg = fg
                title_fg = fg
                desc_fg = fg
            else:
                card_bg = panel_alt
                border_color = border
                badge_fg = muted
                title_fg = fg
                desc_fg = muted

            for widget in (frame, badge, title_lbl, desc_lbl):
                if widget is None:
                    continue
                try:
                    widget.configure(bg=card_bg, highlightbackground=border_color, highlightcolor=border_color)
                except Exception:
                    pass

            try:
                badge.configure(fg=badge_fg)
            except Exception:
                pass
            try:
                title_lbl.configure(
                    fg=title_fg,
                    text=str(getattr(card_vm, "title", "") or entry.get("default_title", "")),
                )
            except Exception:
                pass
            try:
                desc_lbl.configure(
                    fg=desc_fg,
                    text=str(getattr(card_vm, "description", "") or entry.get("default_desc", "")),
                )
            except Exception:
                pass

    @staticmethod
    def _paths_equivalent(left, right) -> bool:
        if not left or not right:
            return False
        try:
            return Path(left).resolve() == Path(right).resolve()
        except Exception:
            try:
                return str(Path(left)) == str(Path(right))
            except Exception:
                return False

    def _resolve_existing_annotation_run_dir(self, candidate) -> Path | None:
        raw = str(candidate or "").strip()
        if not raw:
            return None

        try:
            path = Path(raw)
        except Exception:
            return None

        if path.suffix.lower() == ".xml":
            path = path.parent

        try:
            if not path.exists() or not path.is_dir():
                return None
        except Exception:
            return None

        return path if (path / "annotations.xml").exists() else None

    def _annotation_run_manifest_path(self, run_dir: Path) -> Path:
        return Path(run_dir) / "run_manifest.json"

    def _load_annotation_run_manifest(self, run_dir: Path) -> dict:
        manifest_path = self._annotation_run_manifest_path(run_dir)
        payload = PROJECT_CACHE.load_json(manifest_path, default={})
        return payload if isinstance(payload, dict) else {}

    def _get_campaign_iteration_artifact_bundle(self) -> dict:
        if not CAMPAIGN.get_active_project_name():
            return {}

        try:
            iteration_num = int(CAMPAIGN.get_current_iteration_num() or 1)
        except Exception:
            iteration_num = 1

        package_images_dir = CAMPAIGN.get_master_pool_dir() or CAMPAIGN.get_iteration_raw_dir(iteration_num)
        if package_images_dir is None:
            return {}

        try:
            return dict(
                CAMPAIGN.get_iteration_artifact_bundle(
                    images_dir=package_images_dir,
                    iteration_num=iteration_num,
                ) or {}
            )
        except Exception:
            return {}

    def _get_registry_preferred_step3_source_candidate(self) -> dict | None:
        bundle = self._get_campaign_iteration_artifact_bundle()
        if not bundle:
            return None

        candidate_specs = [
            (
                "step3_extract_source",
                dict(bundle.get("step3_extract_source") or {}),
                "zapisane źródło etapu Z3",
                "annotation_run_dir",
            ),
            (
                "char_effective_source",
                dict(bundle.get("char_effective_source") or {}),
                "gotowe źródło znaków z rejestru",
                "run_dir",
            ),
            (
                "plate_source",
                dict(bundle.get("plate_source") or {}),
                "źródło tablic z rejestru projektu",
                "run_dir",
            ),
        ]

        for _scope_name, raw_entry, label, run_key in candidate_specs:
            run_dir = str(raw_entry.get(run_key) or "").strip()
            xml_path = str(raw_entry.get("xml_path") or "").strip()
            images_dir = str(raw_entry.get("images_dir") or "").strip()
            if not any((run_dir, xml_path, images_dir)):
                continue
            try:
                run_name = Path(run_dir).name if run_dir else ""
            except Exception:
                run_name = ""
            return {
                "run_dir": run_dir,
                "xml_path": xml_path,
                "images_dir": images_dir,
                "label": f"{label}: {run_name}" if run_name else label,
            }

        return None

    def _get_annotation_tab(self):
        try:
            return getattr(self.app, "tabs", {}).get("annotation")
        except Exception:
            return None

    def _get_annotation_run_input_dir(self, run_dir: Path | None) -> Path | None:
        if run_dir is None:
            return None

        manifest = self._load_annotation_run_manifest(run_dir)
        input_dir_raw = str(manifest.get("input_dir") or "").strip()
        if input_dir_raw:
            try:
                input_dir = Path(input_dir_raw)
                if input_dir.exists() and input_dir.is_dir():
                    return input_dir
            except Exception:
                pass

        annotation_tab = self._get_annotation_tab()
        if annotation_tab is not None:
            try:
                current_run = getattr(annotation_tab, "current_annotation_run_dir", None)
                if self._paths_equivalent(run_dir, current_run):
                    current_input = getattr(annotation_tab, "current_input_dir", None)
                    if current_input is not None and Path(current_input).exists():
                        return Path(current_input)
            except Exception:
                pass

        pending_images = str(getattr(self, "_pending_z2_source", {}).get("images_dir") or "").strip()
        pending_run = str(getattr(self, "_pending_z2_source", {}).get("run_dir") or "").strip()
        if pending_images and pending_run and self._paths_equivalent(run_dir, pending_run):
            try:
                pending_input = Path(pending_images)
                if pending_input.exists() and pending_input.is_dir():
                    return pending_input
            except Exception:
                pass

        return None

    def _apply_annotation_run_source(self, run_dir: Path | None, *, refresh_status: bool = True) -> bool:
        safe_run_dir = self._resolve_existing_annotation_run_dir(run_dir)
        if safe_run_dir is None:
            return False

        input_dir = self._get_annotation_run_input_dir(safe_run_dir)
        self._source_binding_sync_in_progress = True
        try:
            self.annotation_run_dir_var.set(str(safe_run_dir))
            self.xml_path_var.set(str(safe_run_dir / "annotations.xml"))
            if input_dir is not None:
                self.images_dir_var.set(str(input_dir))
        finally:
            self._source_binding_sync_in_progress = False

        try:
            self._force_save_all()
        except Exception:
            pass

        if refresh_status:
            self._schedule_source_binding_refresh(delay_ms=0)
        self._refresh_extract_workflow_ui()
        return True

    def set_pending_z2_annotation_source(self, *, xml_path: str = "", images_dir: str = "", run_dir: str = ""):
        candidate_run = str(run_dir or "").strip()
        candidate_xml = str(xml_path or "").strip()
        candidate_images = str(images_dir or "").strip()

        if not candidate_run and candidate_xml:
            try:
                candidate_run = str(Path(candidate_xml).parent)
            except Exception:
                candidate_run = ""

        self._pending_z2_source = {
            "run_dir": candidate_run,
            "xml_path": candidate_xml,
            "images_dir": candidate_images,
        }
        self._refresh_extract_workflow_ui()

    def _pick_annotation_run_dir(self):
        initial_dir = ""
        try:
            initial_dir = str(CAMPAIGN.get_dir("auto_ann") or "")
        except Exception:
            initial_dir = ""
        if not initial_dir:
            initial_dir = str(Path(CONFIG.get_auto_annotations_dir("plate")).absolute())

        selected = filedialog.askdirectory(
            initialdir=initial_dir,
            title="Wskaż folder runu anotacji z annotations.xml",
        )
        if not selected:
            return

        if not self._apply_annotation_run_source(Path(selected)):
            messagebox.showwarning(
                "Błędny run anotacji",
                "Wybrany folder nie zawiera pliku annotations.xml, wiec nie może być zrodlem dla PZ1.",
            )

    def _get_preferred_z2_source_candidate(self) -> dict | None:
        pending = dict(getattr(self, "_pending_z2_source", {}) or {})
        if any(str(pending.get(key) or "").strip() for key in ("run_dir", "xml_path", "images_dir")):
            run_dir = str(pending.get("run_dir") or "").strip()
            label = (
                f"ostatni run anotacji Z2: {Path(run_dir).name}"
                if run_dir else "ostatnie źródło z runu anotacji Z2"
            )
            pending["label"] = label
            return pending

        annotation_tab = self._get_annotation_tab()
        if annotation_tab is not None:
            try:
                getter = getattr(annotation_tab, "_get_preferred_annotation_run_dir", None)
                run_dir = getter(require_xml=True) if callable(getter) else None
            except Exception:
                run_dir = None

            try:
                xml_path = getattr(annotation_tab, "current_annotation_xml_path", None)
                if not xml_path and run_dir is not None:
                    xml_path = run_dir / "annotations.xml"
            except Exception:
                xml_path = run_dir / "annotations.xml" if run_dir is not None else None

            try:
                images_dir = getattr(annotation_tab, "current_input_dir", None)
            except Exception:
                images_dir = None

            if run_dir is not None or xml_path is not None or images_dir is not None:
                return {
                    "run_dir": str(run_dir or ""),
                    "xml_path": str(xml_path or ""),
                    "images_dir": str(images_dir or ""),
                    "label": (
                        f"aktywny run anotacji Z2: {Path(run_dir).name}"
                        if run_dir is not None else "biezace źródło z runu anotacji Z2"
                    ),
                }

        registry_candidate = self._get_registry_preferred_step3_source_candidate()
        if registry_candidate:
            return registry_candidate

        try:
            stored_source = CAMPAIGN.get_last_plate_manual_source()
        except Exception:
            stored_source = {}

        if stored_source:
            run_dir = str(stored_source.get("source_run_path") or "").strip()
            xml_path = str(stored_source.get("source_xml_path") or "").strip()
            images_dir = str(stored_source.get("source_input_path") or "").strip()
            if run_dir or xml_path or images_dir:
                return {
                    "run_dir": run_dir,
                    "xml_path": xml_path,
                    "images_dir": images_dir,
                    "label": (
                        f"ostatnio zapisany run anotacji Z2: {Path(run_dir).name}"
                        if run_dir else "ostatnio zapisane źródło z runu anotacji Z2"
                    ),
                }

        return None

    def _use_z2_source_on_demand(self, *, notify_on_failure: bool = True, advance_to_start: bool = False) -> bool:
        candidate = self._get_preferred_z2_source_candidate()
        if not candidate:
            if notify_on_failure:
                messagebox.showinfo(
                    "Brak źródła z Z2",
                    "Nie znalazlem gotowego źródła z Z2. Otwórz run anotacji Z2 albo wskaż folder runu anotacji ręcznie.",
                )
            return False

        run_dir = self._resolve_existing_annotation_run_dir(candidate.get("run_dir") or candidate.get("xml_path"))
        self._set_extract_entry_mode("continue")
        if run_dir is not None:
            self._apply_annotation_run_source(run_dir, refresh_status=False)

        self._source_binding_sync_in_progress = True
        try:
            if candidate.get("xml_path"):
                self.xml_path_var.set(str(candidate.get("xml_path")))
            if candidate.get("images_dir"):
                self.images_dir_var.set(str(candidate.get("images_dir")))
            if run_dir is None and candidate.get("run_dir"):
                self.annotation_run_dir_var.set(str(candidate.get("run_dir")))
        finally:
            self._source_binding_sync_in_progress = False

        try:
            self._force_save_all()
        except Exception:
            pass
        validation = self._refresh_source_binding_status(allow_autofind=True)
        success = bool(validation.get("ok"))

        if advance_to_start and success:
            self._set_extract_workflow_step("start")
        elif advance_to_start and not success:
            if notify_on_failure:
                messagebox.showwarning(
                    "Nie mogę kontynuowac z Z2",
                    validation.get("message", "Nie udało się automatycznie potwierdzić zrodel z ostatniego runu anotacji Z2."),
                )
            return False
        else:
            self._refresh_extract_workflow_ui()

        return success

    def _refresh_extract_workflow_ui(self):
        workflow_vm = self._get_step3_extract_workflow_view_model()
        route = workflow_vm.route

        try:
            if hasattr(self, "extract_source_title_lbl"):
                self.extract_source_title_lbl.configure(text=workflow_vm.source_title)
            if hasattr(self, "extract_start_title_lbl"):
                self.extract_start_title_lbl.configure(text=workflow_vm.start_title)
        except Exception:
            pass

        def _set_section_visibility(widget, visible: bool, **pack_kwargs):
            if widget is None:
                return
            try:
                if visible:
                    if not str(widget.winfo_manager()):
                        widget.pack(**pack_kwargs)
                elif str(widget.winfo_manager()):
                    widget.pack_forget()
            except Exception:
                pass

        _set_section_visibility(
            getattr(self, "extract_entry_section", None),
            workflow_vm.show_entry,
            fill=tk.X,
        )
        _set_section_visibility(
            getattr(self, "extract_source_section", None),
            workflow_vm.show_source,
            fill=tk.X,
            pady=(18, 0),
        )
        _set_section_visibility(
            getattr(self, "extract_start_section", None),
            workflow_vm.show_start,
            fill=tk.X,
            pady=(18, 0),
        )

        if hasattr(self, "extract_continue_source_frame"):
            try:
                if route == "continue" and workflow_vm.show_source:
                    if not str(self.extract_continue_source_frame.winfo_manager()):
                        self.extract_continue_source_frame.pack(
                            fill=tk.X,
                            pady=(0, 12),
                            before=getattr(self, "extract_source_fields_frame", None),
                        )
                elif str(self.extract_continue_source_frame.winfo_manager()):
                    self.extract_continue_source_frame.pack_forget()
            except Exception:
                pass

        if hasattr(self, "extract_source_intro_lbl"):
            self._set_inline_status_label_state(
                self.extract_source_intro_lbl,
                text=workflow_vm.source_intro,
                tone="muted",
                emphasis=False,
            )
        if hasattr(self, "extract_source_fields_hint_lbl"):
            self._set_inline_status_label_state(
                self.extract_source_fields_hint_lbl,
                text=workflow_vm.source_hint,
                tone="muted",
                emphasis=False,
            )
        if hasattr(self, "extract_run_hint_lbl"):
            self._set_inline_status_label_state(
                self.extract_run_hint_lbl,
                text=workflow_vm.run_hint,
                tone=workflow_vm.run_hint_tone,
                emphasis=False,
            )
        if hasattr(self, "extract_start_hint_lbl"):
            self._set_inline_status_label_state(
                self.extract_start_hint_lbl,
                text=workflow_vm.start_hint,
                tone=workflow_vm.start_hint_tone,
                emphasis=False,
            )

        self._refresh_extract_entry_cards()
        self._refresh_extract_step_cards(workflow_vm)
        self._refresh_extract_step_nav_buttons(workflow_vm)


